INSERT INTO "analysis_memo" VALUES('f7bbd69804d9c16f924166a1bf21e6c6a22f3f0f6faa0d2b62e63ea929ab375b','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект регулирует профессию диетолога: вводит право выполнения профессии, реестр и профессиональное самоуправление (Krajowa Izba Dietetyków). Для иностранцев как таковых он ничего не меняет, кроме общих правил признания квалификаций из ЕС/ЕЭЗ/Швейцарии.","key_changes":["Введение обязательного права выполнения профессии диетолога и реестра","Признание дипломов из ЕС/ЕЭЗ/Швейцарии и стран вне ЕС по общим правилам","Требование знания польского языка на уровне B2 для лиц без польского гражданства","Возможность временного и окказионального оказания услуг диетологами из ЕС/ЕЭЗ","При заявлении требуется документ, подтверждающий право пребывания в Польше"],"affected_groups":["иностранцы с дипломом диетолога","специалисты из стран ЕС/ЕЭЗ/Швейцарии","диетологи с дипломами из третьих стран"],"practical_impact":"Иностранец, желающий работать диетологом в Польше, должен будет подтвердить квалификацию, знание польского на уровне B2, приложить документ о праве пребывания и получить право выполнения профессии; сам статус пребывания законопроект не меняет.","effective_date":"1 января 2027 г., за исключением ст. 23–28 и ст. 10 п. 1, 2 и 4 — через 36 месяцев со дня опубликования","confidence":0.8,"rationale":"Законопроект касается регулирования профессии в целом; иностранцы упоминаются лишь в контексте признания квалификаций и языкового требования, что не меняет условий их пребывания или трудоустройства как таковых.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":290493,"truncated":false,"text_source":"pdf","created_at":"2026-09-17T19:46:28Z","input_tokens":144600,"output_tokens":622,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3126/3126.pdf","source_kind":"print","revision":1,"text_sha256":"b0e16463e3e5b28d5492452462d95d52417194eab2452557d16b2542e3396dec","source_checked_at":"2026-09-17T19:46:28Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('f725583e82f844458d58d9d909efc5108422591f9c9c82a8b6560057338aee29','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект меняет Prawo ochrony środowiska (закон об охране окружающей среды): звук колоколов и звукоусиливающих систем религиозного культа выводится из-под норм шума и решений о допустимом уровне шума. Для иностранцев никаких правовых последствий нет.","key_changes":["Исключение систем нагłaśniających религиозного культа из решений о допустимом уровне шума (art. 115a ust. 2)","Запрет на использование звукоусиливающих устройств в общественных местах не применяется к практике религиозного культа (art. 156 ust. 2)"],"affected_groups":["приходы и религиозные общины","жители домов рядом с храмами"],"practical_impact":"Ничего не меняется в вопросах пребывания, работы или социальных прав иностранцев; изменение касается только шума от религиозных объектов.","effective_date":"Через 14 дней после публикации.","confidence":0.95,"rationale":"Тема — шум от церковных колоколов; иностранцы упомянуты лишь риторически в обосновании, правовых последствий для них нет.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":18591,"truncated":false,"text_source":"pdf","created_at":"2026-09-17T19:46:37Z","input_tokens":9214,"output_tokens":408,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-31346-2026/$file/10-RPW-31346-2026.pdf","source_kind":"print","revision":1,"text_sha256":"cd7a7425e388f5525a3ab2097f03939e9d5e158eb9092f2cdc2bf31741cfead3","source_checked_at":"2026-09-17T19:46:37Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('0d2742c9b566fe6075a45ed378a660a1a58c9af2643abf652dfc968c71f3caa4','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект внедряет европейский кошелёк цифровой идентичности (EUDI Wallet) в рамках mObywatel и меняет правила электронной идентификации и доверенных услуг. Кошелёк должны получить все физические лица в Польше, включая иностранцев-резидентов, а не только граждан. Предусмотрены пункты подтверждения личности, в том числе у воеводы.","key_changes":["Министр цифровизации обеспечивает европейский кошелёк цифровой идентичности для физических и юридических лиц","Подтверждение личности возможно у wojewoda, в банке или в органе гмины при личном присутствии","Набор данных кошелька: имя, фамилия, дата и место рождения, PESEL, гражданство, пол, фото","Кошелёк приравнивается к документу, удостоверяющему личность, при очной проверке (с 24.12.2027)","Бесплатная квалифицированная электронная подпись для непрофессиональных целей","Централизованная система сопоставления личности с реестром PESEL для иностранных средств идентификации"],"affected_groups":["иностранцы, постоянно проживающие в Польше","лица с номером PESEL","лица без PESEL, пользующиеся электронной идентификацией из других стран ЕС","юридические лица и предприниматели"],"practical_impact":"Иностранцы-резиденты, не имеющие польского удостоверения личности, смогут получить цифровой кошелёк, подтвердив личность лично в пункте у воеводы, банка или гмины; кошелёк позволит подтверждать личность и подписывать документы онлайн.","effective_date":"Закон вступает в силу 24 декабря 2026 г., с исключениями: часть норм — на следующий день после публикации, отдельные — 31.12.2027, 30.06.2028, 24.12.2027, 31.12.2029 и через 18/24 месяца после публикации","confidence":0.75,"rationale":"Проект не касается легализации пребывания, но прямо предусматривает доступ к цифровой идентичности для резидентов-неграждан и подтверждение личности через воеводу, что даёт косвенное воздействие.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":296222,"truncated":false,"text_source":"documents","created_at":"2026-09-18T09:55:32Z","input_tokens":141318,"output_tokens":773,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12407350/13188189/13188190/dokument791977.zip","source_kind":"rcl","revision":1,"text_sha256":"ed6e19bc686b1886fa0aa33cf222c8cc825c857aea502a54756ef9cc4915b84c","source_checked_at":"2026-09-18T09:55:32Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('ee447f12bc093fedc2e017a32afb0ef39f6348b1605921e52f342a1176f5e46a','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Реформа Krajowy Rejestr Sądowy (судебный реестр): полная электронизация процедур, счета компаний в судебной системе, новые пометки о непредставлении финансовой отчётности и упрощённая ликвидация «мёртвых» фирм. Для иностранцев значение имеет уточнение заявлений о статусе cudzoziemiec при покупке долей и акций.","key_changes":["Заявитель обязан указать, является ли приобретатель долей/акций cudzoziemcem по ustawa z 1920 r. o nabywaniu nieruchomości","При статусе cudzoziemca — дополнительное заявление о наличии у компании недвижимости в Польше","Обязательное наличие правового титула на помещение по адресу siedziby и приложение документа к заявке","Все заявления и письма в реестровый суд — только через teleinformatyczny счёт компании","Новая пометка в KRS о непредставлении финансовых документов; через год — роспуск фирмы без ликвидации"],"affected_groups":["иностранцы — участники и акционеры польских компаний","иностранные предприниматели, регистрирующие компании в KRS","фонды и объединения с иностранным участием"],"practical_impact":"Иностранцу, покупающему доли или акции польской компании, придётся точнее декларировать свой статус и наличие недвижимости у фирмы; при регистрации или смене адреса потребуется документ о праве на помещение, а вся переписка с судом пойдёт через электронный счёт компании.","effective_date":"Закон вступает в силу 1 октября 2027 г., за исключением отдельных норм о пометке о непредставлении финансовых документов — с 1 октября 2028 г.","confidence":0.85,"rationale":"Закон касается реестра предпринимателей, а иностранцы затрагиваются лишь косвенно — через заявления о статусе cudzoziemca при приобретении долей и общие правила для компаний.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":188666,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:07:34Z","input_tokens":94070,"output_tokens":1006,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3004/3004.pdf","source_kind":"print","revision":1,"text_sha256":"6de93675eb8a39b3ebdbc22f6ce78a830901c2feeeaca7cc1938b70d36843812","source_checked_at":"2026-09-18T19:07:34Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('3f091b012cf8c832c7f583b9acc432bc0209e0cd6071475e1e17a75522d0898a','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект меняет правила информирования участников уголовного процесса (обвиняемых, потерпевших, свидетелей) об их правах. Образцы таких уведомлений будут утверждены министром и опубликованы на сайте Ministerstwo Sprawiedliwości вместе с переводами на иностранные языки, чаще всего используемые в уголовных делах.","key_changes":["Единые образцы письменных pouczeń для обвиняемых, потерпевших, свидетелей на судебной стадии","Публикация образцов на сайте MS с переводом на самые частые иностранные языки","Расширение информирования задержанного о праве и сроке требовать компенсацию за необоснованное задержание","Аналогичное информирование при tymczasowe aresztowanie и при необоснованном осуждении","Свидетелю сообщат о праве на помощь представителя и о возможности допроса консулом"],"affected_groups":["иностранцы — участники уголовного процесса в Польше","задержанные и арестованные иностранцы","свидетели и потерпевшие, не владеющие польским языком"],"practical_impact":"Иностранец, участвующий в уголовном деле, получит стандартное письменное разъяснение своих прав, доступное в переводе на распространённые иностранные языки, включая информацию о праве на переводчика, адвоката и компенсацию за необоснованное задержание.","effective_date":"Закон вступает в силу 1 января 2027 года; новые нормы применяются также к делам, начатым ранее.","confidence":0.82,"rationale":"Норма касается уголовной процедуры в целом, но прямо предусматривает переводы уведомлений и права неговорящих по-польски, что даёт косвенное значение для иностранцев.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":159462,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:07:27Z","input_tokens":82049,"output_tokens":628,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2997/2997.pdf","source_kind":"print","revision":1,"text_sha256":"4de1a98333983b34fcca93efc8641bdeaa8323d09fbbe52b80ffa5e365197b1b","source_checked_at":"2026-09-18T19:07:27Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('27bbe0f88317802ceab3ef360344ac055b7a341c57d9d37afa91b3e5b231372f','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Законопроект вводит «статус артиста» (status artysty) и доплату государства к взносам ZUS и на медстрахование для людей творческих профессий с низкими доходами. Иностранцы с определёнными видами легального пребывания в Польше прямо включены в круг заявителей.","key_changes":["Статус артиста на 5 лет (после трёх раз — на 8) выдаёт dyrektor Instytucji, решение обжалуется министру","Право подать заявление имеют граждане ЕС/ЕЭЗ/Швейцарии и члены семей с правом пребывания","Иностранцы с pobyt stały, rezydent UE, рядом zezwoleń na pobyt czasowy (в т.ч. ст. 114, 127, 151, 139a), беженцы и лица с доп. защитой — тоже","Исключены лица с разрешением на пребывание и работу до 9 месяцев (или до 6 мес. для научных случаев)","Доплата назначается ZUS при среднем доходе за 3 года не выше 125% годового минимального заработка"],"affected_groups":["граждане ЕС/ЕЭЗ/Швейцарии и члены их семей в Польше","иностранцы с pobyt stały и rezydent długoterminowy UE","обладатели отдельных zezwoleń na pobyt czasowy (работа, ICT, научные исследования)","беженцы и лица с дополнительной защитой","граждане Великобритании по Brexit-соглашению"],"practical_impact":"Иностранцы-творческие работники с подходящим основанием пребывания смогут получить статус артиста и войти в систему ZUS/NFZ, а при низких доходах — государственную доплату к взносам. Заявление на статус подаётся в Instytucję, на доплату — в ZUS электронно через profil informacyjny.","effective_date":"Первый день месяца, следующего за истечением 9 месяцев со дня опубликования.","confidence":0.85,"rationale":"Закон касается социального страхования и взносов, прямо перечисляя категории иностранцев, имеющих право на статус артиста, — это социальная сфера, а не легализация пребывания.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":86933,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:07:51Z","input_tokens":44861,"output_tokens":851,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3082/3082.pdf","source_kind":"committee_report","revision":1,"text_sha256":"ad1e8979d087cde24004e2a6bf74e16d4fd297120c3dececc46f370532e1ef72","source_checked_at":"2026-09-18T19:07:51Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('79f783469271105517ebb6c902d1d5c485f34a8fd61a3021b75fcf2d2470fdd6','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект меняет Уголовно-процессуальный кодекс и связанные законы: доступ к защитнику, права задержанных, порядок временного ареста, право на переводчика для тех, кто не владеет польским. Это общие процессуальные гарантии, а не нормы о пребывании или работе иностранцев.","key_changes":["Расширено право на бесплатного переводчика для обвиняемого, не владеющего польским языком","Право требовать перевода документов, важных для защиты, и жаловаться на качество перевода","Постоянное место жительства в другой стране ЕС приравнено к проживанию в Польше при оценке риска побега","Обязательное участие защитника при допросе подозреваемого младше 18 лет","Доступ задержанного и защитника к материалам, обосновывающим задержание и арест"],"affected_groups":["иностранцы, оказавшиеся подозреваемыми или задержанными в Польше","лица, не владеющие польским языком, в уголовном процессе","граждане других стран ЕС, проживающие за пределами Польши"],"practical_impact":"Иностранец, попавший в уголовный процесс в Польше, получит более широкий доступ к переводчику и защитнику, а проживание в другой стране ЕС больше не будет само по себе основанием считать его склонным к побегу. На легализацию пребывания или работу это не влияет.","effective_date":"Закон вступает в силу по истечении 6 месяцев со дня опубликования.","confidence":0.85,"rationale":"Это реформа уголовного процесса; положения о переводчике и о месте жительства в ЕС касаются иностранцев лишь косвенно и не меняют их статуса пребывания или занятости.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":449323,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:08:02Z","input_tokens":227761,"output_tokens":614,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2802/2802.pdf","source_kind":"print","revision":1,"text_sha256":"1495a1bc2a8b6f5353e9f6670c0d7bc3dcdaf5c4e511d900e692aabe1aeccccb","source_checked_at":"2026-09-18T19:08:02Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('7cd73aed2c10fe0e6913e8bfc97e0e281e2c9e64b70f26d956a16ea8c92eadb7','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект ужесточает условия доплаты пенсии до минимальной из ZUS: помимо возраста и стажа потребуется накопить на пенсионном счёте взносы не ниже 25-кратного минимального вознаграждения (в 2026 г. — около 120 150 zł). Формально касается всех, но по обоснованию нацелен на иностранцев с коротким стажем работы в Польше.","key_changes":["Новое условие в art. 87 ust. 1 ustawy o emeryturach i rentach z FUS для доплаты до минимальной пенсии","Требуется валоризованная сумма взносов на счёте не ниже 25-кратного минимального вознаграждения (~120 150 zł в 2026 г.)","Условия возраста (65/60 лет) и стажа (25/20 лет) сохраняются","Новые правила применяются и к делам, начатым, но не завершённым до вступления в силу","Цель обоснования — ограничить доплаты лицам с минимальным стажем работы в Польше"],"affected_groups":["Иностранцы, работавшие в Польше и получающие пенсию из ZUS","Граждане Украины и других стран с договорами о социальном обеспечении с Польшей","Лица с коротким периодом уплаты взносов в Польше","Граждане Польши с низкими накоплениями в ZUS"],"practical_impact":"Если сумма взносов на счёте в ZUS ниже указанного порога, доплата до минимальной пенсии не будет назначена, даже при достаточном общем стаже с учётом периодов работы за границей. Это касается и заявлений, поданных до вступления закона в силу, но ещё не рассмотренных.","effective_date":"Через 14 дней со дня опубликования","confidence":0.9,"rationale":"Проект напрямую влияет на социальные выплаты (пенсии) иностранцам, работавшим в Польше, но не затрагивает легализацию пребывания или работу.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":38308,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:08:16Z","input_tokens":20036,"output_tokens":700,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-31544-2026/$file/10-RPW-31544-2026.pdf","source_kind":"print","revision":1,"text_sha256":"7aae2f3eaa2548b831721657874f012c71cfa9ad6d26f74c06d1f4b75e9c11e2","source_checked_at":"2026-09-18T19:08:16Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('fc06c8abc44bf2ec45706c79184fe29843ed1978dbcf795d123174c03cf5b776','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект меняет Prawo o notariacie (закон о нотариате) и Kodeks postępowania cywilnego. Для иностранцев значим один пункт: при покупке недвижимости или приобретении долей/акций польской компании нотариальный акт должен содержать сведения о гражданстве и номер PESEL. Остальное касается организации работы нотариусов.","key_changes":["В акте о покупке недвижимости иностранцем указываются гражданство и номер PESEL физлица","Для субъекта с местом нахождения в РП — заявление, является ли он cudzoziemcem, с обоснованием и REGON","Требование распространено и на приобретение долей, акций или прав и обязанностей в польской компании","В akt poświadczenia dziedziczenia добавляются PESEL наследников и REGON юрлиц","Нотариус сможет подавать заявления в księga wieczysta и вне связи с собственной сделкой (платно)"],"affected_groups":["иностранцы, покупающие недвижимость в Польше","иностранцы, приобретающие доли и акции польских компаний","наследники-иностранцы","клиенты нотариальных контор"],"practical_impact":"При сделке с недвижимостью или долями компании нотариус потребует данные о гражданстве и номер PESEL, а при отсутствии однозначности — заявление о статусе cudzoziemca. Дополнительно появится платная возможность подать заявление в земельную книгу через нотариуса.","effective_date":"Через 14 дней после опубликования; изменение ст. 1 п. 23 lit. b (подача заявлений в księga wieczysta) — через 6 месяцев после опубликования.","confidence":0.85,"rationale":"Основная часть проекта касается профессии нотариуса, но есть конкретное новое требование к данным иностранцев в нотариальных актах при сделках с недвижимостью и долями — косвенное влияние.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":128815,"truncated":false,"text_source":"documents","created_at":"2026-09-21T10:53:18Z","input_tokens":61122,"output_tokens":806,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12414851/13227172/13227173/dokument798038.docx","source_kind":"rcl","revision":1,"text_sha256":"abdffc03069000691d48f86368d70d0afb5fb4f86460d0cac453a21aa6c8daba","source_checked_at":"2026-09-21T10:53:18Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('1601068bf49fc0fd5df11b1fac074578a38675857242151e23e947806a52ab90','{"triage":{"affects_foreigners":false,"confidence":0.65,"rationale":"Projekt dotyczy głównie procedur notarialnych i postępowania wieczystoksięgowego (organizacja kancelarii, kadencje samorządu notarialnego, archiwizacja dokumentów), a wzmianka o cudzoziemcach ogranicza się do technicznego obowiązku odnotowania obywatelstwa przy nabywaniu nieruchomości, co nie zmienia praw ani obowiązków cudzoziemców w sposób istotny."},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_tokens":7726,"output_tokens":562,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('22487ee77f4d537b75a66c07298e6f4725f58b53832290b0ecf453b811968d6f','{"analysis":{"relevant":true,"score":4,"category":"employment","summary":"Проект вводит новый закон о стажировках (staże) вместо ustawa o praktykach absolwenckich (закон о выпускных практиках): стажировки становятся обязательно оплачиваемыми, с письменным договором и страхованием. Закон распространяется на граждан ЕС/ЕЭЗ и на иностранцев, перечисленных в ст. 3 ч. 1 ustawa o warunkach dopuszczalności powierzania pracy cudzoziemcom (закон о допустимости поручения работы иностранцам).","key_changes":["Отмена ustawa o praktykach absolwenckich; бесплатные выпускные практики больше невозможны","Круг участников: поляки, граждане ЕС/ЕЭЗ и иностранцы из ст. 3 ч. 1 закона о поручении работы иностранцам","Денежная выплата стажёру: не менее 35% среднего заработка и не выше среднего заработка","Договор о стажировке — письменный, максимум 6 месяцев, срок предупреждения 7 или 14 дней","Стажёр подлежит соцстрахованию как исполнитель zlecenie и медстрахованию NFZ через организатора"],"affected_groups":["граждане ЕС/ЕЭЗ в Польше","иностранцы со свободным доступом к рынку труда по ст. 3 ч. 1 закона о поручении работы иностранцам","граждане Украины, охваченные специальным законом (в части ст. 26)","молодёжь и выпускники, включая несовершеннолетних стажёров"],"practical_impact":"Иностранцы, имеющие доступ к польскому рынку труда, смогут проходить стажировку только по письменному договору и за оплату не ниже 35% среднего заработка, с социальным и медицинским страхованием; бесплатные практики исчезнут. Для иностранцев без такого доступа стажировки по этому закону недоступны.","effective_date":"Закон вступает в силу по истечении 6 месяцев со дня опубликования.","confidence":0.8,"rationale":"Закон прямо определяет круг иностранцев, которым разрешены стажировки, и регулирует условия их оплачиваемого труда, что относится к сфере занятости.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v9","input_chars":96624,"truncated":false,"text_source":"documents","created_at":"2026-09-22T16:00:01Z","input_tokens":49715,"output_tokens":1125,"cache_read_input_tokens":0,"cache_creation_input_tokens":2652,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171166/13171167/dokument749803.pdf","source_kind":"rcl","revision":1,"text_sha256":"96b2a36ffb972cede864176f0bd61797487a2189acea3e6a32c4a293080369d1","source_checked_at":"2026-09-22T16:00:01Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('ac09e4b43838e3b29ce4aeeb55f4f30e1cc5fe32684cc52a17c8f187bf1e7bb8','{"triage":{"affects_foreigners":true,"confidence":0.95,"rationale":"Ustawa o stażach wprost obejmuje swoim zakresem cudzoziemców z UE, EOG oraz innych, którzy mogą korzystać ze swobody przepływu osób lub są objęci przepisami o powierzaniu pracy cudzoziemcom, a także zmienia zasady stażu dla obywateli Ukrainy w ramach ustawy o pomocy obywatelom Ukrainy."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":10562,"output_tokens":174,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('c839d68b9f7e7d36b6c14a475e751d2b84e40ac4969dd39114f9a317e0c027a1','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Закон вводит системную услугу личного ассистента (asystencja osobista) для людей с инвалидностью, финансируемую из госбюджета. Иностранцы с перечисленными видами легального пребывания в Польше получают это право наравне с гражданами. Услуга бесплатна, назначается решением wojewódzki zespół ds. orzekania o niepełnosprawności.","key_changes":["Право на услугу: ПМЖ, резидент ЕС, беженцы и доп. защита, граждане ЕС/ЕЭЗ/Швейцарии и члены семей","Включены разрешения по ст. 127, 137a, 139a, 139o, 151, 151b, 159 ust. 1, 186 ust. 1 pkt 3, научная виза, Brexit-соглашение","Карта побыту с отметкой ''dostęp do rynku pracy'' даёт право, кроме студентов, сезонных и краткосрочных работников","Объём: 20–240 часов в месяц (18–65 лет), 20–80 часов (13–18 лет); ставки 49–55 zł брутто в час","Заявление подаётся электронно; иностранец прилагает документ, дающий право на пребывание в Польше"],"affected_groups":["иностранцы с инвалидностью, имеющие ПМЖ или статус резидента ЕС","беженцы и лица с дополнительной защитой","граждане ЕС/ЕЭЗ/Швейцарии и члены их семей","обладатели карты побыту с отметкой ''dostęp do rynku pracy''","работники по внутрикорпоративному переводу и научные работники","граждане Великобритании по Brexit-соглашению"],"practical_impact":"Иностранец с инвалидностью, проживающий в Польше и имеющий соответствующее решение об уровне потребности в поддержке, может бесплатно получить личного ассистента; заявление подаётся только электронно с приложением документа о праве на пребывание.","effective_date":"Через 14 дней после опубликования, с исключениями: ст. 6 ust. 1 pkt 1 и часть ст. 8 — через 12 месяцев; ст. 6 ust. 1 pkt 2 и ст. 7 ust. 2–7 — через 14 месяцев; ст. 58–67 и ст. 99 — с первого дня месяца после 5 месяцев от опубликования.","confidence":0.85,"rationale":"Закон касается социальной поддержки и прямо перечисляет категории иностранцев, получающих право на услугу, но не затрагивает легализацию пребывания или работу.","changes_since_previous":["В перечень оснований добавлены разрешения по ст. 159 ust. 1 и ст. 186 ust. 1 pkt 3 ustawy o cudzoziemcach","Добавлены переходные ограничения максимума часов: 200 часов в 2028 г. и 220 часов в 2029 г.","Уточнены сроки рассмотрения заявлений: до 120 дней (до 31.12.2028), 90 дней, затем 60 дней","Детализирован поэтапный запуск: 90 баллов — через 12/16 месяцев от публикации, 85 — через 17/21, 80 — с 01.09.2028/01.01.2029","Для лиц 13–18 лет и проживающих в учреждениях круглосуточного ухода — заявления с 01.05.2029, право с 01.01.2030"]},"model":"claude-opus-5","prompt_version":"2026-09-v9","input_chars":154338,"truncated":false,"text_source":"pdf","created_at":"2026-09-22T16:01:14Z","input_tokens":77754,"output_tokens":1429,"cache_read_input_tokens":2652,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/316_u3.pdf","source_kind":"text_after3","revision":3,"text_sha256":"ca08cb45cab92073c6425650560e9f2d84d0f354b7e9ed5ec8ec1b0136e2d2f2","source_checked_at":"2026-09-22T16:01:14Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('48d799a9349d69336bb88c4d5c29a9489f4cf53a51eb7dc7c7f43ba075cb0b5f','{"analysis":{"relevant":true,"score":4,"category":"social","summary":"Проект изменяет спецзакон о помощи гражданам Украины. Он отменяет ряд норм, дающих украинцам льготный доступ к социальным выплатам и медицинской помощи, а также к работе в научных институтах без конкурса. После этого украинцы пользовались бы этими правами на общих условиях, как другие иностранцы.","key_changes":["Отмена ряда статей спецзакона (в т.ч. ст. 26, 26a, 27b, 27c, 29, 32, 33, 37) о льготном доступе к соцвыплатам","По обоснованию, отменяется автоматический доступ к медпомощи NFZ для легально пребывающих украинцев","Отмена ст. 47–49: приём украинцев на работу в институты PAN и Łukasiewicz без конкурса, по заявлению","Повят будет финансировать только пребывание в приёмной семье лиц из ст. 27a (новая редакция ст. 27d)","Замена в тексте закона «w Ukrainie» на «na Ukrainie» (языковая правка)"],"affected_groups":["граждане Украины, пребывающие в Польше на основании спецзакона","украинцы, получающие социальные выплаты и медицинскую помощь по спецзакону","украинские учёные, трудоустраивающиеся в научные учреждения"],"practical_impact":"Украинцы со статусом по спецзакону утратили бы льготный доступ к части соцвыплат и медпомощи и могли бы получать их только на общих основаниях, например при наличии карты побыту, статуса беженца или страховки NFZ. Для работы в институтах PAN и Łukasiewicz потребовался бы обычный конкурс.","effective_date":"Закон вступает в силу по истечении 30 дней со дня опубликования.","confidence":0.75,"rationale":"Проект меняет спецзакон о помощи гражданам Украины (уровень 4), а основное содержание касается социальных выплат и медпомощи, отсюда категория social.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":19248,"truncated":false,"text_source":"pdf","created_at":"2026-09-25T03:08:29Z","input_tokens":10115,"output_tokens":1101,"cache_read_input_tokens":0,"cache_creation_input_tokens":2652,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/1039/1039.pdf","source_kind":"print","revision":1,"text_sha256":"7a8ee05156b9bdcefe6bc193021025bfd9c53c6366467170baa828991ffa8cd9","source_checked_at":"2026-09-25T03:08:29Z"}',10,'1039','2026-09-25T03:08:29+00:00');
INSERT INTO "analysis_memo" VALUES('0b8634bb1a3c19e43e3b810ec8e4508720059112c08e1aaec598715745688722','{"analysis":{"relevant":true,"score":4,"category":"employment","summary":"Проект ужесточает условия получения 800+ (świadczenie wychowawcze) для граждан Украины, находящихся в Польше по спецзакону. Выплата будет зависеть от работы или бизнеса в Польше и уплаты налогов; при невыполнении условий пособие приостанавливается.","key_changes":["Новое условие для 800+: трудоустройство или ведение działalności gospodarczej в Польше","Новое условие: исполнение налоговых обязательств перед государством","Исключение: законные освобождения, отсрочки, рассрочка или приостановление решения органа","Приостановление выплаты при выявлении отсутствия работы или неуплаты налогов","Возобновление выплаты с месяца, когда условия снова выполнены"],"affected_groups":["Граждане Украины с легальным пребыванием на основании art. 2 ust. 1 спецзакона","Украинские родители, получающие или подающие заявление на 800+"],"practical_impact":"Чтобы получать 800+ на ребёнка, гражданину Украины нужно будет работать или вести бизнес в Польше и не иметь налоговых задолженностей; иначе ZUS приостановит выплату. Новые условия впервые применяются к заявлениям, подаваемым с 1 февраля по 30 апреля 2025 г.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования; новые условия впервые применяются к заявлениям, подаваемым с 1 февраля 2025 г. по 30 апреля 2025 г.","confidence":0.9,"rationale":"Поправка к ustawa o pomocy obywatelom Ukrainy (закон о помощи гражданам Украины), связывающая доступ к 800+ с занятостью, относится по шкале к уровню 4 и напрямую затрагивает украинцев под временной защитой.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":7982,"truncated":false,"text_source":"pdf","created_at":"2026-09-25T03:08:29Z","input_tokens":4708,"output_tokens":673,"cache_read_input_tokens":0,"cache_creation_input_tokens":2652,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/1040/1040.pdf","source_kind":"print","revision":1,"text_sha256":"346991616e45f3d862e55248ae507d523c88265ad987e0419165eb54a1009af7","source_checked_at":"2026-09-25T03:08:29Z"}',10,'1040','2026-09-25T03:08:29+00:00');
INSERT INTO "analysis_memo" VALUES('6a25be7efddb76263815da1d8934b17d60e33ea40cdcbe934d087e4eb8ab0d8c','{"triage":{"affects_foreigners":true,"confidence":0.75,"rationale":"Законопроект о судебных экспертах требует польское гражданство (или ЕС/EFTA/Швейцария) для получения статуса присяжного эксперта, а также содержит положения об идентификации иностранцев (документ, подтверждающий личность иностранца) в реестре, что напрямую затрагивает иностранцев, желающих выполнять эту функцию."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":12093,"output_tokens":152,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12408900','2026-09-28T11:41:04+00:00');
INSERT INTO "analysis_memo" VALUES('1ca28423810a37685936d33799609691a60e4e03890add4bf9b14e9dd48b5140','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект вводит новую систему судебных экспертов (biegli sądowi): сертификация через Państwowa Komisja Certyfikacyjna и единый реестр. Иностранцев касается требование гражданства: экспертом может стать только гражданин Польши, ЕС, ЕАСТ/ЕЭЗ или Швейцарии, владеющий польским языком.","key_changes":["Судебным экспертом может быть только гражданин Польши, ЕС, ЕАСТ/ЕЭЗ или Швейцарии","Обязательно достаточное владение польским языком, возраст от 25 лет, 5 лет практики","Иностранные документы подаются с заверенным переводом на польский язык","Без PESEL в заявлении указывается паспорт или документ иностранца по ustawa o cudzoziemcach","Сертификат на 5 лет выдаёт Państwowa Komisja Certyfikacyjna, эксперт вносится в общенациональный реестр"],"affected_groups":["граждане третьих стран, желающие работать судебными экспертами в Польше","граждане ЕС/ЕАСТ/Швейцарии — кандидаты в судебные эксперты","действующие судебные эксперты"],"practical_impact":"Граждане стран вне ЕС/ЕАСТ/Швейцарии (например, Украины или Беларуси) не смогут получить сертификат судебного эксперта, даже при наличии квалификации. Граждане ЕС должны подтвердить знание польского языка и предоставить заверенные переводы документов.","effective_date":"Закон вступает в силу 1 января 2027 г., за исключением ст. 55–63 (реестр) — с 1 апреля 2027 г. и ст. 88–90 — с 1 октября 2026 г.","confidence":0.8,"rationale":"Общий закон о профессии судебного эксперта с конкретным аспектом для иностранцев — требованием гражданства Польши/ЕС/ЕАСТ/Швейцарии, поэтому косвенное влияние.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":305859,"truncated":false,"text_source":"documents","created_at":"2026-09-28T11:48:49Z","input_tokens":150243,"output_tokens":1042,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408900/13196264/13196265/dokument770060.docm","source_kind":"rcl","revision":1,"text_sha256":"1356ca7516fc78b98838020f119582553ec383c6571febcb797990440caef1be","source_checked_at":"2026-09-28T11:48:49Z"}',10,'RCL/12408900','2026-09-28T11:48:49+00:00');
INSERT INTO "analysis_memo" VALUES('9513ced30289602e70c00a79e6616f283e50d4c2a010b5c76c6c6ce6f6e608a9','{"triage":{"affects_foreigners":false,"confidence":0.75,"rationale":"Это ратификация международного соглашения о партнёрстве и сотрудничестве ЕС с Киргизией, касающегося торговли, борьбы с преступностью и общих рамок миграционного диалога, но, как прямо указано в обосновании, документ не изменяет польского законодательства и не касается напрямую физических лиц, включая иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":12327,"output_tokens":148,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3139','2026-09-28T15:33:31+00:00');
INSERT INTO "analysis_memo" VALUES('7dc2122dc508fc2268c00425d178ea4bd7b0a258102497fd335b1f23cde6d941','{"triage":{"affects_foreigners":true,"confidence":0.55,"rationale":"Проект касается финансирования лечения ВИЧ для лиц без права на медицинское страхование, что может включать иностранцев, находящихся в Польше без страхования, хотя прямо о них не упоминается в приведённых фрагментах."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":4499,"output_tokens":111,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3143','2026-09-28T15:33:31+00:00');
INSERT INTO "analysis_memo" VALUES('fcd1d6cb54261efd1d4d3afe6aa2a6350defeb45ab4ec3a986a886059f570e24','{"triage":{"affects_foreigners":true,"confidence":0.75,"rationale":"Проект в основном касается организационных вопросов Straży Granicznej и сотрудничества с Frontex, но включает поправки к ustawie o cudzoziemcach (операции и интервенции по возвращению мигрантов), что напрямую затрагивает процедуры в отношении иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":13856,"output_tokens":129,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3146','2026-09-28T15:33:53+00:00');
INSERT INTO "analysis_memo" VALUES('14256896f1b9a16ff26644a5d8ba88f11d78344f2fb1610f0763be64cff6de82','{"triage":{"affects_foreigners":true,"confidence":0.75,"rationale":"Projekt dotyczy koordynacji systemów zabezpieczenia społecznego, poboru składek zdrowotnych z emerytur transferowanych z zagranicy oraz zwrotu kosztów transgranicznej opieki zdrowotnej w UE/EFTA/UK, co bezpośrednio dotyczy osób korzystających z tych świadczeń, w tym cudzoziemców i Polaków mieszkających za granicą."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":9548,"output_tokens":181,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3141','2026-09-28T15:33:53+00:00');
INSERT INTO "analysis_memo" VALUES('de38b0ec57105d6e1aafca380b73db45b949b4a566ed6070da07fd1e52fbf268','{"triage":{"affects_foreigners":false,"confidence":0.65,"rationale":"Это законопроект о ратификации рамочного соглашения ЕС-Узбекистан о партнёрстве, которое, согласно обоснованию, «не касается непосредственно физических или юридических лиц» и не меняет внутреннее польское законодательство, хотя содержит общие положения о сотрудничестве по миграции и реадмиссии на уровне ЕС."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":12080,"output_tokens":501,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3140','2026-09-28T15:33:53+00:00');
INSERT INTO "analysis_memo" VALUES('b01bc3b166094237181b72138d5d90b0c6db00ed632fe36c6d26d6d5640fbb35','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект даёт согласие на ратификацию Расширенного соглашения о партнёрстве и сотрудничестве между ЕС и Узбекистаном. Соглашение в основном касается торговли и сотрудничества, но содержит положения о миграции, реадмиссии граждан без права пребывания и деловых поездках. Прямо польское право оно не меняет.","key_changes":["Узбекистан и страны ЕС обязуются без промедления принимать обратно своих граждан, не имеющих права на пребывание","Документы для возврата выдаются в течение 30 дней после запроса о реадмиссии","Предусмотрен диалог о легальной миграции, защите прав легальных мигрантов и интеграции","Стороны могут начать переговоры о соглашении об упрощении визового режима","Внутрикорпоративный перевод: пребывание до 3 лет; бизнес-визиты для создания компании — до 90 дней"],"affected_groups":["граждане Узбекистана в Польше","граждане Узбекистана без законного права на пребывание","сотрудники компаний, переводимые внутри корпорации","поставщики услуг по контракту из Узбекистана"],"practical_impact":"Для граждан Узбекистана, не имеющих законного права на пребывание в Польше, упрощается процедура возврата на родину (реадмиссии). Требования ustawa o cudzoziemcach (закон об иностранцах) к въезду, пребыванию и работе продолжают действовать; соглашение не даёт физическим лицам прав, на которые можно ссылаться напрямую.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.8,"rationale":"Ратификация двустороннего соглашения с миграционными и реадмиссионными положениями, не меняющего польское право напрямую, относится к косвенному влиянию (балл 2).","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":1199982,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":504067,"output_tokens":685,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3140/3140.pdf","source_kind":"print","revision":1,"text_sha256":"c9e3239a71f94f23614e5789a1164dce5b9300379487c172b974aeb046cf0215","source_checked_at":"2026-09-28T15:56:31Z"}',10,'3140','2026-09-28T15:56:31+00:00');
INSERT INTO "analysis_memo" VALUES('877da56b50df00e2980adba3c00b49d5d9d9298b2eaed1df3fbd58f566fe158b','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Поправки к закону о медицинском страховании NFZ. Страховку получат выпускники медвузов на практическом обучении и слушатели курсов польского языка. Меняются правила взносов с пенсий из стран ЕС, EFTA и Великобритании, а также порядок возмещения расходов на лечение за границей.","key_changes":["Обязательное страхование в NFZ для слушателей курсов польского языка и подготовительных курсов, если у них нет другого основания","Страхование для выпускников медвузов (в т.ч. с обучением не на польском) на практическом обучении по art. 15p","Пенсионеры, закончившие работу в ЕС/EFTA/UK, обязаны сообщить об этом в ZUS/KRUS в течение 14 дней, иначе долг по взносам удержат из пенсии","NFZ сможет сам задним числом зарегистрировать члена семьи, застрахованного по ошибке в другом государстве ЕС","Новая процедура возмещения NFZ расходов на лечение в ЕС/EFTA/UK; к заявке можно приложить заключение зарубежного врача с присяжным переводом"],"affected_groups":["иностранцы на курсах польского языка и подготовительных курсах","выпускники медицинских факультетов, в т.ч. англоязычных программ","получатели пенсий из стран ЕС, EFTA и Великобритании, живущие в Польше","члены семей застрахованных в трансграничных ситуациях","пациенты, лечащиеся в других странах ЕС/EFTA/UK"],"practical_impact":"Слушатели курсов польского языка и выпускники медвузов на практике получат страховку NFZ через вуз, а получатели иностранных пенсий будут платить взнос на здравоохранение через банк и должны вовремя уведомлять ZUS об окончании работы за рубежом. Для людей без места жительства в Польше отделение NFZ определяется по последнему адресу в Польше или по месту нахождения плательщика, без выбора.","effective_date":"Через 14 дней после опубликования, кроме: art. 1 pkt 9 lit. e и g, pkt 13 и art. 2 — через 12 месяцев; art. 1 pkt 25 и art. 3 — через 9 месяцев после опубликования.","confidence":0.75,"rationale":"Законопроект меняет доступ к медицинскому страхованию NFZ и взносы для групп, среди которых много иностранцев (курсы польского, иностранные пенсии, трансграничные ситуации), что относится к социальной сфере.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":151007,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":78995,"output_tokens":1474,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3141/3141.pdf","source_kind":"print","revision":1,"text_sha256":"113c0c5c2684218532aecbd424c368a1387f7d38da08037118210464ea3724bf","source_checked_at":"2026-09-28T15:56:31Z"}',10,'3141','2026-09-28T15:56:31+00:00');
INSERT INTO "analysis_memo" VALUES('c846641f6d1e600153381c2bc29d8b11fd3d72a529370874c345796cd41ea0d1','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект даёт согласие на ратификацию нового соглашения о партнёрстве и сотрудничестве ЕС с Кыргызстаном, заменяющего договор 1995 года. Соглашение касается торговли, инвестиций, защиты географических указаний, а также сотрудничества в сфере миграции, реадмиссии и правовой помощи. Прямо права граждан Кыргызстана в Польше не меняет.","key_changes":["Кыргызстан обязуется принимать обратно своих граждан, не имеющих права находиться в странах ЕС, без дальнейших формальностей","Допускается использование европейского проездного документа для возврата нелегально пребывающих лиц","Стороны могут договориться о соглашении ЕС–Кыргызстан об упрощении визового режима и о реадмиссии","Внутрикорпоративные переводы: руководители и специалисты — до 3 лет, стажёры — до 1 года, при соблюдении национальных правил","Граждане Кыргызстана могут получать консульскую защиту в странах ЕС без его представительства"],"affected_groups":["граждане Кыргызстана в Польше и ЕС","граждане Кыргызстана без законных оснований для пребывания","сотрудники кыргызских компаний, переводимые внутри корпорации","инвесторы из Кыргызстана"],"practical_impact":"Для граждан Кыргызстана в Польше правила получения виз, разрешений на пребывание и работу не меняются: соглашение прямо указывает, что национальное законодательство о въезде, пребывании и работе продолжает действовать. Возможно упрощение возврата лиц без законного статуса в Кыргызстан.","effective_date":"Закон вступает в силу через 14 дней со дня опубликования; само соглашение — в первый день второго месяца после взаимного уведомления сторон о завершении внутренних процедур.","confidence":0.8,"rationale":"Ратификация двустороннего соглашения, затрагивающего миграцию и реадмиссию лишь на уровне рамочного сотрудничества без изменения национальных правил пребывания, соответствует косвенному влиянию (оценка 2).","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":1268621,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":550072,"output_tokens":779,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3139/3139.pdf","source_kind":"print","revision":1,"text_sha256":"f95398d40b3ad92b97a13150325f6533e52d48eed4dc3c935c8b00a65d342a7f","source_checked_at":"2026-09-28T15:56:31Z"}',10,'3139','2026-09-28T15:56:31+00:00');
INSERT INTO "analysis_memo" VALUES('2b462f967e1ee179a2d78482a09163adf2aeb203266f3249f2e3eaab1d37dafe','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект уточняет, кто оплачивает медицинские услуги в двух государственных программах: лечение ВИЧ для людей без медицинской страховки и лечение гепатита C у заключённых. Визиты и анализы в программе лечения ВИЧ для незастрахованных будут оплачиваться из госбюджета. Иностранцы прямо не упоминаются, но касается это и незастрахованных иностранцев.","key_changes":["Услуги, связанные с антиретровирусным лечением ВИЧ, для лиц без права на страховку NFZ оплачиваются из госбюджета (бюджет министра здравоохранения)","Цель — устранить практику, когда за визиты и анализы в программе лечения ВИЧ с незастрахованных брали плату","NFZ сможет финансировать не только лекарства, но и медицинские услуги в программе лечения гепатита C у заключённых","Средства NFZ на программы передаются на счета бюджетных учреждений в сроках и суммах, определяемых министром здравоохранения"],"affected_groups":["люди, живущие с ВИЧ, без медицинской страховки в Польше, в том числе иностранцы","заключённые с хроническим гепатитом C","медучреждения, реализующие программу лечения ВИЧ"],"practical_impact":"Незастрахованный иностранец с ВИЧ, находящийся в Польше, должен получать в рамках программы не только бесплатные лекарства, но и бесплатные визиты к врачу и анализы, без оплаты из собственного кармана.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.65,"rationale":"Законопроект не касается иностранцев как таковых, но улучшает доступ к лечению ВИЧ для всех незастрахованных, среди которых значительную часть составляют иностранцы, поэтому влияние косвенное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":23123,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":14785,"output_tokens":1046,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3143/3143.pdf","source_kind":"print","revision":1,"text_sha256":"8bb9393c139e45c2aaf392d29025b78844821bb0d8aedc9feba2246a43f5b254","source_checked_at":"2026-09-28T15:56:31Z"}',10,'3143','2026-09-28T15:56:31+00:00');
INSERT INTO "analysis_memo" VALUES('5eedd907f384ba51e7c5e1ac0d1e208fee9a970e8269c2a05d375af82ba3a9ba','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект адаптирует польское право к регламенту ЕС 2019/1896 о Frontex. Главным образом он касается Straż Graniczna (Пограничной службы) и её сотрудничества с агентством. Для иностранцев важно, что в ustawa o cudzoziemcach (закон об иностранцах) вводятся правила проведения в Польше операций Frontex по возвращению мигрантов.","key_changes":["В ustawa o cudzoziemcach добавлены понятия «операция по возвращению» и «интервенция по возвращению» (Frontex)","Komendant Główny SG сможет запрашивать у Frontex организацию операций по возвращению или соглашаться на них","Персонал Frontex и других стран ЕС сможет выполнять в Польше задачи по возвращению, включая применение оружия и мер принуждения","Сотрудников SG разрешат направлять в третьи страны как офицеров связи по возвращению (EURLO) для установления личности иностранцев","Frontex получит право регистрировать свои служебные автомобили как транспорт спецслужб"],"affected_groups":["иностранцы, обязанные покинуть Польшу (с решением о zobowiązanie do powrotu)","иностранцы без урегулированного статуса"],"practical_impact":"Процедуры и основания выдворения не меняются, но исполнять решения о возвращении в Польше смогут и команды Frontex, в том числе на совместных рейсах. Польские офицеры в третьих странах будут помогать подтверждать личность иностранцев и получать документы для их возвращения.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.85,"rationale":"Законопроект в основном институциональный (Frontex, Straż Graniczna), но касается исполнения возвращений иностранцев, то есть иммиграционного контроля, поэтому это косвенное влияние с оценкой 2.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":118838,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":61448,"output_tokens":872,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3146/3146.pdf","source_kind":"print","revision":1,"text_sha256":"e4d525e776970059034fef2588e362ef0b3f7fa209c5cc7bdcce3efc3dbd753a","source_checked_at":"2026-09-28T15:56:31Z"}',10,'3146','2026-09-28T15:56:31+00:00');
INSERT INTO "analysis_memo" VALUES('95a10ff3ab8322dc1b16a86e14c5d9a2e92a0ecadbaf721748cbc98c77c2ce10','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет правила медстрахования NFZ и возмещения расходов на лечение в ЕС/EFTA/Великобритании. Он вводит обязанности для получателей польских и зарубежных пенсий и включает в медстрахование выпускников медицинских направлений на практическом обучении и слушателей курсов польского языка.","key_changes":["Отдельная процедура возмещения NFZ расходов на необходимое лечение в ЕС/EFTA/UK по правилам координации (art. 42ia)","К заявлению на согласие NFZ можно приложить заключение врача из ЕС/EFTA/UK с присяжным переводом","Возврат за лекарство в ЕС/ЕЭЗ по польскому рецепту на возмещение, не только по трансграничному","Медстрахование для выпускников на практическом обучении (art. 15p) и слушателей подготовительных курсов польского языка","Сообщить в ZUS/KRUS об окончании работы в ЕС/EFTA/UK в течение 14 дней, иначе долг по взносам удержат из пенсии"],"affected_groups":["выпускники медицинских направлений на иностранном языке, проходящие практическое обучение в Польше","слушатели курсов польского языка и подготовительных курсов к учёбе на польском","получатели пенсий из ЕС/EFTA/UK, живущие в Польше","застрахованные в NFZ, лечащиеся в других странах ЕС/EFTA/UK","члены семей застрахованных в трансграничных ситуациях"],"practical_impact":"Выпускники-медики на практическом обучении и слушатели подготовительных курсов польского языка получают медстрахование, если не застрахованы по другому основанию. Лечение за границей проще согласовать с NFZ по заключению иностранного врача. Пенсионерам после окончания работы в ЕС/EFTA/UK нужно в течение 14 дней уведомить ZUS/KRUS.","effective_date":"Через 14 дней после опубликования; art. 1 pkt 9 lit. e и g, pkt 13 и art. 2 — через 12 месяцев; art. 1 pkt 25 и art. 3 — через 9 месяцев после опубликования.","confidence":0.8,"rationale":"Проект касается медстрахования NFZ и трансграничного лечения, в том числе групп, где много иностранцев (выпускники иноязычных медицинских программ, слушатели курсов польского языка), поэтому это социальная сфера, оценка 3.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":148783,"truncated":false,"text_source":"documents","created_at":"2026-09-28T15:56:32Z","input_tokens":76387,"output_tokens":1419,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12412454/13215502/13215503/dokument797859.zip","source_kind":"rcl","revision":2,"text_sha256":"6f722062659c34910b5eef1ce1542166e5b8b7aafdcc48621ceae7deaf0e6f6b","source_checked_at":"2026-09-28T15:56:32Z"}',10,'RCL/12412454','2026-09-28T15:56:32+00:00');
INSERT INTO "analysis_memo" VALUES('00ab501419f20515388b8880dc6f206dbbc28bee071a566d358fce21c6102dd6','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Закон устанавливает, как Польша исполняет решения Европейского суда по правам человека (ЕСПЧ): кто отвечает за исполнение, как выплачивается компенсация и как соблюдаются временные меры суда. Норм об иностранцах в тексте нет, но закон касается и иностранцев, подавших жалобу в ЕСПЧ против Польши.","key_changes":["MSZ координирует исполнение решений ЕСПЧ, при министре создаётся межведомственный Zespół","Компенсация выплачивается по заверенному формуляру платежа, при его отсутствии сумма идёт в судебный депозит","Временную меру ЕСПЧ исполняют и тогда, когда о ней сообщил представитель заявителя, если документ достоверен","По временной мере орган прекращает или не начинает указанное судом действие и может изменить или отменить решение","Окончательное решение ЕСПЧ становится исполнительным документом (art. 777 KPC)"],"affected_groups":["заявители, подавшие жалобу в ЕСПЧ против Польши, в том числе иностранцы","лица, в делах которых ЕСПЧ назначил временную меру"],"practical_impact":"Заявителю, выигравшему дело в ЕСПЧ, нужно без промедления подать в MSZ заверенный формуляр платежа, иначе сумма попадёт в судебный депозит. Временные меры ЕСПЧ обязательны для органов власти, в том числе если о них сообщил представитель заявителя.","effective_date":"Закон вступает в силу по истечении 30 дней со дня опубликования.","confidence":0.6,"rationale":"Закон общий и процедурный, иностранцы в нём прямо не упоминаются, поэтому для них он маргинален, хотя механизм временных мер ЕСПЧ может затрагивать и их дела.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":46453,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":26181,"output_tokens":1181,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2271/attachment/2271_u3.pdf","source_kind":"text_after3","revision":2,"text_sha256":"e22f0142ed0f6306ff7f712868af66cb47da2c50ad880759c7b83b7ebf15d8b9","source_checked_at":"2026-09-28T15:56:32Z"}',10,'2271','2026-09-28T15:56:32+00:00');
INSERT INTO "analysis_memo" VALUES('7aecd9bb5c73ce9649b1ba011ff3efd15f3b8fdd058527a3f20be5a75744222a','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Законопроект создаёт статус mediator sądowy (судебный медиатор) и электронный Krajowy Rejestr Mediatorów (национальный реестр медиаторов), вводит единые стандарты обучения. Иностранцы затронуты лишь как возможные кандидаты в медиаторы.","key_changes":["Вместо списков постоянных медиаторов вводится единый электронный Krajowy Rejestr Mediatorów","Без PESEL в заявлении указывается паспорт, документ путешественника или документ по ustawa o cudzoziemcach","Лица без польского гражданства прилагают подтверждение знания польского языка не ниже B2","Требования: 26 лет, высшее образование, базовое (40 ч) и специализированное обучение, несудимость","Учитывается зарубежное высшее образование, признанное в Польше; в реестре можно указать языки медиации"],"affected_groups":["иностранцы, желающие стать судебными медиаторами","иностранцы, работающие медиаторами по действующим спискам"],"practical_impact":"Иностранец без PESEL сможет подать заявление о внесении в реестр, указав паспорт или документ по ustawa o cudzoziemcach, но обязан подтвердить знание польского на уровне B2. Для большинства иностранцев ничего не меняется.","effective_date":"Закон вступает в силу 1 сентября 2027 г.","confidence":0.85,"rationale":"Иностранцы упоминаются лишь в контексте формальных требований к кандидатам в медиаторы, поэтому влияние маргинальное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":138006,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":71032,"output_tokens":581,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3008/3008.pdf","source_kind":"print","revision":2,"text_sha256":"05f8b358d8b13983313de7c36a3987d45a652f65878c2f5d5c8b123702bad1ab","source_checked_at":"2026-09-28T15:56:32Z"}',10,'3008','2026-09-28T15:56:32+00:00');
INSERT INTO "analysis_memo" VALUES('d79f11953db40f7520b4fbe37731ae4df6a51880df4add33462bf3c6a90c4d7b','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Закон вводит «umowa o wspólnym pożyciu» (договор о совместной жизни): это нотариальный договор для пар независимо от пола, дающий статус ближайшего лица. Заключить его могут и иностранцы, но права на пребывание в Польше он не даёт.","key_changes":["Договор заключается у нотариуса в Польше, при одновременном присутствии обеих сторон","В заверениях указываются гражданство, PESEL (если присвоен) и данные документа личности","Нельзя заключить договор, если человек уже состоит в браке или в зарубежном союзе, не признаваемом браком","По умолчанию действует раздельность имущества; можно выбрать общность или выравнивание достижений","Регистрация в urząd stanu cywilnego, opłata skarbowa 100 zł; возможны доверенности, доступ к медданным, завещания"],"affected_groups":["иностранцы, живущие в Польше в неформальных парах","пары одного пола, в том числе с участием иностранцев","иностранцы без PESEL"],"practical_impact":"Иностранец может заключить договор с партнёром у польского нотариуса по документу личности, даже без PESEL, и получить права по имуществу, медицинской информации и представительству. Если он состоит в зарубежном союзе, не признаваемом в Польше браком, заключить договор нельзя; легализации пребывания договор не даёт.","effective_date":"Закон вступает в силу в срок, определённый в отдельном законе «Przepisy wprowadzające ustawę o statusie osoby najbliższej w związku i umowie o wspólnym pożyciu» (вводные положения).","confidence":0.8,"rationale":"Это общий гражданско-правовой закон, доступный иностранцам, с отдельными нормами о гражданстве, PESEL и зарубежных союзах, но без влияния на право пребывания, поэтому воздействие косвенное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":24882,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":15787,"output_tokens":1129,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2110/attachment/2110_u3.pdf","source_kind":"text_after3","revision":2,"text_sha256":"86421a120c0194a37f061d6829b176f10ad4c45d25b2c2ec92f6aa50793d1969","source_checked_at":"2026-09-28T15:56:32Z"}',10,'2110','2026-09-28T15:56:32+00:00');
INSERT INTO "analysis_memo" VALUES('204f450615c0c25a8368fe9b48a19d7f084abf838a287455f97f1d6b105b5c67','{"analysis":{"relevant":true,"score":3,"category":"legal_stay","summary":"Специальный закон об организации Всемирного скаутского Джамбори в Гданьске в 2027 году. Для иностранцев главное: участники освобождаются от консульского сбора за национальную и шенгенскую визу, а их заявления рассматриваются без лишней задержки. Остальные нормы касаются медицины, санитарии, строительства и безопасности.","key_changes":["Освобождение от консульского сбора за национальную визу и визу Шенген для участников Джамбори","Нужно приложить подтверждение регистрации участия или иной документ об участии","Рассмотрение «без излишней задержки», если консула уведомили не позднее чем за 6 недель до начала","Срок 6 недель не действует для глав государств, членов правительств, монархов и официальных делегаций","Волонтёры не из ЕС должны представить справки о несудимости из стран гражданства и проживания за 10 лет"],"affected_groups":["иностранные участники Всемирного скаутского Джамбори, нуждающиеся в визе","иностранные волонтёры, работающие с несовершеннолетними участниками","официальные иностранные делегации"],"practical_impact":"Иностранные участники Джамбори не платят консульский сбор за визу при наличии подтверждения регистрации и получают ускоренное рассмотрение при уведомлении консула за 6 недель. Волонтёры-иностранцы для работы с детьми обязаны собрать справки о несудимости из стран гражданства и проживания за последние 10 лет.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.85,"rationale":"Закон содержит визовые льготы (сфера легализации въезда), но узкие и разовые — только для участников одного мероприятия, поэтому оценка средняя.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":27534,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":17389,"output_tokens":1155,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf","source_kind":"text_after3","revision":2,"text_sha256":"f4a3bf591d2ceebcf73b360901f38bb0fc2bf7f016acb504a4c15caecd85808a","source_checked_at":"2026-09-28T15:56:32Z"}',10,'2846','2026-09-28T15:56:32+00:00');
INSERT INTO "analysis_memo" VALUES('eb33d25d3d43f7c55420fe8e7c5ef9b9baaa23db70ded1d5dd0bc78cdbe4671a','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект меняет работу KRS (Krajowy Rejestr Sądowy, судебный реестр компаний и организаций): вся переписка с судом идёт через электронную систему и счёт организации, упрощается ликвидация «мёртвых» фирм. Иностранцев касается лишь уточнённое заявление о статусе cudzoziemca у покупателя долей и акций.","key_changes":["В заявке о покупке долей/акций указывается, является ли приобретатель cudzoziemcem по ustawa z 1920 r.","Если приобретатель — иностранец, заявляется, владеет ли компания недвижимостью в Польше","Для адреса регистрации фирмы нужно правовое основание на помещение, документ прилагается к заявке","Заявления и письма в реестровый суд — только через ИТ-систему и счёт организации","Пометка в KRS о несдаче финансовой отчётности; через год — роспуск фирмы без ликвидации"],"affected_groups":["иностранцы — покупатели и учредители долей и акций польских компаний","иностранцы — владельцы и члены правления компаний, зарегистрированных в KRS"],"practical_impact":"При покупке долей или акций польской компании иностранцем в заявке в KRS нужно указать его статус и наличие у компании недвижимости в Польше. Для всех фирм, включая принадлежащие иностранцам, обязательны электронная переписка с судом и документ о праве на помещение по адресу регистрации.","effective_date":"Закон вступает в силу 1 октября 2027 г., за исключением положений о пометке о несдаче финансовой отчётности и связанных норм, которые вступают в силу 1 октября 2028 г.","confidence":0.8,"rationale":"Проект касается корпоративного реестра в целом, а иностранцы затронуты лишь уточнением декларации по закону о приобретении недвижимости иностранцами, поэтому влияние маргинальное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":188666,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":97076,"output_tokens":1085,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3004/3004.pdf","source_kind":"print","revision":2,"text_sha256":"6de93675eb8a39b3ebdbc22f6ce78a830901c2feeeaca7cc1938b70d36843812","source_checked_at":"2026-09-28T15:56:32Z"}',10,'3004','2026-09-28T15:56:32+00:00');
INSERT INTO "analysis_memo" VALUES('e33f74e61cdf519193215751dbfa66b4adb634cc7de23a06ef8ffc17addf40a8','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект приводит польское законодательство в соответствие с регламентом ЕС 2019/1896 о Frontex. Для иностранцев главное: в ustawa o cudzoziemcach (закон об иностранцах) появляется правовая база для операций и интервенций по возвращению (выдворению) при участии Frontex на территории Польши.","key_changes":["В ustawa o cudzoziemcach вводятся понятия «operacja powrotowa» и «interwencja powrotowa» по регламенту ЕС 2019/1896","Komendant Główny SG сможет запрашивать у Frontex операции возвращения и давать согласие на них в Польше","Персонал Frontex и погранслужб стран ЕС сможет выполнять задачи по возвращению в Польше, включая применение силы","Польских пограничников можно будет направлять офицерами по возвращению (EURLO) в третьи страны для установления личности иностранцев","Frontex получает право регистрировать свои служебные машины, которые приравнены к спецтранспорту"],"affected_groups":["иностранцы, обязанные покинуть Польшу по решению о возвращении","иностранцы на внешней границе ЕС","сотрудники Straży Granicznej"],"practical_impact":"Права и процедуры для иностранцев не меняются, но выдворение из Польши и контроль на внешней границе смогут проводиться с участием сотрудников Frontex и других стран ЕС, в том числе с применением силы по правилам регламента ЕС.","effective_date":"Через 14 дней со дня опубликования.","confidence":0.85,"rationale":"Проект касается исполнения возвращений и пограничного контроля, но не меняет основания легализации и права иностранцев, поэтому это косвенное влияние.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":118838,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T16:14:59Z","input_tokens":61870,"output_tokens":1005,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3146/3146.pdf","source_kind":"print","revision":2,"text_sha256":"e4d525e776970059034fef2588e362ef0b3f7fa209c5cc7bdcce3efc3dbd753a","source_checked_at":"2026-09-28T16:14:59Z"}',10,'3146','2026-09-28T16:14:59+00:00');
INSERT INTO "analysis_memo" VALUES('da61bf6ec5df8c5f77f74e7fa19ae4880e7e3f6d755cc6926118495ca56a5756','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект меняет правила opłata miejscowa и opłata uzdrowiskowa (местный и курортный сборы). Их будет платить каждый, кто хотя бы одну ночь проживает в гостинице, пансионате или санатории в таких местностях, а удерживать сбор будет объект размещения. Кроме того, растёт порог освобождения от PCC при продаже движимых вещей.","key_changes":["Сбор взимается за каждую ночь проживания в объекте размещения, независимо от цели поездки","Максимальные ставки: 5,00 zł и 5,50 zł (местный), 6,86 zł за ночь (курортный)","Освобождение при проживании более 29 ночей подряд в объектах одной гмины","Сбор удерживают объекты размещения (płatnik); они могут требовать предоплату за заявленные ночи","Лимит освобождения от PCC при продаже движимых вещей: с 1000 до 3000 zł"],"affected_groups":["иностранные туристы и гости","иностранцы, живущие в гостиницах и хостелах в курортных и туристических местностях","сотрудники дипломатических и консульских представительств, не являющиеся гражданами Польши"],"practical_impact":"При заселении в гостиницу или санаторий в местности со сбором иностранец, как и гражданин Польши, платит его объекту размещения, возможно авансом за заявленные ночи; при проживании более 29 ночей подряд сбор не взимается. Иностранцы специально не выделяются, кроме сохранённого освобождения для дипперсонала без постоянного места пребывания в Польше.","effective_date":"Закон вступает в силу 1 января 2027 г., за исключением ст. 3 и ст. 10 (изменения PCC), которые вступают в силу через 14 дней после опубликования.","confidence":0.8,"rationale":"Это общая реформа местных сборов и налогов, которая касается всех одинаково; иностранцы упомянуты только в связи с освобождением для дипперсонала, поэтому влияние маргинальное.","changes_since_previous":["Изменены максимальные ставки местного сбора: теперь до 5,00 zł и до 5,50 zł за ночь вместо указанных ранее 3,56 zł и 5,03 zł; курортный сбор остался до 6,86 zł","Из условий введения местного сбора исключён критерий благоприятных климатических условий; достаточно ландшафтных достоинств местности, критерии которых определит rozporządzenie Rady Ministrów","Рада гмины может дифференцировать ставки или вводить освобождения по месту жительства, возрасту, наличию Karta Dużej Rodziny, степени инвалидности, сезону и длительности пребывания","Для объектов размещения до конца 2029 г. разрешена подача ежемесячной информации о сборе в бумажном виде"]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":25964,"truncated":false,"text_source":"documents","created_at":"2026-09-28T16:14:59Z","input_tokens":16308,"output_tokens":1514,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12410853/13206829/13206830/dokument796915.zip","source_kind":"rcl","revision":2,"text_sha256":"c2f429077b42f7e6a40a19d8dfd9157ac90fcc055b0f22523eb1ffdcb833dfc2","source_checked_at":"2026-09-28T16:14:59Z"}',10,'RCL/12410853','2026-09-28T16:14:59+00:00');
INSERT INTO "analysis_memo" VALUES('a80c32b84a2398d2a40a33a2da02ae05e1b351a7294a2a5007c66f54372e1965','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет правила медстрахования NFZ в трансграничных ситуациях ЕС/EFTA/Великобритании и порядок возмещения расходов на лечение за границей. Он также включает в медстрахование слушателей курсов польского языка и выпускников медицинских направлений на практическом обучении.","key_changes":["Новая процедура возмещения NFZ расходов на необходимое лечение в ЕС/EFTA/UK по правилам координации (art. 42ia)","К заявлению на согласие NFZ можно приложить заключение врача из ЕС/EFTA/UK с присяжным переводом","Медстрахование для слушателей курсов польского языка и подготовительных курсов, если нет другого основания","Пенсионеры должны в течение 14 дней сообщить в ZUS/KRUS об окончании работы в ЕС/EFTA/UK, иначе долг удержат из пенсии","NFZ сможет сам зарегистрировать члена семьи в медстраховании, если по правилам координации он должен быть застрахован в Польше"],"affected_groups":["слушатели курсов польского языка и подготовительных курсов к учёбе на польском","выпускники медицинских направлений на иностранном языке, проходящие практическое обучение в Польше","получатели пенсий из ЕС/EFTA/UK, проживающие в Польше","члены семей застрахованных в трансграничных ситуациях","пациенты, лечащиеся в других странах ЕС/EFTA/UK"],"practical_impact":"Слушатели курсов польского языка и выпускники-медики на практике получают право на медстрахование NFZ, если у них нет другого основания, а пенсионеры с работой в ЕС/EFTA/UK должны в течение 14 дней уведомить пенсионный орган об её окончании. Возмещение расходов на лечение за границей получает единую процедуру; к заявлению можно приложить заключение зарубежного врача с присяжным переводом.","effective_date":"Через 14 дней после опубликования, кроме art. 1 pkt 9 lit. e и g, pkt 13 и art. 2 — через 12 месяцев, а также art. 1 pkt 25 и art. 3 — через 9 месяцев после опубликования.","confidence":0.85,"rationale":"Проект касается медстрахования NFZ и доступа к лечению, в том числе для слушателей языковых курсов и лиц в трансграничных ситуациях, что относится к социальной сфере (оценка 3).","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":151007,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T17:19:34Z","input_tokens":79397,"output_tokens":1310,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3141/3141.pdf","source_kind":"print","revision":3,"text_sha256":"113c0c5c2684218532aecbd424c368a1387f7d38da08037118210464ea3724bf","source_checked_at":"2026-09-28T17:19:34Z"}',10,'3141','2026-09-28T17:19:34+00:00');
INSERT INTO "analysis_memo" VALUES('27452ec86925d6181d2b752deaac4d74879ff791f8d7419f88e904eda52c09e8','{"triage":{"affects_foreigners":false,"confidence":0.85,"rationale":"Проект касается банковского права, надзора за банками и финансовыми холдингами, требований к капиталу и оценке членов правления банков; упоминание гражданства и Straży Granicznej — лишь техническая деталь среди перечня требований, не создающая изменений в правах или процедурах для иностранцев как таковых."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":7326,"output_tokens":137,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12341804','2026-09-29T17:22:33+00:00');
INSERT INTO "analysis_memo" VALUES('014f1cb5b542853c1ccb3f0cf63e821a4b405c04a8964b15848b4261b350a3f8','{"triage":{"affects_foreigners":false,"confidence":0.75,"rationale":"Законопроект касается системы рефинансирования лекарств, медицинских изделий и процедур в аптеках, упоминание граждан Украины и координации ЕС носит второстепенный технический характер и не меняет существенно положение иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":9090,"output_tokens":111,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12398102','2026-09-30T11:17:40+00:00');
INSERT INTO "analysis_memo" VALUES('0e5b8dd9afd55f3164e3bf6217d0a226579471ed037d42183c5a9f56dc5a946f','{"triage":{"affects_foreigners":true,"confidence":0.55,"rationale":"Это проект бюджета на 2027 год, который включает конкретные статьи расходов, касающиеся иностранцев (Urząd do Spraw Cudzoziemców, pomoc dla cudzoziemców, Karta Polaka, репатрианты), хотя это в основном финансовый документ, а не изменение прав, но затрагивает финансирование программ для иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":12955,"output_tokens":157,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RPW/32733/2026','2026-09-30T11:17:40+00:00');
INSERT INTO "analysis_memo" VALUES('354b140a3974c9fcac4670e7f7b4440deef319746773ce49a5d274d693d7c7fd','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект полностью перестраивает правила рефундации лекарств и медизделий за счёт NFZ, вводит новые ИТ‑системы и упрощённые процедуры. Это может улучшить доступ к дорогим и редким лекарствам для всех застрахованных, в т.ч. иностранцев, и меняет данные, которые указываются в рецептах и заявках на возмещение.","key_changes":["Новые процедуры и ИТ‑системы для рефундации и мониторинга программ лековых (SOLR, SOID, System Monitorowania Programów Lekowych, SWDPL)","Подробная регламентация импортa целевого и его рефундации, в т.ч. по заявлению пациента с PESEL или с паспортом, если PESEL нет","Отдельный учёт пациентов с правами по координации ЕС: личный идентификационный номер и данные иностранной институции на рецептах","Расширение и упорядочение рефундации редких («сиротских») лекарств, с новой многофакторной оценкой","Уточнение данных в рецептах и отчётности аптек (коды болезней ICD‑10, номера документов, коды для координации ЕС и пр.)"],"affected_groups":["Все застрахованные пациенты NFZ, включая иностранцев","Иностранцы без номера PESEL, подающие заявки на индивидуальную рефундацию импортируемых лекарств/питания","Пациенты, имеющие право на лечение по правилам координации ЕС (EHIC, S1 и др.)","Аптеки и врачи, выписывающие рецепты иностранцам"],"practical_impact":"В повседневности у иностранцев с правом на NFZ изменится форма рецептов и заявлений: чаще потребуется указывать PESEL либо данные паспорта/личный номер по координации ЕС. Потенциально возрастает доступность дорогостоящих и редких лекарств за счёт упрощённых и быстрее проводимых процедур рефундации.","effective_date":"Закон вступает в силу 1 января 2027 г., за исключением указанных статей, которые начнут действовать: через 14 дней, через 6 месяцев от дня оглашения, либо с 1 апреля 2027 г., 1 июля 2027 г. и 1 января 2028 г.","confidence":0.88,"rationale":"Акт комплексно меняет правила рефундации и доступа к лекарствам в системе NFZ, что прямо затрагивает и иностранцев‑пациентов, но не меняет специальных иммиграционных режимов, поэтому это социальная сфера средней важности.","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-09-v9","input_chars":495380,"truncated":false,"text_source":"documents","created_at":"2026-09-30T11:32:33Z","input_tokens":154731,"output_tokens":1760,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12398102/13129955/13129956/dokument782506.zip","source_kind":"rcl","revision":1,"text_sha256":"524157fa25a212119ccdf0eaa03ac7361481e0897a566f90548b9b3a13c50ed6","law_sha256":"ba40ef050ccbcbe4812e32bd7981f599b3c5ccf103eeb19131577128dc57c845","source_checked_at":"2026-09-30T11:32:33Z"}',10,'RCL/12398102','2026-09-30T11:32:33+00:00');
INSERT INTO "analysis_memo" VALUES('22f3e42631fcb9a27a0e8fce717c9dae7262d1fa44cfa30e27d0be54c68ea2fe','{"triage":{"affects_foreigners":false,"confidence":0.9,"rationale":"Законопроект касается изменения порогов налогообложения PIT и программы сотрудничества с крупными налогоплательщиками CIT, не затрагивая специфических положений о пребывании, работе или правах иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":6326,"output_tokens":104,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3156','2026-09-30T12:58:27+00:00');
INSERT INTO "bills" VALUES(10,'258','Poselski projekt ustawy o rekompensatach za szkody wyrządzone przez ptaki','2026-09-17T09:04:25+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"258","title":"Poselski projekt ustawy o rekompensatach za szkody wyrządzone przez ptaki","description":"projekt dotyczy umożliwienia wypłaty rekompensat ze środków budżetu państwa, za szkody wyrządzone przez ptaki roślinożerne w uprawach na gruntach ornych oraz kormorana na gruntach pod stawami rybnymi","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2024-01-22","document_date":"2024-01-22","change_date":"2026-09-17T09:04:25Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":["1387"]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-09-18T09:54:10+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'316','Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o asystencji osobistej osób z niepełnosprawnościami','2026-09-18T09:10:25+00:00','2026-09-18',1,'analyzed','[]','{"term":10,"number":"316","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o asystencji osobistej osób z niepełnosprawnościami","description":"projekt dotyczy systemowego uregulowania korzystania przez osoby z niepełnosprawnościami z usługi asystencji osobistej i stworzenia w ten sposób trwałych warunków dla osób z niepełnosprawnościami do realizacji możliwie pełnego samodzielnego życia","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2024-03-04","document_date":"2024-03-04","change_date":"2026-09-18T09:10:25Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":["1929","1933"]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2024-03-04","print_number":"316","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2024-03-11","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2024-04-24","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2024-04-24","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2024-10-01","sitting_num":18,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2024-10-01","committee_code":"PSR","sub_committee":false,"children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-05-14","sub_committee":false,"children":[{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-05-14","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/spr_316_1929_1933.pdf","sub_committee":true,"minority_motions":0,"children":[]},{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-07-08","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/spr_316_1929_1933_1.pdf","sub_committee":true,"minority_motions":0,"children":[]},{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-07-30","print_number":"2792","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2792/2792.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":14,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-02","sitting_num":64,"decision":"niedokończone II czytanie","sub_committee":false,"children":[]}]','942080c2e359c871d443ab63f7304df360b75913c6b2dbbdc3c863c110be94a2','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Законопроект вводит государственную услугу персонального ассистента (asystencja osobista) для людей с инвалидностью. Право на неё получают не только граждане Польши, но и определённые категории иностранцев с легальным пребыванием в Польше. Услуга бесплатная, назначается решением starosty powiatu.","key_changes":["Право на услугу у иностранцев с pobyt stały, pobyt rezydenta długoterminowego UE","Право у лиц с zezwolenie na pobyt czasowy по art. 159 ust. 1 pkt 1 lit. c/d или art. 186 ust. 1 pkt 3","Право у лиц со статусом беженца или дополнительной защитой","Право у граждан ЕС/EFTA/Швейцарии и членов их семей с правом пребывания","К заявлению иностранец прилагает документ, дающий право на пребывание"],"affected_groups":["иностранцы с постоянным пребыванием","резиденты ЕС","обладатели некоторых zezwoleń na pobyt czasowy","беженцы и лица с дополнительной защитой","граждане ЕС/EFTA и члены их семей"],"practical_impact":"Иностранец с указанным видом пребывания и решением об уровне потребности в поддержке (70–100 баллов) сможет подать заявление в starostwo powiatowe и бесплатно получать от 40 до 200 часов помощи ассистента в месяц.","effective_date":"Закон вступает в силу 1 января 2025 г., кроме art. 11 ust. 3-6 и art. 30 ust. 2 pkt 2 (с 1 января 2026 г.) и части art. 4 ust. 1 для 70–84 баллов (с 1 января 2027 г.).","confidence":0.88,"rationale":"Новая социальная услуга прямо перечисляет категории иностранцев, имеющих на неё право, что относится к социальной сфере.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":966,"truncated":false,"text_source":"scan","created_at":"2026-09-14T21:58:20Z","input_tokens":124658,"output_tokens":794,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/316/316.pdf","source_kind":"print","revision":1,"text_sha256":"9deeeb9f5b26d0c47bcab860623124c40657b55ce58f4547f0358a2cf295bc49","source_checked_at":null}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-19T13:56:39+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"comparison":{"same_substance":false,"summary":"Президентский проект даёт наиболее узкий круг иностранцев (без карты с ''dostęp do rynku pracy'' и большинства ВНЖ), решение выдаёт starosta, объём 40–200 часов при 70–100 баллах поддержки; заявление подаётся в starostwo, а не электронно.","differences":["Решение принимает starosta powiatu, а в druk 1929 и 1933 — wojewódzki zespół ds. orzekania o niepełnosprawności","Круг иностранцев уже: нет карты с ''dostęp do rynku pracy'', ст. 127, 137a, 151 и др., в отличие от druk 1929 и 1933","Объём помощи 40–200 часов в месяц против 20–240 в druk 1929 и 1933","Порог поддержки 70–100 баллов сразу, без поэтапного снижения из druk 1929 (90→85→80)","Заявление в starostwo powiatowe, а не только электронно (druk 1929) или через систему ZUS (druk 1933)"],"confidence":0.85},"compared_with":["1929","1933"],"model":"claude-opus-5","prompt_version":"2026-09-v7","created_at":"2026-09-14T21:58:29Z","input_tokens":2233,"output_tokens":375,"cache_read_input_tokens":0,"cache_creation_input_tokens":1216}',NULL,NULL,0,NULL,NULL,NULL,'full','relevant_analysis');
INSERT INTO "bills" VALUES(10,'1387','Poselski projekt ustawy o zmianie ustawy o ochronie przyrody oraz niektórych innych ustaw','2026-09-17T09:04:25+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:migracja"]','{"term":10,"number":"1387","title":"Poselski projekt ustawy o zmianie ustawy o ochronie przyrody oraz niektórych innych ustaw","description":"projekt dotyczy m. in. dodania do katalogu gatunków m. in. kormorana czarnego, żurawia, dzikich gęsi z rodzaju Anser, łabędzi, kruka i czapli siwej, za których szkody przysługuje rekompensata, określenia podmiotu odpowiedzialnego za szacowanie i wypłatę odszkodowań (dyrektor oddziału terenowego Krajowego Ośrodka Wsparcia rolnictwa), zapewnienia udziału izb rolniczych oraz jednostek doradztwa rolniczego w procesie potwierdzania i dokumentowania szkód wyrządzonych przez ptaki","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-06-03","document_date":"2025-06-03","change_date":"2026-09-17T09:04:25Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":["258"]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-06-03","print_number":"1387","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-06-10","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-07-22","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-07-22","committee_code":"RRW","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-07-22","committee_code":"OSZ","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2025-10-15","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2025-11-06","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2025-11-06","print_number":"1661","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/1661/1661.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-04","sitting_num":64,"decision":"skierowano ponownie do komisji w celu przedstawienia sprawozdania","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-04","committee_code":"RRW","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-04","committee_code":"OSZ","sub_committee":false,"children":[]}]}]','d2474d7d51b5add060aa5af65c6a52bfad813db3b84b58c4fb1a421a1844f927','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект касается изменения правил компенсации ущерба от птиц для сельского и рыбного хозяйства и не затрагивает статус, права или обязанности иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.95,"rationale":"Проект касается изменения правил компенсации ущерба от птиц для сельского и рыбного хозяйства и не затрагивает статус, права или обязанности иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v3","input_chars":18120,"truncated":true,"text_source":"excerpts","created_at":"2026-09-09T17:57:15Z","input_tokens":11014,"output_tokens":88,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-18T09:54:10+00:00',NULL,NULL,NULL,NULL,'{"representative":null,"representative_club":null,"clubs":[["PSL-TD",30]],"signatories":30,"unresolved":0}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'metadata','not_relevant');
INSERT INTO "bills" VALUES(10,'1654','Poselski projekt ustawy o utworzeniu Politechniki Włocławskiej','2026-09-02T17:31:16','2026-09-02',0,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"1654","title":"Poselski projekt ustawy o utworzeniu Politechniki Włocławskiej","description":"projekt dotyczy utworzenia z dniem 1 października 2025 r. publicznej uczelni technicznej - Politechniki Włocławskiej na bazie istniejącej Państwowej Akademii Nauk Stosowanych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-08-06","document_date":"2025-08-06","change_date":"2026-09-02T17:31:16","closure_date":"2026-09-02","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×2)','2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'1929','Rządowy projekt ustawy o asystencji osobistej osób z niepełnosprawnościami','2026-09-18T09:10:25+00:00','2026-09-18',1,'analyzed','["text:cudzoziemcy", "text:uchodzcy", "text:obywatelstwo", "text:wizy", "text:zezwolenie_pobyt", "text:pobyt_kwalifikowany", "text:ochrona_miedzynarodowa", "text:status_uchodzcy"]','{"term":10,"number":"1929","title":"Rządowy projekt ustawy o asystencji osobistej osób z niepełnosprawnościami","description":"projekt dotyczy systemowego uregulowania usługi asystencji osobistej jako obligatoryjnego i powszechnie dostępnego, w wybranej przez osobę z niepełnosprawnością formie, instrumentu wsparcia w codziennym funkcjonowaniu  m.in. przemieszczaniu się, prowadzeniu domu, załatwianiu spraw urzędowych, a także w pracy, nauce i kontaktach społecznych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-11-04","document_date":"2025-11-04","change_date":"2026-09-18T09:10:25Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-188-25","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-188-25","prints_considered_jointly":["316","1933"],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-11-04","print_number":"1929","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2025-11-07","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-11-07","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2025-11-21","sitting_num":45,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-11-21","committee_code":"PSR","sub_committee":false,"children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-05-14","sub_committee":false,"children":[{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-05-14","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/1929/attachment/spr_316_1929_1933.pdf","sub_committee":true,"minority_motions":0,"children":[]},{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-07-08","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/1929/attachment/spr_316_1929_1933_1.pdf","sub_committee":true,"minority_motions":0,"children":[]},{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-07-30","print_number":"2792","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2792/2792.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":14,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-02","sitting_num":64,"decision":"skierowano ponownie do komisji w celu przedstawienia sprawozdania","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po II czytaniu","stage_type":"CommitteeWork","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-15","print_number":"2792-A","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2792-A/2792-A.pdf","proposal":"przyjąć część poprawek","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/316_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-09-18","sub_committee":false,"voting":{"yes":443,"no":0,"abstain":0,"not_participating":17,"sitting":65,"voting_number":68,"date":"2026-09-18T08:48:50Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/65/68/pdf","clubs":[]},"children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}],"title_final":"o asystencji osobistej osób z niepełnosprawnościami"}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-11-04","print_number":"1929","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2025-11-07","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-11-07","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2025-11-21","sitting_num":45,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-11-21","committee_code":"PSR","sub_committee":false,"committee_name":"Komisja Polityki Społecznej i Rodziny","children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-05-14","sub_committee":false,"children":[{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-05-14","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/1929/attachment/spr_316_1929_1933.pdf","sub_committee":true,"minority_motions":0,"children":[]},{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-07-08","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/1929/attachment/spr_316_1929_1933_1.pdf","sub_committee":true,"minority_motions":0,"children":[]},{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-07-30","print_number":"2792","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2792/2792.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":14,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-02","sitting_num":64,"decision":"skierowano ponownie do komisji w celu przedstawienia sprawozdania","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po II czytaniu","stage_type":"CommitteeWork","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-15","print_number":"2792-A","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2792-A/2792-A.pdf","proposal":"przyjąć część poprawek","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/316_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-09-18","sub_committee":false,"voting":{"yes":443,"no":0,"abstain":0,"not_participating":17,"sitting":65,"voting_number":68,"date":"2026-09-18T08:48:50Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/65/68/pdf","clubs":[]},"children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','a7850ab982d317aea4cc4d3e291b6a095b79ce72df7649668633e1006adbd6df','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Закон вводит системную услугу личного ассистента (asystencja osobista) для людей с инвалидностью, финансируемую из госбюджета. Иностранцы с перечисленными видами легального пребывания в Польше получают это право наравне с гражданами. Услуга бесплатна, назначается решением wojewódzki zespół ds. orzekania o niepełnosprawności.","key_changes":["Право на услугу: ПМЖ, резидент ЕС, беженцы и доп. защита, граждане ЕС/ЕЭЗ/Швейцарии и члены семей","Включены разрешения по ст. 127, 137a, 139a, 139o, 151, 151b, 159 ust. 1, 186 ust. 1 pkt 3, научная виза, Brexit-соглашение","Карта побыту с отметкой ''dostęp do rynku pracy'' даёт право, кроме студентов, сезонных и краткосрочных работников","Объём: 20–240 часов в месяц (18–65 лет), 20–80 часов (13–18 лет); ставки 49–55 zł брутто в час","Заявление подаётся электронно; иностранец прилагает документ, дающий право на пребывание в Польше"],"affected_groups":["иностранцы с инвалидностью, имеющие ПМЖ или статус резидента ЕС","беженцы и лица с дополнительной защитой","граждане ЕС/ЕЭЗ/Швейцарии и члены их семей","обладатели карты побыту с отметкой ''dostęp do rynku pracy''","работники по внутрикорпоративному переводу и научные работники","граждане Великобритании по Brexit-соглашению"],"practical_impact":"Иностранец с инвалидностью, проживающий в Польше и имеющий соответствующее решение об уровне потребности в поддержке, может бесплатно получить личного ассистента; заявление подаётся только электронно с приложением документа о праве на пребывание.","effective_date":"Через 14 дней после опубликования, с исключениями: ст. 6 ust. 1 pkt 1 и часть ст. 8 — через 12 месяцев; ст. 6 ust. 1 pkt 2 и ст. 7 ust. 2–7 — через 14 месяцев; ст. 58–67 и ст. 99 — с первого дня месяца после 5 месяцев от опубликования.","confidence":0.85,"rationale":"Закон касается социальной поддержки и прямо перечисляет категории иностранцев, получающих право на услугу, но не затрагивает легализацию пребывания или работу.","changes_since_previous":["В перечень оснований добавлены разрешения по ст. 159 ust. 1 и ст. 186 ust. 1 pkt 3 ustawy o cudzoziemcach","Добавлены переходные ограничения максимума часов: 200 часов в 2028 г. и 220 часов в 2029 г.","Уточнены сроки рассмотрения заявлений: до 120 дней (до 31.12.2028), 90 дней, затем 60 дней","Детализирован поэтапный запуск: 90 баллов — через 12/16 месяцев от публикации, 85 — через 17/21, 80 — с 01.09.2028/01.01.2029","Для лиц 13–18 лет и проживающих в учреждениях круглосуточного ухода — заявления с 01.05.2029, право с 01.01.2030"]},"model":"claude-opus-5","prompt_version":"2026-09-v9","input_chars":154338,"truncated":false,"text_source":"pdf","created_at":"2026-09-22T16:01:14Z","input_tokens":77754,"output_tokens":1429,"cache_read_input_tokens":2652,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/316_u3.pdf","source_kind":"text_after3","revision":3,"text_sha256":"ca08cb45cab92073c6425650560e9f2d84d0f354b7e9ed5ec8ec1b0136e2d2f2","source_checked_at":"2026-09-22T16:01:14Z"}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-30T18:32:40+00:00','{"term":10,"number":"RPW/36702/2025","title":"Rządowy projekt ustawy o asystencji osobistej osób z niepełnosprawnościami","description":"systemowego uregulowania usługi asystencji osobistej jako obligatoryjnego i powszechnie dostępnego, w wybranej przez osobę z niepełnosprawnością formie, instrumentu wsparcia w codziennym funkcjonowaniu  m.in. przemieszczaniu się, prowadzeniu domu, załatwianiu spraw urzędowych, a także w pracy, nauce i kontaktach społecznych","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2025-11-04","print_number":"1929","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["1929-001", "1929-002", "1929-003", "1929-004", "1929-005"]',NULL,'2026-09-18','{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-11-04","print_number":"1929","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2025-11-07","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-11-07","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2025-11-21","sitting_num":45,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-11-21","committee_code":"PSR","sub_committee":false,"committee_name":"Komisja Polityki Społecznej i Rodziny","children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-05-14","sub_committee":false,"children":[{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-05-14","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/1929/attachment/spr_316_1929_1933.pdf","sub_committee":true,"minority_motions":0,"children":[]},{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-07-08","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/1929/attachment/spr_316_1929_1933_1.pdf","sub_committee":true,"minority_motions":0,"children":[]},{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-07-30","print_number":"2792","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2792/2792.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":14,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-02","sitting_num":64,"decision":"skierowano ponownie do komisji w celu przedstawienia sprawozdania","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po II czytaniu","stage_type":"CommitteeWork","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-15","print_number":"2792-A","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2792-A/2792-A.pdf","proposal":"przyjąć część poprawek","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/316_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-09-18","sub_committee":false,"voting":{"yes":443,"no":0,"abstain":0,"not_participating":17,"sitting":65,"voting_number":68,"date":"2026-09-18T08:48:50Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/65/68/pdf","clubs":[]},"children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}],"closure_date":"2026-09-18","passed":true,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/316_u3.pdf","kind":"text_after3","extra_urls":[]},"analysis_sha256":"ca08cb45cab92073c6425650560e9f2d84d0f354b7e9ed5ec8ec1b0136e2d2f2","analysis_revision":3,"seen_supplements":["1929-001","1929-002","1929-003","1929-004","1929-005"]}',0,NULL,'{"url":"https://www.senat.gov.pl/prace/proces-legislacyjny-w-senacie/ustawy-uchwalone-przez-sejm/ustawy-uchwalone-przez-sejm/ustawa,2170.html","title":"Ustawa o asystencji osobistej osób z niepełnosprawnościami","print_number":"832","received":"2026-09-22","committees":[{"id":233,"name":"Komisja Rodziny, Polityki Senioralnej i Społecznej","email":"krpss@senat.gov.pl"}],"committee_sittings":[]}',NULL,'full','telegram_thread');
INSERT INTO "bills" VALUES(10,'1933','Poselski projekt ustawy o asystencji osobistej osób z niepełnosprawnościami','2026-09-18T09:10:25+00:00','2026-09-18',1,'analyzed','["text:cudzoziemcy", "text:uchodzcy", "text:obywatelstwo", "text:wizy", "text:zezwolenie_pobyt", "text:pobyt_kwalifikowany", "text:ochrona_miedzynarodowa", "text:status_uchodzcy"]','{"term":10,"number":"1933","title":"Poselski projekt ustawy o asystencji osobistej osób z niepełnosprawnościami","description":"projekt dotyczy systemowego uregulowania dostępu do formy wsparcia, jaką jest asystencja osobista","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-10-16","document_date":"2025-10-16","change_date":"2026-09-18T09:10:25Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":["316","1929"]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-10-16","print_number":"1933","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-10-27","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2025-11-07","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-11-07","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2025-11-21","sitting_num":45,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-11-21","committee_code":"PSR","sub_committee":false,"children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-05-14","sub_committee":false,"children":[{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-05-14","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/1933/attachment/spr_316_1929_1933.pdf","sub_committee":true,"children":[]},{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-07-08","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/1933/attachment/spr_316_1929_1933_1.pdf","sub_committee":true,"children":[]},{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-07-30","print_number":"2792","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2792/2792.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-02","sitting_num":64,"decision":"niedokończone II czytanie","sub_committee":false,"children":[]}]','aa0cd7575fa6ece82523226dcfdadded598ef0d411a0fd5dbb8e351cff1d25ad','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект вводит системную услугу личного ассистента для людей с инвалидностью, финансируемую из госбюджета. В законе прямо перечислены категории иностранцев, имеющих право подать заявление: граждане ЕС/ЕЭЗ/Швейцарии, обладатели ПМЖ, статуса долгосрочного резидента ЕС, беженцы, лица с картой побыта с отметкой «доступ к рынку труда» и др. Обязательное условие — проживание в Польше в период пользования услугой.","key_changes":["Право на бесплатную ассистенцию для иностранцев с ПМЖ, статусом резидента ЕС, беженцев и лиц с доп. защитой","Право для граждан ЕС/ЕЭЗ/Швейцарии и членов их семей с правом пребывания","Право для обладателей карты побыта с отметкой «dostęp do rynku pracy», кроме сезонных работников, студентов и работающих по визе","Включены обладатели ВНЖ по ст. 127, 137a, 139a, 139o, 151, 151b, 159, 186 ustawy o cudzoziemcach и научные визы","Требование фактического проживания в Польше; заявление подаётся электронно, нужен PESEL или документ, удостоверяющий личность","Иностранцы также могут работать личными ассистентами (требуется внесение в Rejestr asystentów)"],"affected_groups":["Иностранцы с инвалидностью, имеющие ПМЖ или статус резидента ЕС","Беженцы и лица с дополнительной защитой","Граждане ЕС/ЕЭЗ/Швейцарии и члены их семей","Обладатели карты побыта с доступом к рынку труда","Иностранцы, желающие работать личными ассистентами"],"practical_impact":"Иностранцы указанных категорий с инвалидностью смогут подать заявление на бесплатную помощь личного ассистента (от 20 до 240 часов в месяц) через электронную систему ZUS; решение выдаёт wojewódzki zespół ds. orzekania o niepełnosprawności на срок от 1 до 5 лет. Исключены лица с краткосрочными разрешениями (до 6-9 месяцев), студенты, сезонные работники и работающие по визе.","effective_date":"Закон вступает в силу 1 января 2027 г., за исключением: положений о задачах Уполномоченного, госзакупках и лимитах расходов — через 14 дней после опубликования; ст. 51–60 и 122 — с 30 июня 2026 г.; ст. 6 ч. 1 и ст. 7 — через 14 месяцев после опубликования. Фактическое оказание услуг начинается с 1 апреля 2027 г. (для лиц с 90+ баллами), с 1 января 2028 г. — для лиц с 85+ баллами и подростков 13–18 лет.","confidence":0.9,"rationale":"Законопроект напрямую определяет круг иностранцев, имеющих право на новую социальную услугу, что относится к социальной сфере (услуги, льготы) без влияния на легализацию пребывания.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":625066,"truncated":false,"text_source":"pdf","created_at":"2026-09-09T17:57:07Z","input_tokens":305132,"output_tokens":1100,"cache_read_input_tokens":2118,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/1933/1933.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-19T13:56:39+00:00','{"term":10,"number":"RPW/34400/2025","title":"Poselski projekt ustawy o asystencji osobistej osób z niepełnosprawnościami","description":"systemowego uregulowania dostępu do formy wsparcia, jaką jest asystencja osobista","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2025-10-16","print_number":"1933","eu_related":false,"public_consultation":true,"consultation_start":"2025-10-17","consultation_end":"2025-11-16","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,'{"representative":null,"representative_club":null,"clubs":[["Lewica",20],["Polska2050",10],["Centrum",8],["niez.",1]],"signatories":39,"unresolved":0}','[{"kind": "committee", "ref": "PSR/139/2026-09-15", "date": "2026-09-15", "end_date": null, "start_time": "08:30:00", "committee_code": "PSR", "committee_name": "Komisja Polityki Społecznej i Rodziny", "sitting_number": 139, "room": "sala im. Olgi Krzyżanowskiej (nr 412, bud. U)", "text": "Rozpatrzenie poprawek zgłoszonych w czasie drugiego czytania do projektu ustawy o asystencji osobistej osób z niepełnosprawnościami (druki nr 316, 1929, 1933 i 2792).", "video_url": "https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=DB511B56293B5C6FC1258E6E003B4E09"}]',NULL,NULL,NULL,NULL,NULL,'{"comparison":{"same_substance":false,"summary":"Депутатский проект почти совпадает с правительственным (druk 1929) по кругу иностранцев и объёму 20–240 часов, но прямо требует фактического проживания в Польше, допускает подачу по PESEL или документу личности и отдельно регулирует работу иностранцев ассистентами через Rejestr asystentów.","differences":["druk 1929: не упоминает Rejestr asystentów и работу иностранцев в роли ассистентов","druk 316: круг иностранцев уже (без карты с ''dostęp do rynku pracy'' и научных виз)","druk 316: заявление в starostwo, решение starosty; здесь — электронно, решение wojewódzki zespół","druk 316: 40–200 часов и порог 70–100 баллов; здесь 20–240 часов","druk 1929: этапный порог баллов (90→85→80) и ставка 49–55 zł/час не указаны в этом проекте"],"confidence":0.7},"compared_with":["316","1929"],"model":"claude-opus-5","prompt_version":"2026-09-v7","created_at":"2026-09-14T21:58:38Z","input_tokens":2233,"output_tokens":339,"cache_read_input_tokens":1216,"cache_creation_input_tokens":0}',NULL,NULL,0,NULL,NULL,NULL,'full','relevant_analysis');
