INSERT INTO "bills" VALUES(10,'2394','Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o rozwoju portów morskich o podstawowym znaczeniu dla gospodarki narodowej oraz o zmianie niektórych innych ustaw','2026-09-01T17:34:40+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"2394","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o rozwoju portów morskich o podstawowym znaczeniu dla gospodarki narodowej oraz o zmianie niektórych innych ustaw","description":"projekt dotyczy określenia inwestycji o strategicznym znaczeniu dla rozwoju portów morskich o podstawowym znaczeniu dla gospodarki narodowej w rozumieniu ustawy z dnia 20 grudnia 1996 r. o portach i przystaniach morskich","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-10-21","document_date":"2025-10-17","change_date":"2026-09-01T17:34:40Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-10-21","print_number":"2394","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-10-27","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-01","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"INF","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"GMZ","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-10-21","print_number":"2394","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-10-27","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","