INSERT INTO "bills" VALUES(10,'2410','Rządowy projekt ustawy o zmianie ustawy o przygotowaniu i realizacji inwestycji w zakresie obiektów energetyki jądrowej oraz inwestycji towarzyszących oraz niektórych innych ustaw','2026-08-27T09:15:41+00:00','2026-07-03',1,'analyzed','["text:legalizacja", "text:uznawanie_kwalifikacji"]','{"term":10,"number":"2410","title":"Rządowy projekt ustawy o zmianie ustawy o przygotowaniu i realizacji inwestycji w zakresie obiektów energetyki jądrowej oraz inwestycji towarzyszących oraz niektórych innych ustaw","description":"projekt dotyczy doprecyzowania, które przepisy Prawa budowlanego mają zastosowanie, gdy pozwolenie na budowę dotyczy tylko części obiektu jądrowego lub etapu inwestycji, wprowadzenia nowej kategorii decyzji - pozwolenie na budowę dotyczące wstępnych robót budowlanych przy obiekcie jądrowym.\nProjekt umożliwia podział inwestycji jądrowej na etapy, także dla części obiektów, które nie mogą samodzielnie funkcjonować; wprowadzenie wymogu \nposiadania zgody Prezesa Państwowej Agencji Atomistyki na roboty budowlane, które mają znaczenie dla bezpieczeństwa jądrowego i ochrony radiologicznej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-03-31","document_date":"2026-03-30","change_date":"2026-08-27T09:15:41Z","closure_date":"2026-07-03","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-36-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-36-26","prints_considered_jointly":[],"eli":"DU/2026/1097","display_address":"Dz.U. 2026 poz. 1097","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001097","stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-03-31","print_number":"2410","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-04-14","sub_committee":false,"children":[{"stage_name":"Skierowanie",