INSERT INTO "bills" VALUES(10,'2700','Rządowy projekt ustawy o zmianie ustawy o publicznym transporcie zbiorowym oraz niektórych innych ustaw','2026-09-02T08:24:32','2026-07-31',1,'skipped_text_prefilter','["text:legalizacja", "text:przekraczanie_granicy"]','{"term":10,"number":"2700","title":"Rządowy projekt ustawy o zmianie ustawy o publicznym transporcie zbiorowym oraz niektórych innych ustaw","description":"projekt dotyczy poprawy dostępności transportu publicznego, szczególnie na obszarach wiejskich i w mniejszych miejscowościach oraz skuteczniejszego przeciwdziałania wykluczeniu transportowemu","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-11","document_date":"2026-06-11","change_date":"2026-09-02T08:24:32","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: weak patterns only (legalizacja×2, przekraczanie_granicy×3)','2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2701','Komisyjny projekt ustawy o zmianie ustawy o rehabilitacji zawodowej i społecznej oraz zatrudnianiu osób niepełnosprawnych','2026-08-27T11:20:22','2026-07-17',1,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"2701","title":"Komisyjny projekt ustawy o zmianie ustawy o rehabilitacji zawodowej i społecznej oraz zatrudnianiu osób niepełnosprawnych","description":"projekt dotyczy stworzenia odrębnej, szczególnej podstawy prawnej umożliwiającej PEFRON nieodpłatne przekazywanie osobom z niepełnosprawnościami oraz rodzinom, których członkami są osoby z niepełnosprawnościami, środków materialnych i niematerialnych pochodzących z rezerw strategicznych, udostępnionych Funduszowi w celu realizacji programów","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-05-28","document_date":"2026-05-27","change_date":"2026-08-27T11:20:22","closure_date":"2026-07-17","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2737','Rządowy projekt ustawy o zmianie ustawy - Kodeks spółek handlowych oraz ustawy o zmianie ustawy - Kodeks spółek handlowych oraz niektórych innych ustaw','2026-09-24T13:01:18+00:00','2026-09-04',1,'skipped_text_prefilter','[]','{"term":10,"number":"2737","title":"Rządowy projekt ustawy o zmianie ustawy - Kodeks spółek handlowych oraz ustawy o zmianie ustawy - Kodeks spółek handlowych oraz niektórych innych ustaw","description":"projekt dotyczy uproszczenia zasad funkcjonowania spółek z ograniczoną odpowiedzialnością oraz dostosowania je do obrotu cyfrowego. Zmiany mają ułatwić prowadzenie firm, w szczególności w sytuacjach, gdy wspólnicy kontaktują się zdalnie lub przebywają za granicą. Nowe przepisy ograniczają wymogi dotyczące papierowych dokumentów i podpisów, umożliwiając częstsze korzystanie z formy elektronicznej, np. e-maila lub skanu dokumentu. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-22","document_date":"2026-06-19","change_date":"2026-09-24T13:01:18Z","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-09-25T13:35:21+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2750','Komisyjny projekt ustawy zmieniającej ustawę o zmianie ustawy - Prawo energetyczne oraz niektórych innych ustaw','2026-09-17T16:19:53+00:00','2026-07-31',1,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"2750","title":"Komisyjny projekt ustawy zmieniającej ustawę o zmianie ustawy - Prawo energetyczne oraz niektórych innych ustaw","description":"projekt dotyczy zmiany przepisów w zakresie obowiązku wniesienia albo uzupełnienia zaliczki na poczet opłaty za przyłączenie do sieci. Projekt nie ingeruje w konstrukcję zaliczki, lecz doprecyzowuje zakres podmiotowy i czasowy przepisów przejściowych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-18","document_date":"2026-06-18","change_date":"2026-09-17T16:19:53Z","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-09-07T13:52:14+00:00','2026-09-18T19:03:51+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2769','Senacki projekt ustawy o organach właściwych i postępowaniach w sprawach reklamy politycznej oraz odpowiedzialności za naruszenie obowiązków w tych sprawach','2026-09-24T13:03:54+00:00','2026-09-04',1,'skipped_text_prefilter','["text:obywatele_innych_panstw"]','{"term":10,"number":"2769","title":"Senacki projekt ustawy o organach właściwych i postępowaniach w sprawach reklamy politycznej oraz odpowiedzialności za naruszenie obowiązków w tych sprawach","description":"projekt dotyczy ustanowienia przepisów służących stosowaniu rozporządzenia Parlamentu Europejskiego i Rady (UE) 2024/900 z dnia 13 marca 2024 r. W myśl projektu organem wiodącym, któremu powierzone zostaną zadania w zakresie ww. rozporządzenia  oraz nadzór nad jego stosowaniem będzie PKW, a pozostałymi organami będą: Prezes UKE, KRRiT, Prezes UKOiK oraz Prezes UODO. Postępowania będą się toczyć w trybie przewidzianym w kpa.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-26","document_date":"2026-06-25","change_date":"2026-09-24T13:03:54Z","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":true,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (obywatele_innych_panstw×1)','2026-09-07T13:52:14+00:00','2026-09-25T13:35:21+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2778','Rządowy projekt ustawy o zmianie ustawy - Prawo ochrony środowiska','2026-09-04T10:24:02','2026-07-31',1,'skipped_text_prefilter','[]','{"term":10,"number":"2778","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo ochrony środowiska","description":"projekt dotyczy wzmocnienia prawa obywateli do ochrony zdrowia i czystego powietrza. Mieszkańcy, przedsiębiorcy i organizacje społeczne będą mogli składać skargi - bez wykazania interesu prawnego - na programy ochrony powietrza, ich aktualizacje, plany działań krótkoterminowych, a także na bezczynność organów odpowiedzialnych za ich przyjęcie. Programy ochrony powietrza są tworzone wtedy, gdy w danym regionie przekroczone zostają normy jego jakości.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-06","document_date":"2026-07-03","change_date":"2026-09-04T10:24:02","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2799','Rządowy projekt ustawy o zmianie ustawy o przeciwdziałaniu nieuczciwym praktykom rynkowym oraz ustawy o prawach konsumenta','2026-09-24T13:07:29+00:00','2026-09-04',1,'analyzed','[]','{"term":10,"number":"2799","title":"Rządowy projekt ustawy o zmianie ustawy o przeciwdziałaniu nieuczciwym praktykom rynkowym oraz ustawy o prawach konsumenta","description":"projekt dotyczy dostosowania polskich przepisów do prawa Unii Europejskiej, których celem jest wspieranie konsumentów w podejmowaniu bardziej świadomych decyzji zakupowych. Wprowadzone zmiany ułatwią rozpoznawanie rzetelnych informacji o produktach oraz ograniczą możliwość stosowania przez przedsiębiorców wprowadzających w błąd deklaracji dotyczących wpływu produktów na środowisko (tzw. \"greenwashingu\")","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-10","document_date":"2026-07-10","change_date":"2026-09-24T13:07:29Z","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":true,"rcl_num":"RM-0610-99-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-99-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-10","print_number":"2799","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-07-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"OSZ","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"GOR","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-07-29","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-09-02","sub_committee":false,"children":[