INSERT INTO "bills" VALUES(10,'2825','Poselski projekt ustawy o zmianie ustawy - Prawo wodne, ustawy o gospodarce nieruchomościami oraz ustawy o szczególnych rozwiązaniach związanych z usuwaniem skutków powodzi','2026-09-01T19:46:15',NULL,0,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"2825","title":"Poselski projekt ustawy o zmianie ustawy - Prawo wodne, ustawy o gospodarce nieruchomościami oraz ustawy o szczególnych rozwiązaniach związanych z usuwaniem skutków powodzi","description":"projekt dotyczy wprowadzenia mechanizmu pozwalającego przekazywać do zasobu nieruchomości Skarbu Państwa nieruchomości, które stały się zbędne dla działalności Wód Polskich","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-06","document_date":"2026-07-06","change_date":"2026-09-01T19:46:15","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2837','Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku dochodowym od osób prawnych','2026-09-24T13:11:27+00:00','2026-09-18',1,'skipped_text_prefilter','[]','{"term":10,"number":"2837","title":"Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku dochodowym od osób prawnych","description":"projekt dotyczy uproszczenia obowiązków informacyjnych dla przedsiębiorców dotyczących cen transferowych, czyli rozliczeń pomiędzy firmami należącymi do tej samej grupy kapitałowej. Nowe rozwiązania ograniczą obowiązki administracyjne, zmniejszą koszty prowadzenia działalności gospodarczej i ułatwią wywiązywanie się z obowiązków sprawozdawczych. Nowe przepisy realizują działania deregulacyjne rządu","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-22","document_date":"2026-07-22","change_date":"2026-09-24T13:11:27Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-09-25T13:35:21+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2838','Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług','2026-09-24T12:58:00+00:00','2026-09-18',1,'skipped_text_prefilter','[]','{"term":10,"number":"2838","title":"Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług","description":"projekt dotyczy nowelizacji obowiązujących przepisów ustawy o VAT w związku ze zmianami przepisów unijnych dotyczących zniesienia zwolnienia z należności celnych przesyłek o wartości do 150 euro. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-23","document_date":"2026-07-22","change_date":"2026-09-24T12:58:00Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-09-25T13:35:21+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
