INSERT INTO "bills" VALUES(10,'2846','Rządowy projekt ustawy o szczególnych rozwiązaniach związanych z organizacją XXVI Światowego Jamboree Skautowego w Polsce w 2027 r.','2026-09-24T12:59:51+00:00','2026-09-18',1,'analyzed','["text:obywatelstwo", "text:wizy", "text:straz_graniczna", "text:schengen"]','{"term":10,"number":"2846","title":"Rządowy projekt ustawy o szczególnych rozwiązaniach związanych z organizacją XXVI Światowego Jamboree Skautowego w Polsce w 2027 r.","description":"projekt dotyczy uregulowania współpracy administracji i służb odpowiedzialnych za przygotowanie XXVI Światowego Jamboree Skautowego. Wydarzenie odbędzie się od 29 lipca do 9 sierpnia 2027 r. na Wyspie Sobieszewskiej w Gdańsku. Organizatorem jest Związek Harcerstwa Polskiego we współpracy ze Światową Organizacją Ruchu Skautowego.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-23","document_date":"2026-07-23","change_date":"2026-09-24T12:59:51Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-113-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-113-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-23","print_number":"2846","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-07-27","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-27","committee_code":"ASW","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-07-30","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-09-02","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-02","print_number":"3024","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3024/3024.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-16","sitting_num":65,"decision":"niezwłocznie przystąpiono do III czytania","sub_committee":false,"children":[]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-09-18","sub_committee":false,"voting":{"yes":411,"no":23,"abstain":0,"not_participating":26,"sitting":65,"voting_number":86,"date":"2026-09-18T09:15:44Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/65/86/pdf","clubs":[]},"children":[]}]},{"stage_name":"Stanowisko Senatu","stage_type":"SenatePosition","date":"2026-09-24","position":"nie wniósł poprawek","sub_committee":false,"children":[]},{"stage_name":"Ustawę przekazano Prezydentowi do podpisu","stage_type":"ToPresident","date":"2026-09-24","sub_committee":false,"children":[]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}],"title_final":"o szczególnych rozwiązaniach związanych z organizacją XXVI Światowego Jamboree Skautowego w Rzeczypospolitej Polskiej w 2027 r."}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-23","print_number":"2846","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-07-27","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-27","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-07-30","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-09-02","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-02","print_number":"3024","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3024/3024.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-16","sitting_num":65,"decision":"niezwłocznie przystąpiono do III czytania","sub_committee":false,"children":[]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-09-18","sub_committee":false,"voting":{"yes":411,"no":23,"abstain":0,"not_participating":26,"sitting":65,"voting_number":86,"date":"2026-09-18T09:15:44Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/65/86/pdf","clubs":[]},"children":[]}]},{"stage_name":"Stanowisko Senatu","stage_type":"SenatePosition","date":"2026-09-24","position":"nie wniósł poprawek","sub_committee":false,"children":[]},{"stage_name":"Ustawę przekazano Prezydentowi do podpisu","stage_type":"ToPresident","date":"2026-09-24","sub_committee":false,"children":[]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','0bc81a4f1c75a6a3ffb33276d41d39f25da8d379c0250301dadf5aa4c3b767b6','{"analysis":{"relevant":true,"score":3,"category":"legal_stay","summary":"Специальный закон об организации Всемирного скаутского Джамбори в Гданьске в 2027 году. Для иностранцев главное: участники освобождаются от консульского сбора за национальную и шенгенскую визу, а их заявления рассматриваются без лишней задержки. Остальные нормы касаются медицины, санитарии, строительства и безопасности.","key_changes":["Освобождение от консульского сбора за национальную визу и визу Шенген для участников Джамбори","Нужно приложить подтверждение регистрации участия или иной документ об участии","Рассмотрение «без излишней задержки», если консула уведомили не позднее чем за 6 недель до начала","Срок 6 недель не действует для глав государств, членов правительств, монархов и официальных делегаций","Волонтёры не из ЕС должны представить справки о несудимости из стран гражданства и проживания за 10 лет"],"affected_groups":["иностранные участники Всемирного скаутского Джамбори, нуждающиеся в визе","иностранные волонтёры, работающие с несовершеннолетними участниками","официальные иностранные делегации"],"practical_impact":"Иностранные участники Джамбори не платят консульский сбор за визу при наличии подтверждения регистрации и получают ускоренное рассмотрение при уведомлении консула за 6 недель. Волонтёры-иностранцы для работы с детьми обязаны собрать справки о несудимости из стран гражданства и проживания за последние 10 лет.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.85,"rationale":"Закон содержит визовые льготы (сфера легализации въезда), но узкие и разовые — только для участников одного мероприятия, поэтому оценка средняя.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":27534,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf","source_kind":"text_after3","revision":2,"text_sha256":"f4a3bf591d2ceebcf73b360901f38bb0fc2bf7f016acb504a4c15caecd85808a","source_checked_at":"2026-09-28T15:56:32Z"}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-30T18:32:40+00:00','{"term":10,"number":"RPW/25576/2026","title":"Rządowy projekt ustawy o szczególnych rozwiązaniach związanych z organizacją XXVI Światowego Jamboree Skautowego w Polsce w 2027 r.","description":"uregulowania współpracy administracji i służb odpowiedzialnych za przygotowanie XXVI Światowego Jamboree Skautowego. Wydarzenie odbędzie się od 29 lipca do 9 sierpnia 2027 r. na Wyspie Sobieszewskiej w Gdańsku. Organizatorem jest Związek Harcerstwa Polskiego we współpracy ze Światową Organizacją Ruchu Skautowego.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-07-23","print_number":"2846","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["2846-001", "2846-002"]',NULL,'2026-09-18','{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-23","print_number":"2846","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-07-27","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-27","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-07-30","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-09-02","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-02","print_number":"3024","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3024/3024.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-16","sitting_num":65,"decision":