INSERT INTO "bills" VALUES(10,'3013','Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Filipin o przekazywaniu osób skazanych, podpisanej w Warszawie dnia 8 czerwca 2026 r.','2026-09-16T07:14:51+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:obywatelstwo"]','{"term":10,"number":"3013","title":"Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Filipin o przekazywaniu osób skazanych, podpisanej w Warszawie dnia 8 czerwca 2026 r.","description":"projekt dotyczy uregulowania problematyki współpracy prawnej w sprawach karnych, w szczególności w zakresie przekazywania osób skazanych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-18","document_date":"2026-08-18","change_date":"2026-09-16T07:14:51Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-18","print_number":"3013","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-08-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-20","committee_code":"SPC","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-20","committee_code":"SZA","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-09-16","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-09-16","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-16","print_number":"3098","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3098/3098.pdf","proposal":"uchwalić projekt ustawy bez poprawek","sub_committee":false,"minority_motions":0,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-18","print_number":"3013","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-08-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-20","committee_code":"SPC","sub_committee":false,"committee_name":"Komisja Sprawiedliwości i Praw Człowieka","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-20","committee_code":"SZA","sub_committee":false,"committee_name":"Komisja Spraw Zagranicznych","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-09-16","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-09-16","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-16","print_number":"3098","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3098/3098.pdf","proposal":"uchwalić projekt ustawy bez poprawek","sub_committee":false,"minority_motions":0,"children":[]}]}]','6c3deb97eb69c85b1bfc1ec3610d83b1d58f013b66fa8e811c2e0b56bfd735dd','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект разрешает ратификацию договора между Польшей и Филиппинами о передаче осуждённых. Он касается лиц, отбывающих наказание в тюрьмах или психиатрических учреждениях одной страны, которые хотят отбывать его в стране своего гражданства. Передача возможна только с согласия самого осуждённого.","key_changes":["Согласие на ратификацию двустороннего договора с Филиппинами о передаче осуждённых","Передача возможна только при добровольном согласии осуждённого","Наказание при передаче не может быть ужесточено; отбытый срок засчитывается","Договор охватывает и тех, кто уже отбывает наказание до его вступления в силу","Центральный орган с польской стороны — Minister Sprawiedliwości; переписка на английском"],"affected_groups":["граждане Филиппин, осуждённые в Польше","граждане Польши, осуждённые на Филиппинах","члены их семей"],"practical_impact":"Осуждённый гражданин Филиппин, отбывающий наказание в Польше, сможет с собственного согласия ходатайствовать о переводе для отбывания наказания на родине; расходы конвоя в этом случае несёт филиппинская сторона.","effective_date":"Закон вступает в силу через 14 дней после опубликования.","confidence":0.9,"rationale":"Это ратификация двустороннего соглашения по уголовно-правовому сотрудничеству — косвенное влияние на иностранцев (граждан Филиппин) в Польше, без изменений в легализации пребывания.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":20750,"truncated":false,"text_source":"pdf","created_at":"2026-09-09T18:02:02Z","input_tokens":10660,"output_tokens":574,"cache_read_input_tokens":2118,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3013/3013.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-30T16:00:57+00:00',NULL,NULL,NULL,NULL,NULL,'[{"kind": "sejm", "ref": "sejm/66/2026-10-06", "date": "2026-10-06", "end_date": "2026-10-09", "start_time": null, "committee_code": null, "committee_name": null, "sitting_number": 66, "room": null, "text": "Sprawozdanie Komisji Spraw Zagranicznych oraz Komisji Sprawiedliwości i Praw Człowieka o rządowym projekcie ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Filipin o przekazywaniu osób skazanych, podpisanej w Warszawie dnia 8 czerwca 2026 r. (druki nr 3013 i 3098) - sprawozdawca poseł Anna Wojciechowska.", "video_url": null, "condition": null, "closed": false, "apply_email": null, "apply_by": null}]',NULL,NULL,NULL,NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-18","print_number":"3013","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-08-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-20","committee_code":"SPC","sub_committee":false,"committee_name":"Komisja Sprawiedliwości i Praw Człowieka","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-20","committee_code":"SZA","sub_committee":false,"committee_name":"Komisja Spraw Zagranicznych","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-09-16","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-09-16","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-16","print_number":"3098","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3098/3098.pdf","proposal":"uchwalić projekt ustawy bez poprawek","sub_committee":false,"minority_motions":0,"children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3013/3013.pdf","kind":"print","extra_urls":[]},"analysis_revision":1,"seen_supplements":[]}',0,NULL,NULL,NULL,'full','relevant_analysis');
