INSERT INTO "bills" VALUES(10,'3028','Rządowy projekt ustawy o zmianie ustawy o szczególnych rozwiązaniach służących realizacji ustawy budżetowej na rok 2026','2026-09-24T13:08:23+00:00','2026-09-04',1,'skipped_text_prefilter','[]','{"term":10,"number":"3028","title":"Rządowy projekt ustawy o zmianie ustawy o szczególnych rozwiązaniach służących realizacji ustawy budżetowej na rok 2026","description":"projekt dotyczy wprowadzenia rozwiązań umożliwiających sprawne wykonywanie budżetu państwa w 2026 r. w celu sfinansowania realizacji istotnych zadań publicznych w zakresie świadczeń wypłacanych z Funduszu emerytalno-rentowego","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-01","document_date":"2026-09-01","change_date":"2026-09-24T13:08:23Z","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-09-25T13:35:21+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3029','Rządowy projekt ustawy o zmianie niektórych ustaw w celu ochrony rolniczych funkcji produkcyjnych wsi','2026-09-16T07:12:17+00:00',NULL,0,'analyzed','["text:migracja", "text:legalizacja"]','{"term":10,"number":"3029","title":"Rządowy projekt ustawy o zmianie niektórych ustaw w celu ochrony rolniczych funkcji produkcyjnych wsi","description":"projekt dotyczy wzmocnienia ochrony działalności rolniczej oraz ograniczenia konfliktów społecznych związanych m.in. z postępującą urbanizacją obszarów wiejskich. Rolnicy prowadzący działalność zgodnie z prawem zyskają większą pewność, że typowe uciążliwości związane z produkcją rolną, takie jak hałas, zapachy czy odgłosy zwierząt, nie będą podstawą do nieuzasadnionego ograniczania ich działalności. Projekt zakłada także lepsze informowanie osób kupujących nieruchomości na wsi o możliwych uciążliwościach związanych z działalnością rolniczą. Projekt realizuje priorytet polityki Rady Ministrów.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-19","document_date":"2026-08-19","change_date":"2026-09-16T07:12:17Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-130-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-130-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-19","print_number":"3029","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-01","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-15","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","c