INSERT INTO "bills" VALUES(10,'2675','Poselski projekt ustawy o zmianie ustawy o szczególnych rozwiązaniach związanych z usuwaniem skutków powodzi oraz niektórych innych ustaw','2026-09-08T09:17:48+00:00','2026-07-31',1,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"2675","title":"Poselski projekt ustawy o zmianie ustawy o szczególnych rozwiązaniach związanych z usuwaniem skutków powodzi oraz niektórych innych ustaw","description":"projekt dotyczy umożliwienia właścicielom gruntów rolnych zniszczonych w wyniku powodzi przywrócenia właściwości produkcyjnych gleb poprzez usprawnienie i przyspieszenie procesu rekultywacji gruntów. W przypadku gdy rekultywacja gruntów będzie zbyt kosztowna lub gdy grunty rolne w przyszłości narażone będą na ponowne zalanie wodami powodziowymi proponuje się umożliwienie dokonania zmiany lokalizacji gruntów właścicieli prywatnych na lokalizację gdzie znajdują się obecnie grunty Skarbu Państwa.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-02-12","document_date":"2026-02-12","change_date":"2026-09-08T09:17:48Z","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"eli":"DU/2026/1155","display_address":"Dz.U. 2026 poz. 1155","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001155"}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-09-08T09:25:59+00:00','2026-09-09T14:39:55+00:00','{"term":10,"number":"RPW/5176/2026","title":"Poselski projekt ustawy o zmianie ustawy o szczególnych rozwiązaniach związanych z usuwaniem skutków powodzi oraz niektórych innych ustaw","description":"umożliwienia właścicielom gruntów rolnych zniszczonych w wyniku powodzi przywrócenia właściwości produkcyjnych gleb poprzez usprawnienie i przyspieszenie procesu rekultywacji gruntów. W przypadku gdy rekultywacja gruntów będzie zbyt kosztowna lub gdy grunty rolne w przyszłości narażone będą na ponowne zalanie wodami powodziowymi proponuje się umożliwienie dokonania zmiany lokalizacji gruntów właścicieli prywatnych na lokalizację gdzie znajdują się obecnie grunty Skarbu Państwa.","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-02-12","print_number":"2675","eu_related":false,"public_consultation":true,"consultation_start":"2026-02-13","consultation_end":"2026-03-15","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
