INSERT INTO "bills" VALUES(10,'RPW/30027/2026','Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz niektórych innych ustaw','2026-09-08T00:00:00+00:00',NULL,NULL,'skipped_prefilter','[]','{"term":10,"number":"RPW/30027/2026","title":"Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz niektórych innych ustaw","description":"usprawnienia zasad rozliczania VAT przy sprzedaży on-line towarów i usług w innych państwach Unii Europejskiej. Zmiany mają ułatwić przedsiębiorcom korzystanie z unijnego systemu OSS, ograniczyć obowiązki związane z rejestracją VAT w różnych krajach UE oraz doprecyzować przepisy dotyczące sprzedaży wysyłkowej.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-08","document_date":"2026-09-08","change_date":"2026-09-08T00:00:00Z","eu_related":true,"prints_considered_jointly":[],"applicant":"government"}',NULL,NULL,NULL,0,NULL,'2026-09-09T08:59:56+00:00','2026-09-09T08:59:56+00:00','{"term":10,"number":"RPW/30027/2026","title":"Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz niektórych innych ustaw","description":"usprawnienia zasad rozliczania VAT przy sprzedaży on-line towarów i usług w innych państwach Unii Europejskiej. Zmiany mają ułatwić przedsiębiorcom korzystanie z unijnego systemu OSS, ograniczyć obowiązki związane z rejestracją VAT w różnych krajach UE oraz doprecyzować przepisy dotyczące sprzedaży wysyłkowej.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-08","print_number":null,"eu_related":true,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
