INSERT INTO "bills" VALUES(10,'RCL/12402254','Projekt ustawy o zmianie ustawy o systemach homologacji pojazdów oraz ich wyposażenia oraz niektórych innych ustaw','2026-09-17T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:zezwolenie_pobyt", "text:pobyt_kwalifikowany", "text:straz_graniczna", "text:granica_panstwowa", "text:schengen"]','{"term":10,"number":"RCL/12402254","title":"Projekt ustawy o zmianie ustawy o systemach homologacji pojazdów oraz ich wyposażenia oraz niektórych innych ustaw","description":"TRANSPORT DROGOWY; HOMOLOGACJA POJAZDÓW I URZĄDZEŃ; transport. Numer i tytuł aktu prawnego Unii Europejskiej: rozporządzenia (WE) nr 715/2007 Parlamentu Europejskiego i Rady z dnia 20 czerwca 2007 r. w sprawie homologacji typu pojazdów silnikowych w odniesieniu do emisji zanieczyszczeń pochodzących z lekkich pojazdów pasażerskich i użytkowych (Euro 5 i Euro 6) oraz w sprawie dostępu do informacji dotyczących naprawy i utrzymania pojazdów 2) rozporządzenia Parlamentu Europejskiego i Rady (WE) nr 595/2009 z dnia 18 czerwca 2009 r. dotyczącego homologacji typu pojazdów silnikowych i silników w odniesieniu do emisji zanieczyszczeń pochodzących z pojazdów ciężarowych o dużej ładowności (Euro VI) i zmieniającego rozporządzenie (WE) nr 715/2007 i dyrektywę 2007/46/WE oraz uchylającego dyrektywy 80/1269/EWG, 2005/55/WE i 2005/78/WE 3) rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 167/2013 z dnia 5 lutego 2013 r. w sprawie homologacji i nadzoru rynku pojazdów rolniczych i leśnych 4) rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 168/2013 z dnia 15 stycznia 2013 r. w sprawie homologacji i nadzoru rynku pojazdów dwu– lub trzykołowych oraz czterokołowców 5) rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 540/2014 z dnia 16 kwietnia 2014 r. w sprawie poziomu dźwięku pojazdów silnikowych i zamiennych układów tłumiących oraz zmieniającego dyrektywę 2007/46/WE i uchylającego dyrektywę 70/157/EWG 6) rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/858 z dnia 30 maja 2018 r. w sprawie homologacji i nadzoru rynku pojazdów silnikowych i ich przyczep oraz układów, komponentów i oddzielnych zespołów technicznych przeznaczonych do tych pojazdów, zmieniającego rozporządzenie (WE) nr 715/2007 i (WE) nr 595/2009 oraz uchylającego dyrektywę 2007/46/WE","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-09-18","document_date":"2026-08-04","change_date":"2026-09-17T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12402254","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"5. Komitet Rady Ministrów do Spraw Cyfryzacji","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2026-08-04","sub_committee":false,"children":[]}]','41523b7083b3cfcb001ec827aa12e7290ae770b541462b4d111bdd32df77a41f','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект касается технических правил гомологации транспортных средств, регистрации автомобилей и обязанностей органов технадзора; упоминания obywatelstwo/PESEL и Straży Granicznej относятся к идентификации участников процедур регистрации, а не к правам или статусу иностранцев как таковых.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Проект касается технических правил гомологации транспортных средств, регистрации автомобилей и обязанностей органов технадзора; упоминания obywatelstwo/PESEL и Straży Granicznej относятся к идентификации участников процедур регистрации, а не к правам или статусу иностранцев как таковых.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v4","input_chars":19726,"truncated":true,"text_source":"excerpts","created_at":"2026-09-10T09:53:07Z","input_tokens":12655,"output_tokens":134,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"law_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-10T09:52:45+00:00','2026-09-30T15:59:51+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12402254,"title":"Projekt ustawy o zmianie ustawy o systemach homologacji pojazdów oraz ich wyposażenia oraz niektórych innych ustaw","applicant":"Minister Infrastruktury","wykaz_number":"UC95","wykaz_url":"https://www.gov.pl/web/premier/projekt-ustawy-o-zmianie-ustawy-o-systemach-homologacji-pojazdow-oraz-ich-wyposazenia-oraz-niektorych-innych-ustaw","created":"2025-09-18","modified":"2026-09-17","departments":["transport"],"keywords":["TRANSPORT DROGOWY","HOMOLOGACJA POJAZDÓW I URZĄDZEŃ"],"status":"otwarty","eu_note":"Numer i tytuł aktu prawnego Unii Europejskiej: rozporządzenia (WE) nr 715/2007 Parlamentu Europejskiego i Rady z dnia 20 czerwca 2007 r. w sprawie homologacji typu pojazdów silnikowych w odniesieniu do emisji zanieczyszczeń pochodzących z lekkich pojazdów pasażerskich i użytkowych (Euro 5 i Euro 6) oraz w sprawie dostępu do informacji dotyczących naprawy i utrzymania pojazdów 2) rozporządzenia Parlamentu Europejskiego i Rady (WE) nr 595/2009 z dnia 18 czerwca 2009 r. dotyczącego homologacji typu pojazdów silnikowych i silników w odniesieniu do emisji zanieczyszczeń pochodzących z pojazdów ciężarowych o dużej ładowności (Euro VI) i zmieniającego rozporządzenie (WE) nr 715/2007 i dyrektywę 2007/46/WE oraz uchylającego dyrektywy 80/1269/EWG, 2005/55/WE i 2005/78/WE 3) rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 167/2013 z dnia 5 lutego 2013 r. w sprawie homologacji i nadzoru rynku pojazdów rolniczych i leśnych 4) rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 168/2013 z dnia 15 stycznia 2013 r. w sprawie homologacji i nadzoru rynku pojazdów dwu– lub trzykołowych oraz czterokołowców 5) rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 540/2014 z dnia 16 kwietnia 2014 r. w sprawie poziomu dźwięku pojazdów silnikowych i zamiennych układów tłumiących oraz zmieniającego dyrektywę 2007/46/WE i uchylającego dyrektywę 70/157/EWG 6) rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/858 z dnia 30 maja 2018 r. w sprawie homologacji i nadzoru rynku pojazdów silnikowych i ich przyczep oraz układów, komponentów i oddzielnych zespołów technicznych przeznaczonych do tych pojazdów, zmieniającego rozporządzenie (WE) nr 715/2007 i (WE) nr 595/2009 oraz uchylającego dyrektywę 2007/46/WE","term_label":"X","stages":[{"id":13157116,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13157117,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2026-06-25","folders":[{"id":13157118,"name":"Projekt","modified":"2026-06-25","documents":[{"id":738041,"name":"projekt UC95.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12402254/13157117/13157118/dokument738041.pdf","created":"2025-09-18","author":"Minister Infrastruktury"},{"id":738042,"name":"projekt UC95.docx","url":"https://legislacja.rcl.gov.pl/docs//2/12402254/13157117/13157118/dokument738042.docx","created":"2025-09-18","author":"Minister Infrastruktury"},{"id":738043,"name":"uzasadnienie UC95.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12402254/13157117/13157118/dokument738043.pdf","created":"2025-09-18","author":"Minister Infrastruktury"},{"id":738044,"name":"uzasadnienie UC95.docx","url":"https://legislacja.rcl.gov.pl/docs//2/12402254/13157117/13157118/dokument738044.docx","created":"2025-09-18","author":"Minister Infrastruktury"},{"id":738045,"name":"OSR UC95.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12402254/13157117/13157118/dokument738045.pdf","created":"2025-09-18","