INSERT INTO "bills" VALUES(10,'RPW/30305/2026','Rządowy projekt ustawy o zmianie ustawy o postępowaniu w sprawach dotyczących pomocy publicznej oraz niektórych innych ustaw','2026-09-10T00:00:00+00:00',NULL,NULL,'linked','[]','{"term":10,"number":"RPW/30305/2026","title":"Rządowy projekt ustawy o zmianie ustawy o postępowaniu w sprawach dotyczących pomocy publicznej oraz niektórych innych ustaw","description":"zniesienia obowiązku przedstawiania zaświadczeń lub oświadczeń dotyczących udzielonej pomocy de minimis i pomocy de minimis w rolnictwie lub rybołówstwie przez podmioty ubiegające się o taką pomoc, jaki obecnie ciąży na nich zgodnie z art. 37 ust. 1 i 2 ustawy z dnia 30 kwietnia 2004 r. o postępowaniu w sprawach dotyczących pomocy publicznej. Nowe przepisy realizują działania deregulacyjne Rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-10","document_date":"2026-09-10","change_date":"2026-09-10T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"government"}',NULL,NULL,NULL,0,NULL,'2026-09-10T19:08:59+00:00','2026-09-11T09:51:12+00:00','{"term":10,"number":"RPW/30305/2026","title":"Rządowy projekt ustawy o zmianie ustawy o postępowaniu w sprawach dotyczących pomocy publicznej oraz niektórych innych ustaw","description":"zniesienia obowiązku przedstawiania zaświadczeń lub oświadczeń dotyczących udzielonej pomocy de minimis i pomocy de minimis w rolnictwie lub rybołówstwie przez podmioty ubiegające się o taką pomoc, jaki obecnie ciąży na nich zgodnie z art. 37 ust. 1 i 2 ustawy z dnia 30 kwietnia 2004 r. o postępowaniu w sprawach dotyczących pomocy publicznej. Nowe przepisy realizują działania deregulacyjne Rządu.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-10","print_number":"3088","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','3088',NU