um":50,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-01-21","committee_code":"SPC","sub_committee":false,"committee_name":"Komisja Sprawiedliwości i Praw Człowieka","children":[]},{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-01-21","sub_committee":false,"voting":{"yes":185,"no":232,"abstain":5,"not_participating":38,"sitting":50,"voting_number":5,"date":"2026-01-21T14:25:04Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/50/5/pdf","clubs":[]},"children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-02-10","sub_committee":false,"children":[{"stage_name":"Wysłuchanie publiczne","stage_type":"PublicHearing","date":"2026-02-10","sub_committee":false,"children":[]},{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-03","print_number":"3019","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3019/3019.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]}],"passed":false,"analysis_revision":1,"seen_supplements":["2107-001","2107-002","2107-003","2107-004"]}',0,NULL,NULL,NULL,'metadata','not_relevant');
INSERT INTO "bills" VALUES(10,'RCL/12402353','Projekt ustawy o rejestracji statków pod polską banderą','2026-09-11T00:00:00+00:00',NULL,NULL,'analyzed','["text:wizy", "text:straz_graniczna", "text:schengen", "text:obywatele_innych_panstw"]','{"term":10,"number":"RCL/12402353","title":"Projekt ustawy o rejestracji statków pod polską banderą","description":"STATKI MORSKIE; gospodarka morska","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-09-22","document_date":"2025-09-22","change_date":"2026-09-11T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12402353","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]}]','3a4cd1cf6419ab629ae84c39a944988eb5a9c153b6963f6d4b64dd40ca3f1f1d','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект касается регистрации морских судов под польским флагом: реестр переходит от izby morskie к директорам urzędów morskich, становится электронным и двуязычным. Для иностранцев значима одна деталь: моряки с дипломами, выданными третьими странами, смогут временно (до 3 месяцев) работать на судах под польским флагом.","key_changes":["Признание дипломов моряков из стран, не признанных Еврокомиссией, на срок до 3 месяцев","Работа на судне под польским флагом на основании подтверждения о подаче заявления (до 3 мес.)","Подтверждение выдаётся после проверки подлинности документа; оплата 30 PLN","Реестр судов ведётся на польском и английском, документы можно подавать по-английски","Регистрация судов, принадлежащих гражданам ЕС или субъектам с местом нахождения в ЕС","Ликвидация izby morskie, передача функций директорам urzędów morskich"],"affected_groups":["Иностранные моряки с дипломами третьих стран","Судовладельцы и армaторы из ЕС и третьих стран","Работники ликвидируемых izby morskie"],"practical_impact":"Моряк-иностранец с дипломом из страны, не признанной Еврокомиссией, сможет занять должность на судне под польским флагом до 3 месяцев, имея подтверждение о подаче заявления о признании диплома (сбор 30 PLN). Документы в судовой реестр можно будет подавать на английском языке.","effective_date":"Закон вступает в силу через 3 года после опубликования, за исключением перечисленных положений (в т.ч. касающихся признания дипломов моряков), которые вступают в силу через 14 дней после опубликования.","confidence":0.8,"rationale":"Основное содержание — морская администрация и реестр судов, но есть конкретное облегчение для иностранных моряков с зарубежными дипломами, что даёт косвенное трудовое влияние.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v4","input_chars":116209,"truncated":false,"text_source":"documents","created_at":"2026-09-11T09:52:37Z","input_tokens":57279,"output_tokens":701,"cache_read_input_tokens":0,"cache_creation_input_tokens":2280,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12402353/13157943/13157944/dokument738433.pdf","source_kind":"rcl","revision":1,"text_sha256":"09583e05eea8c9a5ca5919f5035e5112adba5fbbfd7041fef8b5296b32dd8f1e","law_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-11T09:51:44+00:00','2026-09-30T16:00:00+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12402353,"title":"Projekt ustawy o rejestracji statków pod polską banderą","applicant":"Minister Infrastruktury","wykaz_number":"UDER84","wykaz_url":"https://www.gov.pl/web/premier/projekt-ustawy-o-rejestracji-statkow-pod-polska-bandera","created":"2025-09-22","modified":"2026-09-11","departments":["gospodarka morska"],"keywords":["STATKI MORSKIE"],"status":"otwarty","term_label":"X","stages":[{"id":13157930,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":fal