INSERT INTO "bills" VALUES(10,'RCL/12409050','Projekt ustawy o ochronie rynku i konkurencyjnej gospodarki przed produktami i towarami powodującymi wylesianie oraz degradację lasów','2026-09-15T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','[]','{"term":10,"number":"RCL/12409050","title":"Projekt ustawy o ochronie rynku i konkurencyjnej gospodarki przed produktami i towarami powodującymi wylesianie oraz degradację lasów","description":"DREWNO; LASY; RYNEK WEWNĘTRZNY; środowisko. Numer i tytuł aktu prawnego Unii Europejskiej: rozporządzenie Parlamentu Europejskiego i Rady (UE) 2023/1115 z dnia 31 maja 2023 r. w sprawie udostępniania na rynku unijnym i wywozu z Unii niektórych towarów i produktów związanych z wylesianiem i degradacją lasów oraz uchylenia rozporządzenia (UE) nr 995/2010 (Dz. Urz. UE L 150 z 09.06.2023, str. 206, z późn. zm.)","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-04-09","document_date":"2026-09-03","change_date":"2026-09-15T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12409050","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2026-09-03","sub_committee":false,"children":[]}]','1e4941cfd709362de176e55fd617ef38f3a2b70bc06223efdfdbc4a3434fc931',NULL,0,'text prefilter: no keyword hits','2026-09-11T19:11:32+00:00','2026-09-15T15:46:30+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12409050,"title":"Projekt ustawy o ochronie rynku i konkurencyjnej gospodarki przed produktami i towarami powodującymi wylesianie oraz degradację lasów","applicant":"Minister Klimatu i Środowiska","wykaz_number":"UC101","wykaz