INSERT INTO "bills" VALUES(10,'RCL/12405351','Projekt ustawy o zmianie ustawy – Kodeks postępowania karnego oraz ustawy o dokumentach paszportowych','2026-09-30T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:straz_graniczna", "text:granica_panstwowa", "text:schengen", "text:obywatele_innych_panstw"]','{"term":10,"number":"RCL/12405351","title":"Projekt ustawy o zmianie ustawy – Kodeks postępowania karnego oraz ustawy o dokumentach paszportowych","description":"KARNE POSTĘPOWANIE; sprawiedliwość","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-12-17","document_date":"2026-09-14","change_date":"2026-09-30T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12405351","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]}]','7ef909314638054d4d047c4d8da4353e94eb84813b14ff444ff7ed5b0ae4aee2','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект меняет Kodeks postępowania karnego: вводится запрет покидать территорию ЕС и возможность самостоятельно изымать, аннулировать или отказывать в выдаче паспортного документа как мера пресечения. Соответственно правится ustawa o cudzoziemcach (закон об иностранцах) в части отказа в выдаче или аннулирования документов для иностранцев, к которым применена такая мера.","key_changes":["В art. 277 § 1 k.p.k. добавлен запрет покидать территорию ЕС, а не только Польшу","Изъятие, аннулирование или запрет выдачи паспортного документа можно применять самостоятельно","Art. 330 ust. 1 pkt 7 ustawy o cudzoziemcach увязан с любой мерой из art. 277 § 1 k.p.k.","Аннулирование паспорта судом/органом вместо административной процедуры; отметку в реестре делает wojewoda","Применение меры подлежит обжалованию и оценке суда по существу (zażalenie)"],"affected_groups":["иностранцы, являющиеся подозреваемыми или обвиняемыми в уголовных делах в Польше","лица, подающие заявление на польский проездной документ для иностранца","трансграничные работники и лица, проживающие в других странах ЕС"],"practical_impact":"Иностранцу, в отношении которого польский суд или прокуратура применили меру пресечения по art. 277 § 1 k.p.k., могут отказать в выдаче или аннулировать проездной документ; при этом появляется возможность обжаловать саму меру по существу, а не только формально.","effective_date":"Закон вступает в силу 1 октября 2027 года.","confidence":0.75,"rationale":"Поправка в ustawa o cudzoziemcach носит производный характер и касается лишь документов лиц в уголовном процессе, поэтому влияние косвенное.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":40983,"truncated":false,"text_source":"documents","created_at":"2026-09-14T20:21:42Z","input_tokens":20069,"output_tokens":1037,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405351/13176282/13176283/dokument797020.zip","source_kind":"rcl","revision":1,"text_sha256":"4baef1e7b23798db3f4d2ef6418e16e53e953e3da175c379c5986793a8f738ad","law_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-14T20:20:43+00:00','2026-09-30T18:32:35+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12405351,"title":"Projekt ustawy o zmianie ustawy – Kodeks postępowania karnego oraz ustawy o dokumentach paszportowych","applicant":"Minister Sprawiedliwości","wykaz_number":"UD319","wykaz_url":"https://www.gov.pl/web/premier/projekt-ustawy-o-zmianie-ustawy--kodeks-postepowania-karnego-oraz-ustawy-o-dokumentach-paszportowych","created":"2025-12-17","modified":"2026-09-30","departments":["sprawiedliwość"],"keywords":["KARNE POSTĘPOWANIE"],"status":"otwarty","term_label":"X","stages":[{"id":13176244,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13176245,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2026-01-16","folders":[{"id":13176246,"name":"Projekt","modified":"2025-12-17","documents":[{"id":754559,"name":"Projekt ustawy o zmianie ustawy - Kodeks postępowania karnego oraz ustawy o dokumentach paszportowych (UD319).docx","url":"https://legislacja.rcl.gov.pl/docs//2/12405351/13176245/13176246/dokument754559.docx","created":"2025-12-17","author":"Minister Sprawiedliwości"},{"id":754560,"name":"Ocena Skutków Regulacji (UD319).doc","url":"https://legislacja.rcl.gov.pl/docs//2/12405351/13176245/13176246/dokument754560.doc","created":"2025-12-17","author":"Minister Sprawiedliwości"},{"id":754577,"name":"Projekt ustawy o zmianie ustawy - Kodeks postępowania karnego oraz ustawy o dokumentach paszportowych (UD319).pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12405351/13176245/13176246/dokument754577.pdf","created":"2025-12-17","author":"Minister Sprawiedliwości"}]},{"id":13176247,"name":"Pisma kierujące projekt do uzgodnień","modified":"2025-12-17","documents":[{"id":754561,"name":"UD319 - Pismo - uzgodnienia .pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12405351/13176245/13176247/dokument754561.pdf","created":"2025-12-17","author":"Minister Sprawiedliwości"}]},{"id":13176248,"name":"Stanowiska zgłoszone w ramach uzgodnień","modified":"2026-01-16","documents":[{"id":757676,"name":"Ministerstwo Cyfryzacji.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12405351/13176245/13176248/dokument757676.pdf","created":"2026-01-08","author":"Minister Sprawiedliwości"},{"id":758078,"name":"Minister Spraw Zagranicznych.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12405351/13176245/13176248/dokument758078.pdf","created":"2026-01-13","author":"Minister Sprawiedliw