ad":false}],"consultation":{"letter_url":"https://legislacja.rcl.gov.pl/docs//2/12410308/13204102/13204104/dokument776520.pdf","letter_date":"2026-05-14","days":30,"deadline":"2026-06-13","email":"ustawapp@mz.gov.pl","positions":0,"response_published":false,"letters_read":["https://legislacja.rcl.gov.pl/docs//2/12410308/13204102/13204104/dokument776520.pdf"]},"consultation_attempts":0}',NULL,NULL,NULL,NULL,NULL,NULL,'{"stages":[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]}],"document":{"url":"https://legislacja.rcl.gov.pl/docs//2/12410308/13204102/13204103/dokument776516.pdf","kind":"rcl","extra_urls":[]},"analysis_sha256":"8a8275745cdd4a404f9a6c6ac286b1e133d43ea9b64dff88158303be22692a09","analysis_revision":1}',0,NULL,NULL,NULL,'full','telegram_thread');
INSERT INTO "bills" VALUES(10,'RCL/12411050','Projekt ustawy o zmianie ustawy o zawodach lekarza i lekarza dentysty oraz niektórych innych ustaw','2026-06-08T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:nostryfikacja", "text:obywatele_innych_panstw"]','{"term":10,"number":"RCL/12411050","title":"Projekt ustawy o zmianie ustawy o zawodach lekarza i lekarza dentysty oraz niektórych innych ustaw","description":"OCHRONA ZDROWIA; zdrowie","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-08","document_date":"2026-06-08","change_date":"2026-06-08T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12411050","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]}]','8865ddc6b63953e00692ab3917903794ade7286ef6d6f6be225eb588df760118','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект меняет правила допуска к профессии врача и стоматолога: экзамены LEK/LDEK, специализацию, стажировку. Для иностранцев ключевое — сворачивание «упрощённой процедуры» допуска к работе врачей с дипломом вне ЕС: заявления принимаются только до 31 декабря 2026 г. Также вводится обязательный номер PESEL для работы в системе SMK.","key_changes":["Упрощённая процедура допуска врачей из-за пределов ЕС: заявления только до 31.12.2026, позже — без рассмотрения","Отмена ст. 7 ust. 21: работа только по решению министра прекращается через 90 дней после вступления в силу","Обязательный PESEL для врачей и студентов-медиков при подаче заявлений в SMK","Врачи по упрощённой процедуре обязаны информировать окружную врачебную палату о месте работы","Вводится Specjalizacyjny Egzamin Weryfikacyjny (SEW) для признания специализации, полученной вне ЕС"],"affected_groups":["врачи и стоматологи с дипломом, полученным вне ЕС","иностранцы-студенты медицинских направлений в Польше","врачи, работающие по решению Министра здравоохранения (упрощённая процедура)","иностранные врачи, добивающиеся признания специализации"],"practical_impact":"Врачам с образованием вне ЕС останется только полная процедура признания квалификаций (нострификация или LEW/LDEW, экзамен по польскому, стажировка, LEK/LDEK); подать заявление по упрощённой процедуре можно лишь до 31.12.2026. Работающим лишь по решению министра нужно оформить право выполнения профессии в палате в течение 90 дней.","effective_date":"По общему правилу через 14 дней после опубликования; отдельные положения — с 1 января 2027 г., 1 мая 2027 г., 1 июля 2027 г., 1 октября 2027 г., 1 января 2029 г. и через 6 месяцев после опубликования.","confidence":0.82,"rationale":"Закон касается профессиональной квалификации, а не пребывания, но прямо ограничивает доступ к работе врачей с дипломами вне ЕС и вводит требование PESEL, что имеет ощутимый, но косвенный эффект для узкой группы иностранцев.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":355697,"truncated":false,"text_source":"documents","created_at":"2026-09-15T01:42:27Z","input_tokens":174528,"output_tokens":855,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12411050/13207858/13207859/dokument780025.pdf","source_kind":"rcl","revision":1,"text_sha256":"26084bbbfbf255796bb48745c9539866a2f1cc8e87acf18ec6b5ad1f51c80516","law_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-15T01:39:01+00:00','2026-09-30T16:00:30+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12411050,"title":"Projekt ustawy o zmianie ustawy o zawodach lekarza i lekarza dentysty oraz niektórych innych ustaw","applicant":"Minister Zdrowia","wykaz_number":"UD384","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2026-06-08","modified":"2026-06-08","departments":["zdrowie"],"keywords":["OCHRONA ZDROWIA"],"status":"otwarty","term_label":"X","stages":[{"id":13207851,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13207852,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2026-06-08","folders":[{"id":13207853,"name":"Projekt","modified":"2026-06-08","documents":[{"id":780014,"name":"Projekt","url":"https://legislacja.rcl.gov.pl/docs//2/12411050/13207852/13207853/dokument780014.pdf","created":"2026-06-08","author":"Minister Zdrowia"},{"id":780015,"name":"OSR","url":"https://legislacja.rcl.gov.pl/docs//2/12411050/13207852/13207853/dokument780015.docx","created":"2026-06-08","author":"Minister Zdrowia"},{"id":780016,"name":"Uzasadnienie","url":"https://legislacja.rcl.gov.pl/docs//2/12411050/13207852/13207853/dokument780016.docx","created":"2026-06-08","author":"Minister Zdrowia"},{"id":780017,"name":"Załącznik nr 1","url":"https://legislacja.rcl.gov.pl/docs//2/12411050/13207852/13207853/dokument780017.xlsx","created":"2026-06-08","author":"Minister Zdrowia"},{"id":780024,"name":"Załącznik nr 3","url":"https://legislacja.rcl.gov.pl/docs//2/12411050/13207852/13207853/dokument780024.xlsx","created":"2026-06-08","author":"Minister Zdrowia"},{"id":780035,"name":"Załącznik nr 2","url":"https://legislacja.rcl.gov.pl/docs//2/12411050/13207852/13207853/dokument780035.xlsx","created":"2026-06-08","author":"Minister Zdrowia"}]},{"id":13207854,"name":"Pisma kierujące projekt do uzgodnień","modified":"2026-06-08","documents":[{"id":780023,"name":"Pismo - uzgodnienia","url":"https://legislacja.rcl.gov.pl/docs//2/12411050/13207852/13207854/dokument780023.pdf","created":"2026-06-08","author":"Minister Zdrowia"}]},{"id":13207855,"name":"Stanowiska zgłoszone w ramach uzgodnień","documents":[]},{"id":13207856,"name":"Odniesienie się wnioskodawcy do uwag","documents":[]},{"id":13207857,"name":"Konferencja uzgodnieniowa","documents":[]}],"catalog_read":true},{"id":13207858,"number":3,"name":