":[],"catalog_read":false},{"id":13186926,"number":9,"name":"Stały Komitet Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13186931,"number":10,"name":"Komisja Prawnicza","state":"not_started","folders":[],"catalog_read":false},{"id":13186932,"number":11,"name":"Potwierdzenie projektu przez Stały Komitet Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13186937,"number":12,"name":"Rada Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13186943,"number":13,"name":"Notyfikacja","state":"not_started","folders":[],"catalog_read":false},{"id":13186944,"number":14,"name":"Skierowanie projektu ustawy do Sejmu","state":"not_started","folders":[],"catalog_read":false}],"consultation":{"letter_url":"https://legislacja.rcl.gov.pl/docs//2/12407104/13186895/13186897/dokument762717.docx","days":21,"deadline":"2026-03-05","email":"dep.prawny@mswia.gov.pl","positions":8,"response_published":false,"letters_read":["https://legislacja.rcl.gov.pl/docs//2/12407104/13186895/13186897/dokument762717.docx"]},"consultation_attempts":1}',NULL,NULL,NULL,NULL,NULL,NULL,'{"stages":[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]}],"document":{"url":"https://legislacja.rcl.gov.pl/docs//2/12407104/13186901/13186902/dokument762718.docx","kind":"rcl","extra_urls":[]},"analysis_sha256":"7b89c260f4635e34771bd7610e3618f513720de56beb3219d2e772f42d7fa3c3","analysis_revision":1}',0,NULL,NULL,NULL,'full','relevant_analysis');
INSERT INTO "bills" VALUES(10,'RCL/12409801','Projekt ustawy o zmianie ustawy – Prawo o ruchu drogowym oraz niektórych innych ustaw','2026-09-28T00:00:00+00:00',NULL,NULL,'analyzed','[]','{"term":10,"number":"RCL/12409801","title":"Projekt ustawy o zmianie ustawy – Prawo o ruchu drogowym oraz niektórych innych ustaw","description":"RUCH DROGOWY; informatyzacja","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-04-30","document_date":"2026-04-30","change_date":"2026-09-28T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12409801","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]}]','6672da2ae796ddf843b3f99a2c18d5ea37b2046ef5e88a58c6c3ceac1f2db272','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект цифровизирует регистрацию автомобилей и выдачу водительских удостоверений: заявления через интернет, электронный dowód rejestracyjny, электронный договор купли-продажи авто. Для иностранцев ключевое — обмен/получение прав и карты квалификации водителя будет требовать номер PESEL.","key_changes":["Получение prawo jazdy требует наличия номера PESEL (новый пункт в art. 11)","Обмен иностранного национального удостоверения на польское — только при наличии PESEL (art. 14)","Karta kwalifikacji kierowcy выдаётся лицам с иностранными правами при наличии PESEL","Ликвидация PKK и профиля профессионального водителя — идентификация по PESEL в CEK","Электронный договор продажи авто доступен только физлицам с PESEL и юрлицам с местом в Польше"],"affected_groups":["иностранцы, обменивающие иностранные права на польские","иностранцы-водители профессионального транспорта","владельцы автомобилей без номера PESEL","кандидаты на получение польских прав"],"practical_impact":"Без номера PESEL нельзя будет получить или обменять польское водительское удостоверение, карту квалификации водителя и пройти профессиональную квалификацию, а также воспользоваться онлайн-договором продажи авто; одновременно большинство процедур (заявление, электронный техпаспорт, доставка документов почтой) станут доступны онлайн и в любом старостве.","effective_date":"Закон вступает в силу через 14 дней после опубликования, за исключением многочисленных положений с датами: 29 ноября 2027 г., 1 января 2028 г., 5 июня 2028 г., 13 ноября 2028 г., 15 января 2029 г., 2 июля 2029 г. и 14 января 2030 г.","confidence":0.72,"rationale":"Затрагивает водительские документы и обмен иностранных прав, вводя требование PESEL — сфера повседневных административных прав, а не легализации пребывания.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":145563,"truncated":false,"text_source":"documents","created_at":"2026-09-15T11:32:14Z","input_tokens":72745,"output_tokens":955,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12409801/13201107/13201108/dokument774418.docx","source_kind":"rcl","revision":1,"text_sha256":"8668caa4c9a0dea46d0b1a2825f4a257f87d74752d5630ede8bf5d25a339759e","law_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-15T01:40:30+00:00','2026-09-30T15:59:36+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12409801,"title":"Projekt ustawy o zmianie ustawy – Prawo o ruchu drogowym oraz niektórych innych ustaw","applicant":"Minister Cyfryzacji","wykaz_number":"UDER87","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2026-04-30","modified":"2026-09-28","departments":["informatyzacja"],"keywords":["RUCH DROGOWY"],"status":"otwarty","term_label":"X","stages":[{"id":13201094,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":1