INSERT INTO "bills" VALUES(10,'RCL/12413302','Projekt ustawy o zmianie ustawy - Prawo o ruchu drogowym oraz niektórych innych ustaw','2026-08-07T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','["text:legalizacja", "text:straz_graniczna"]','{"term":10,"number":"RCL/12413302","title":"Projekt ustawy o zmianie ustawy - Prawo o ruchu drogowym oraz niektórych innych ustaw","description":"TRANSPORT DROGOWY; transport","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-07","document_date":"2026-08-07","change_date":"2026-08-07T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12413302","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]}]','a9e9ffeae7b7a41bf760fceab4589ad04159510f4073c69b63956a31cb871f6b',NULL,0,'text prefilter: weak patterns only (legalizacja×1, straz_graniczna×2)','2026-09-15T01:40:47+00:00','2026-09-15T01:40:47+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12413302,"title":"Projekt ustawy o zmianie ustawy - Prawo o ruchu drogowym oraz niektórych innych ustaw","applicant":"Minister Infrastruktury","wykaz_number":"UD263","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2026-08-07","modified":"2026-08-07","departments":["transport"],"keywords":["TRANSPORT DROGOWY"],"status":"otwarty","term_label":"X","stages":[{"id":13219887,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13219888,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2026-08-07","folders":[],"catalog_read":false},{"id":13219894,"number":3,"name":"Konsultacje publiczne","state":"active","modified":"2026-08-07","folders":[],"catalog_read":true},{"id":13219900,"number":4,"name":"Opiniowanie","state":"not_started","folders":[],"catalog_read":fals