INSERT INTO "bills" VALUES(10,'3040','Poselski projekt ustawy o zmianie ustawy o środkach ochrony roślin','2026-09-15T09:18:06+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3040","title":"Poselski projekt ustawy o zmianie ustawy o środkach ochrony roślin","description":"projekt dotyczy czasowego ograniczenia katalogu sankcji stosowanych w przypadku nieprowadzenia lub nieprzechowywania dokumentacji (ewidencji) dotyczącej zastosowanych środków ochrony roślin w formacie elektronicznym, do środków oddziaływania wychowawczego","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-12","document_date":"2026-08-12","change_date":"2026-09-15T09:18:06Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-12","print_number":"3040","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"RRW","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-12","print_number":"3040","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"RRW","sub_committee":false,"committee_name":"Komisja Rolnictwa i Rozwoju Wsi","children":[]}]}]','1214e71683c4213cbd8b368bfd2761b2982e93f81260d23b2b89949c26dc1bfc','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект касается временного смягчения санкций для сельхозпроизводителей за непредоставление электронной документации по средствам защиты растений и никак не затрагивает иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.95,"rationale":"Законопроект касается временного смягчения санкций для сельхозпроизводителей за непредоставление электронной документации по средствам защиты растений и никак не затрагивает иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":0,"truncated":true,"text_source":"excerpts","created_at":"2026-09-15T10:13:50Z","input_tokens":13854,"output_tokens":92,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-15T10:11:52+00:00','2026-09-30T16:00:59+00:00','{"term":10,"number":"RPW/27520/2026","title":"Poselski projekt ustawy o zmianie ustawy o środkach ochrony roślin","description":"czasowego ograniczenia katalogu sankcji stosowanych w przypadku nieprowadzenia lub nieprzechowywania dokumentacji (ewidencji) dotyczącej zastosowanych środków ochrony roślin w formacie elektronicznym, do środków oddziaływania wychowawczego","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-08-12","print_number":"3040","eu_related":false,"public_consultation":true,"consultation_start":"2026-08-13","consultation_end":"2026-09-12","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,'{"representative":"Katarzyna Królak","representative_club":"KO","clubs":[["KO",38]],"signatories":38,"unresolved":0}','[{"kind": "committee", "ref": "RRW/181/2026-10-07+10:00+sala im. Bronisława Geremka (nr 14, bud. G)", "date": "2026-10-07", "end_date": null, "start_time": "10:00:00", "committee_code": "RRW", "committee_name": "Komisja Rolnictwa i Rozwoju Wsi", "sitting_number": 181, "room": "sala im. Bronisława Geremka (nr 14, bud. G)", "text": "Pierwsze czytanie poselskiego projektu ustawy o zmianie ustawy o środkach ochrony roślin (druk nr 3040).", "video_url": "http