INSERT INTO "bills" VALUES(10,'3089','Poselski projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz niektórych innych ustaw','2026-09-15T09:29:36+00:00',NULL,0,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"3089","title":"Poselski projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz niektórych innych ustaw","description":"projekt dotyczy wprowadzenia czasowych obniżek (od dnia 3 lipca do dnia 30 września 2026 r.) stawek podatku od towarów i usług (z 3% do 8%) na niektóre produkty energetyczne takie jak benzyny silnikowe, oleje napędowe, biokomponenty oraz gazy przeznaczone do napędu silników spalinowych skroplone oraz określenia tymczasowych (mniejszych) stawek akcyzy na wymienione produkty energetyczne, które będą obowiązujące od dnia 3 lipca do dnia 30  września 2026 r., a także wyłączenia ww. produktów z opodatkowania podatkiem od sprzedaży detalicznej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-02","document_date":"2026-07-02","change_date":"2026-09-15T09:29:36Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-09-15T10:11:54+00:00','2026-09-16T10:05:08+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3094','Rządowy projekt ustawy o zmianie ustawy o ubezpieczeniach gwarantowanych przez Skarb Państwa','2026-09-15T09:54:54+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3094","title":"Rządowy projekt ustawy o zmianie ustawy o ubezpieczeniach gwarantowanych przez Skarb Państwa","description":"projekt dotyczy rozszerzenia możliwości działania Korporacji Ubezpieczeń Kredytów Eksportowych (KUKE). Zmiany mają wzmocnić pozycję krajowych firm na rynkach zagranicznych, zwiększyć bezpieczeństwo Polski oraz wesprzeć transformację energetyczną i klimatyczną. KUKE będzie mogła m.in. ubezpieczać wybrane inwestycje związane z bezpieczeństwem i obronnością państwa, szerzej wspierać inwestycje energetyczne, przejmować część ryzyka w sytuacjach nadzwyczajnych oraz inwestować w zagraniczne instytucje o podobnym profilu działalności.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-14","document_date":"2026-09-14","change_date":"2026-09-15T09:54:54Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-137-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-137-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-14","print_number":"3094","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"GOR","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"FPB","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-14","print_number":"3094","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"Read