INSERT INTO "bills" VALUES(10,'3088','Rządowy projekt ustawy o zmianie ustawy o postępowaniu w sprawach dotyczących pomocy publicznej oraz niektórych innych ustaw','2026-09-15T08:56:11+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3088","title":"Rządowy projekt ustawy o zmianie ustawy o postępowaniu w sprawach dotyczących pomocy publicznej oraz niektórych innych ustaw","description":"projekt dotyczy zniesienia obowiązku przedstawiania zaświadczeń lub oświadczeń dotyczących udzielonej pomocy de minimis i pomocy de minimis w rolnictwie lub rybołówstwie przez podmioty ubiegające się o taką pomoc, jaki obecnie ciąży na nich zgodnie z art. 37 ust. 1 i 2 ustawy z dnia 30 kwietnia 2004 r. o postępowaniu w sprawach dotyczących pomocy publicznej. Nowe przepisy realizują działania deregulacyjne Rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-10","document_date":"2026-09-10","change_date":"2026-09-15T08:56:11Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-141-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-141-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-10","print_number":"3088","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"GOR","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"DER","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-10","print_number":"3088","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"GOR","sub_committee":false,"committee_name":"Komisja Gospodarki i Rozwoju","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"DER","sub_committee":false,"committee_name":"Komisja do Spraw Deregulacji","children":[]}]}]','b42102f2f8490db991b8e2e73c9d889e4644e00205065cd66e681cda1ac17a4c','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект касается процедур публичной помощи (пособия de minimis), реестров и отчетности для субъектов, получающих такую помощь, а упоминания границы и PESEL являются техническими и не затрагивают права или обязанности иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Проект касается процедур публичной помощи (пособия de minimis), реестров и отчетности для субъектов, получающих такую помощь, а упоминания границы и PESEL являются техническими и не затрагивают права или обязанности иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":10856,"truncated":true,"text_source":"excerpts","created_at":"2026-09-15T15:47:51Z","input_tokens":6727,"output_tokens":112,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-15T10:13:53+00:00','2026-09-30T16:01:00+00:00','{"term":10,"number":"RPW/30305/2026","title":"Rządowy projekt ustawy o zmianie ustawy o postępowaniu w sprawach dotyczących pomocy publicznej oraz niektórych innych ustaw","description":"zniesienia obowiązku przedstawiania zaświadczeń lub oświadczeń dotyczących udzielonej pomocy de minimis i pomocy de minimis w rolnictwie lub rybołówstwie przez podmioty ubiegające się o taką pomoc, jaki obecnie ciąży na nich zgodnie z art. 37 ust. 1 i 2 ustawy z dnia 30 kwietnia 2004 r. o postępowaniu w sprawach dotyczących pomocy publicznej. Nowe przepisy realizują działania deregulacyjne Rządu.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-10","print_number":null,"eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RCL/12405302',NULL,NULL,NULL,'[{"kind": "committee", "ref": "DER/134/2026-10-08+13:00+sala nr 312, bud. U", "date": "2026-10-08", "end_date": null, "start_time": "13:00:00", "committee_code": "DER", "committee_name": "Komisja do Spraw Deregulacji", "sitting_number": 134, "room": "sala nr 312, bud. U", "text": "Pierwsze czytanie rządowego projektu ustawy o zmianie ustawy o postępowaniu w sprawach dotyczących pomocy publicznej oraz niektórych innych ustaw (druk nr 3088)", "video_url": "https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=74E8EEEB1E53E304C1258E82004786F4", "condition": null, "closed": false, "apply_email": null, "apply_by": null}]',NULL,NULL,'UDER101',NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-10","print_number":"3088","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"GOR","sub_committee":false,"committee_name":"Komisja Gospodarki i Rozwoju","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"DER","sub_committee":false,"committee_name":"Komisja do Spraw Deregulacji","children":[]}]}],"passed":false,"analysis_revision":1,"seen_supplements":[]}',1,NULL,NULL,NULL,'metadata','not_relevant');
