INSERT INTO "bills" VALUES(10,'2110','Rządowy projekt ustawy o statusie osoby najbliższej w związku i umowie o wspólnym pożyciu','2026-09-18T11:07:33+00:00','2026-09-17',0,'analyzed','["text:migracja", "text:azyl", "text:obywatelstwo"]','{"term":10,"number":"2110","title":"Rządowy projekt ustawy o statusie osoby najbliższej w związku i umowie o wspólnym pożyciu","description":"projekt dotyczy uregulowania kwestii związków nieformalnych; osoby żyjące w takich związkach będą mogły zawrzeć przed notariuszem umowę cywilnoprawną, która następnie zostanie zarejestrowana w urzędzie stanu cywilnego i dzięki której zyskają możliwość kształtowania wzajemnych praw i obowiązków w sferze majątkowej, rodzinnej i osobistej m. in. będą mogły razem rozliczać PIT, zyskają dostęp do informacji i dokumentacji medycznej partnera oraz uprawnienia dotyczące ubezpieczenia zdrowotnego, renty rodzinnej, prawa do pochówku czy zasiłku opiekuńczego. Będą także uprawnione do dziedziczenia testamentowego. Nowe przepisy zwiększą też ochronę osób tworzących niesformalizowane związki, niezależnie od płci.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-12-30","document_date":"2025-12-30","change_date":"2026-09-18T11:07:33Z","closure_date":"2026-09-17","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-242-25","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-242-25","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-12-30","print_number":"2110","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2025-12-31","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-12-31","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"20