INSERT INTO "bills" VALUES(10,'RPW/31193/2026','Rządowy projekt ustawy o zmianie ustawy o finansowym wsparciu niektórych przedsięwzięć mieszkaniowych oraz niektórych innych ustaw','2026-09-16T00:00:00+00:00',NULL,NULL,'linked','[]','{"term":10,"number":"RPW/31193/2026","title":"Rządowy projekt ustawy o zmianie ustawy o finansowym wsparciu niektórych przedsięwzięć mieszkaniowych oraz niektórych innych ustaw","description":"zmian w dwóch programach wsparcia mieszkalnictwa: programie budownictwa socjalnego i komunalnego (BSK) oraz programie TERMO, wspierającym termomodernizację, remonty i instalację odnawialnych źródeł energii w budynkach wielorodzinnych. Zmiany pozwolą wykorzystać wolne środki z programu Stop Smog na zwiększenie wsparcia dla wspólnot i spółdzielni mieszkaniowych, gmin oraz innych właścicieli i zarządców budynków, w ramach programu TERMO.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-16","document_date":"2026-09-16","change_date":"2026-09-16T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"government"}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-16T19:35:40+00:00','2026-09-17T10:08:11+00:00','{"term":10,"number":"RPW/31193/2026","title":"Rządowy projekt ustawy o zmianie ustawy o finansowym wsparciu niektórych przedsięwzięć mieszkaniowych oraz niektórych innych ustaw","description":"zmian w dwóch programach wsparcia mieszkalnictwa: programie budownictwa socjalnego i komunalnego (BSK) oraz programie TERMO, wspierającym termomodernizację, remonty i instalację odnawialnych źródeł energii w budynkach wielorodzinnych. Zmiany pozwolą wykorzystać wolne środki z programu Stop Smog na zwiększenie wsparcia dla wspólnot i spółdzielni mieszkaniowych, gmin oraz innych właścicieli i zarządców budynków, w ramach programu TERMO.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-16","print_number":"3121","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','3121',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
