INSERT INTO "bills" VALUES(10,'3126','Poselski projekt ustawy o zawodzie dietetyka i samorządzie zawodowym dietetyków','2026-09-17T17:03:51+00:00',NULL,0,'analyzed','["text:obywatelstwo", "text:obywatele_innych_panstw", "text:uznawanie_kwalifikacji"]','{"term":10,"number":"3126","title":"Poselski projekt ustawy o zawodzie dietetyka i samorządzie zawodowym dietetyków","description":"projekt dotyczy usankcjonowania zawodu dietetyka jako samodzielnego zawodu medycznego; określenia zasad: wykonywania zawodu dietetyka, uzyskiwania prawa wykonywania tego zawodu, kształcenia zawodowego dietetyków, ponoszenia przez dietetyków odpowiedzialności zawodowej. Projekt reguluje także organizację i zadania samorządu zawodowego dietetyków oraz prawa i obowiązki jego członków.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-16","document_date":"2026-07-16","change_date":"2026-09-17T17:03:51Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-16","print_number":"3126","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-17","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-17","committee_code":"ZDR","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-16","print_number":"3126","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-17","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-17","committee_code":"ZDR","sub_committee":false,"committee_name":"Komisja Zdrowia","children":[]}]}]','699b468bc18707e627ce3af8f9b01e493663a1c02ac8299f76f3d83058876162','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект регулирует профессию диетолога: вводит право выполнения профессии, реестр и профессиональное самоуправление (Krajowa Izba Dietetyków). Для иностранцев как таковых он ничего не меняет, кроме общих правил признания квалификаций из ЕС/ЕЭЗ/Швейцарии.","key_changes":["Введение обязательного права выполнения профессии диетолога и реестра","Признание дипломов из ЕС/ЕЭЗ/Швейцарии и стран вне ЕС по общим правилам","Требование знания польского языка на уровне B2 для лиц без польского гражданства","Возможность временного и окказионального оказания услуг диетологами из ЕС/ЕЭЗ","При заявлении требуется документ, подтверждающий право пребывания в Польше"],"affected_groups":["иностранцы с дипломом диетолога","специалисты из стран ЕС/ЕЭЗ/Швейцарии","диетологи с дипломами из третьих стран"],"practical_impact":"Иностранец, желающий работать диетологом в Польше, должен будет подтвердить квалификацию, знание польского на уровне B2, приложить документ о праве пребывания и получить право выполнения профессии; сам статус пребывания законопроект не меняет.","effective_date":"1 января 2027 г., за исключением ст. 23–28 и ст. 10 п. 1, 2 и 4 — через 36 месяцев со дня опубликования","confidence":0.8,"rationale":"Законопроект касается регулирования профессии в целом; иностранцы упоминаются лишь в контексте признания квалификаций и языкового требования, что не меняет условий их пребывания или трудоустройства как таковых.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":290493,"truncated":false,"text_source":"pdf","created_at":"2026-09-17T19:46:28Z","input_tokens":144600,"output_tokens":622,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3126/3126.pdf","source_kind":"print","revision":1,"text_sha256":"b0e16463e3e5b28d5492452462d95d52417194eab2452557d16b2542e3396dec","source_checked_at":"2026-09-17T19:46:28Z"}',0,NULL,'2026-09-17T19:45:19+00:00','2026-09-30T16:01:01+00:00','{"term":10,"number":"RPW/24748/2026","title":"Poselski projekt ustawy o zawodzie dietetyka i samorządzie zawodowym dietetyków","description":"usankcjonowania zawodu dietetyka jako samodzielnego zawodu medycznego; określenia zasad: wykonywania zawodu dietetyka, uzyskiwania prawa wykonywania tego zawodu, kształcenia zawodowego dietetyków, ponoszenia przez dietetyków odpowiedzialności zawodowej. Projekt reguluje także organizację i zadania samorządu zawodowego dietetyków oraz prawa i obowiązki jego członków.","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-07-16","print_number":"3126","eu_related":false,"public_consultation":true,"consultation_start":"2026-07-17","consultation_end":"2026-08-16","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,'{"representative":"Wioleta Tomczak","representative_club":"Polska2050","clubs":[["Polska2050",15],["Centrum",1],["niez.",1]],"signatories":17,"unresolved":0}',NULL,NULL,NULL,NULL,NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-16","print_number":"3126","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-17","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-17","committee_code":"ZDR","sub_committee":false,"committee_name":"Komisja Zdrowia","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3126/3126.pdf","kind":"print","extra_urls":[]},"analysis_sha256":"b0e16463e3e5b28d5492452462d95d52417194eab2452557d16b2542e3396dec","analysis_revision":1,"seen_supplements":[]}',0,NULL,NULL,NULL,'metadata','not_relevant');
INSERT INTO "bills" VALUES(10,'RPW/29629/2026','Obywatelski projekt ustawy o zmianie ustawy - Prawo łowieckie oraz niektórych innych ustaw','2026-09-17T00:00:00+00:00',NULL,NULL,'analyzed','[]','{"term":10,"number":"RPW/29629/2026","title":"Obywatelski projekt ustawy o zmianie ustawy - Prawo łowieckie oraz niektórych innych ustaw","description":"zmiany modelu prawnej regulacji łowiectwa poprzez zwiększenie bezpieczeństwa społecznego w związku z prowadzonymi polowaniami; zwiększenie udziału społeczeństwa w decydowaniu o kształcie i sposobie wykonywania gospodarki łowieckiej; ograniczenia wpływu myśliwych na kształt gospodarki łowieckiej i wprowadzenia kontroli organów ochrony przyrody","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-17","document_date":"2026-09-17","change_date":"2026-09-17T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"citizens"}',NULL,NULL,'{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект касается изменения Закона об охоте (Prawo łowieckie) — регулирует охоту, планы охотничьих хозяйств и охрану природы, не затрагивая статус, пребывание или права иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Проект касается изменения Закона об охоте (Prawo łowieckie) — регулирует охоту, планы охотничьих хозяйств и охрану природы, не затрагивая статус, пребывание или права иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":0,"truncated":true,"text_source":"excerpts","created_at":"2026-09-17T19:46:27Z","input_tokens":13923,"output_tokens":105,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-17T19:45:19+00:00','2026-09-18T09:54:12+00:00','{"term":10,"number":"RPW/29629/2026","title":"Obywatelski projekt ustawy o zmianie ustawy - Prawo łowieckie oraz niektórych innych ustaw","description":"zmiany modelu prawnej regulacji łowiectwa poprzez zwiększenie bezpieczeństwa społecznego w związku z prowadzonymi polowaniami; zwiększenie udziału społeczeństwa w decydowaniu o kształcie i sposobie wykonywania gospodarki łowieckiej; ograniczenia wpływu myśliwych na kształt gospodarki łowieckiej i wprowadzenia kontroli organów ochrony przyrody","applicant":"citizens","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-17","print_number":null,"eu_related":false,"public_consultation":true,"consultation_start":"2026-09-18","consultation_end":"2026-10-18","consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'metadata','not_relevant');
INSERT INTO "bills" VALUES(10,'RPW/31346/2026','Poselski projekt ustawy o zmianie ustawy - Prawo ochrony środowiska','2026-09-17T00:00:00+00:00',NULL,NULL,'analyzed','["text:migracja", "text:uznawanie_kwalifikacji"]','{"term":10,"number":"RPW/31346/2026","title":"Poselski projekt ustawy o zmianie ustawy - Prawo ochrony środowiska","description":"wyłączenia dzwonów kościelnch spod restrykcyjnych limitów hałasu, przypisując im status podobny do infrastruktury transportowej (np. linii tramwajowych czy kolejowych), dla których tradycyjne pomiary hałasu przemysłowego nie mają zastosowania w ten sam sposób","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-17","document_date":"2026-09-17","change_date":"2026-09-17T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"deputies"}',NULL,NULL,'{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект меняет Prawo ochrony środowiska (закон об охране окружающей среды): звук колоколов и звукоусиливающих систем религиозного культа выводится из-под норм шума и решений о допустимом уровне шума. Для иностранцев никаких правовых последствий нет.","key_changes":["Исключение систем нагłaśniających религиозного культа из решений о допустимом уровне шума (art. 115a ust. 2)","Запрет на использование звукоусиливающих устройств в общественных местах не применяется к практике религиозного культа (art. 156 ust. 2)"],"affected_groups":["приходы и религиозные общины","жители домов рядом с храмами"],"practical_impact":"Ничего не меняется в вопросах пребывания, работы или социальных прав иностранцев; изменение касается только шума от религиозных объектов.","effective_date":"Через 14 дней после публикации.","confidence":0.95,"rationale":"Тема — шум от церковных колоколов; иностранцы упомянуты лишь риторически в обосновании, правовых последствий для них нет.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":18591,"truncated":false,"text_source":"pdf","created_at":"2026-09-17T19:46:37Z","input_tokens":9214,"output_tokens":408,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-31346-2026/$file/10-RPW-31346-2026.pdf","source_kind":"print","revision":1,"text_sha256":"cd7a7425e388f5525a3ab2097f03939e9d5e158eb9092f2cdc2bf31741cfead3","source_checked_at":"2026-09-17T19:46:37Z"}',0,NULL,'2026-09-17T19:45:19+00:00','2026-09-18T09:54:12+00:00','{"term":10,"number":"RPW/31346/2026","title":"Poselski projekt ustawy o zmianie ustawy - Prawo ochrony środowiska","description":"wyłączenia dzwonów kościelnych spod restrykcyjnych limitów hałasu, przypisując im status podobny do infrastruktury transportowej (np. linii tramwajowych czy kolejowych), dla których tradycyjne pomiary hałasu przemysłowego nie mają zastosowania w ten sam sposób","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-17","print_number":null,"eu_related":false,"public_consultation":true,"consultation_start":"2026-09-18","consultation_end":"2026-10-18","consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'metadata','not_relevant');
