INSERT INTO "bills" VALUES(10,'2746','Poselski projekt ustawy o zmianie ustawy - Kodeks postępowania karnego','2026-09-18T12:54:59+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:legalizacja", "text:uznawanie_kwalifikacji"]','{"term":10,"number":"2746","title":"Poselski projekt ustawy o zmianie ustawy - Kodeks postępowania karnego","description":"projekt dotyczy m. in. regulacji określających tymczasowe aresztowanie","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-05-22","document_date":"2026-05-22","change_date":"2026-09-18T12:54:59Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-05-22","print_number":"2746","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-07-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-05-22","print_number":"2746","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-07-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"committee_name":"Komisja Nadzwyczajna do spraw zmian w kodyfikacjach","children":[]}]}]','b30173880eefce0e51168012e04caf8966afd02e4c2bae518a35ff97ef690768','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект вносит изменения в Уголовно-процессуальный кодекс, касающиеся временного задержания, доступа к защитникам и допустимости доказательств для всех участников уголовного процесса, без специального регулирования для иностранцев (упоминание помощи иностранцам касается лишь знания языков дежурными адвокатами).","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Проект вносит изменения в Уголовно-процессуальный кодекс, касающиеся временного задержания, доступа к защитникам и допустимости доказательств для всех участников уголовного процесса, без специального регулирования для иностранцев (упоминание помощи иностранцам касается лишь знания языков дежурными адвокатами).","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":14593,"truncated":true,"text_source":"excerpts","created_at":"2026-09-18T19:07:40Z","input_tokens":8592,"output_tokens":143,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-18T19:03:51+00:00','2026-09-30T16:00:54+00:00','{"term":10,"number":"RPW/17946/2026","title":"Poselski projekt ustawy o zmianie ustawy - Kodeks postępowania karnego","description":"m. in. regulacji określających tymczasowe aresztowanie","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-05-22","print_number":"2746","eu_related":false,"public_consultation":true,"consultation_start":"2026-05-26","consultation_end":"2026-06-25","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,'{"representa