INSERT INTO "bills" VALUES(10,'2802','Poselski projekt ustawy o zmianie ustawy - Kodeks postępowania karnego oraz niektórych innych ustaw','2026-09-18T12:53:55+00:00',NULL,0,'analyzed','["text:migracja", "text:obywatele_ukrainy", "text:straz_graniczna", "text:obywatele_innych_panstw", "text:uznawanie_kwalifikacji"]','{"term":10,"number":"2802","title":"Poselski projekt ustawy o zmianie ustawy - Kodeks postępowania karnego oraz niektórych innych ustaw","description":"projekt dotyczy potrzeby dostosowania obowiązujących regulacji prawa karnego procesowego do standardów konstytucyjnych i międzynarodowych mi.n. przez zmiany w sposobie przesłuchiwania podejrzanego, który nie ukończył 18 lat (m.in. obowiązkowy udział obrońcy); zapewnienie prawa do pomocy tłumacza języka migowego oskarżonemu, który jest głuchy lub niemy również na potrzeby jego udziału w czynnościach postępowania (np. rozprawie lub posiedzeniach) oraz kontaktów z obrońcą","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-01","document_date":"2026-06-01","change_date":"2026-09-18T12:53:55Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-01","print_number":"2802","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-07-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-01","print_number":"2802","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-07-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"committee_name":"Komisja Nadzwyczajna do spraw zmian w kodyfikacjach","children":[]}]}]','b4e7ff32208e5a6c4cfb0cc9ac4967af11e3f76abd0fe0a5a064b2a440172a37','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект меняет Уголовно-процессуальный кодекс и связанные законы: доступ к защитнику, права задержанных, порядок временного ареста, право на переводчика для тех, кто не владеет польским. Это общие процессуальные гарантии, а не нормы о пребывании или работе иностранцев.","key_changes":["Расширено право на бесплатного переводчика для обвиняемого, не владеющего польским языком","Право требовать перевода документов, важных для защиты, и жаловаться на качество перевода","Постоянное место жительства в другой стране ЕС приравнено к проживанию в Польше при оценке риска побега","Обязательное участие защитника при допросе подозреваемого младше 18 лет","Доступ задержанного и защитника к материалам, обосновывающим задержание и арест"],"affected_groups":["иностранцы, оказавшиеся подозреваемыми или задержанными в Польше","лица, не владеющие польским языком, в уголовном процессе","граждане других стран ЕС, проживающие за пределами Польши"],"practical_impact":"Иностранец, попавший в уголовный процесс в Польше, получит более широкий доступ к переводчику и защитнику, а проживание в другой стране ЕС больше не будет само по себе основанием считать его склонным к побегу. На легализацию пребывания или работу это не влияет.","effective_date":"Закон вступает в силу по истечении 6 месяцев со дня опубликования.","confidence":0.85,"rationale":"Это реформа уголовного процесса; положения о переводчике и о месте жительства в ЕС касаются иностранцев лишь косвенно и не меняют их статуса пребывания или занятости.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":449323,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:08:02Z","input_tokens":227761,"output_tokens":614,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2802/2802.pdf","source_kind":"print","revision":1,"text_sha256":"1495a1bc2a8b6f5353e9f6670c0d7bc3dcdaf5c4e511d900e692aabe1aeccccb","source_checked_at":"2026-09-18T19:08:02Z"}',0,NULL,'2026-09-18T19:03:51+00:00','2026-09-30T16:00:54+00:00','{"term":10,"number":"RPW/18910/2026","title":"Poselski projekt ustawy o zmianie ustawy - Kodeks postępowania karnego oraz niektórych innych ustaw","description":"potrzeby dostosowania obowiązujących regulacji prawa karnego procesowego do standardów konstytucyjnych i międzynarodowych mi.n. przez zmiany w sposobie przesłuchiwania podejrzanego, który nie ukończył 18 lat (m.in. obowiązkowy udział obrońcy); zapewnienie prawa do pomocy tłumacza języka migowego oskarżonemu, który jest głuchy lub niemy również na potrzeby jego udziału w czynnościach postępowania (np. rozprawie lub posiedzeniach) oraz kontaktów z obrońcą","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-06-01","print_number":"2802","eu_related":false,"public_consultation":true,"consultation_start":"2026-06-03","consultation_end":"2026-07-03","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,'{"representative":"Maciej Tomczykiewicz","representative_club":"KO","clubs":[["KO",25]],"signatories":25,"unresolved":0}',NULL,NULL,NULL,NULL,NULL,'["2802-001", "2802-002", "2802-003", "2802-004"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-01","print_number":"2802","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-07-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"committee_name":"Komisja Nadzwyczajna do spraw zmian w kodyfikacjach","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/2802/2802.pdf","kind":"print","extra_urls":[]},"analysis_sha256":"1495a1bc2a8b6f5353e9f6670c0d7bc3dcdaf5c4e511d900e692aabe1aeccccb","analysis_revision":1,"seen_supplements":["2802-001","2802-002","2802-003","2802-004"]}',0,NULL,NULL,NULL,'metadata','not_relevant');
INSERT INTO "bills" VALUES(10,'2997','Rządowy projekt ustawy o zmianie ustawy - Kodeks postępowania karnego','2026-09-18T14:08:30+00:00',NULL,0,'analyzed','["text:obywatelstwo", "text:straz_graniczna", "text:granica_panstwowa", "text:schengen"]','{"term":10,"number":"2997","title":"Rządowy projekt ustawy o zmianie ustawy - Kodeks postępowania karnego","description":"projekt dotyczy wprowadzenia prostszych i bardziej przejrzystych pouczeń dla świadków, pokrzywdzonych i oskarżonych oraz rozszerzenia informacji o przysługujących im prawach","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-30","document_date":"2026-07-30","change_date":"2026-09-18T14:08:30Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-118-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-118-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-30","print_number":"2997","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-08-11","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-11","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-30","print_number":"2997","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-08-11","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-11","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"committee_name":"Komisja Nadzwyczajna do spraw zmian w kodyfikacjach","children":[]}]}]','7b30f4f08b7880bbebe6f4cc31d03916e1bc0e92f76ce9286c7b99b1393aedab','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект меняет правила информирования участников уголовного процесса (обвиняемых, потерпевших, свидетелей) об их правах. Образцы таких уведомлений будут утверждены министром и опубликованы на сайте Ministerstwo Sprawiedliwości вместе с переводами на иностранные языки, чаще всего используемые в уголовных делах.","key_changes":["Единые образцы письменных pouczeń для обвиняемых, потерпевших, свидетелей на судебной стадии","Публикация образцов на сайте MS с переводом на самые частые иностранные языки","Расширение информирования задержанного о праве и сроке требовать компенсацию за необоснованное задержание","Аналогичное информирование при tymczasowe aresztowanie и при необоснованном осуждении","Свидетелю сообщат о праве на помощь представителя и о возможности допроса консулом"],"affected_groups":["иностранцы — участники уголовного процесса в Польше","задержанные и арестованные иностранцы","свидетели и потерпевшие, не владеющие польским языком"],"practical_impact":"Иностранец, участвующий в уголовном деле, получит стандартное письменное разъяснение своих прав, доступное в переводе на распространённые иностранные языки, включая информацию о праве на переводчика, адвоката и компенсацию за необоснованное задержание.","effective_date":"Закон вступает в силу 1 января 2027 года; новые нормы применяются также к делам, начатым ранее.","confidence":0.82,"rationale":"Норма касается уголовной процедуры в целом, но прямо предусматривает переводы уведомлений и права неговорящих по-польски, что даёт косвенное значение для иностранцев.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":159462,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:07:27Z","input_tokens":82049,"output_tokens":628,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2997/2997.pdf","source_kind":"print","revision":1,"text_sha256":"4de1a98333983b34fcca93efc8641bdeaa8323d09fbbe52b80ffa5e365197b1b","source_checked_at":"2026-09-18T19:07:27Z"}',0,NULL,'2026-09-18T19:03:52+00:00','2026-09-30T16:00:56+00:00','{"term":10,"number":"RPW/26576/2026","title":"Rządowy projekt ustawy o zmianie ustawy - Kodeks postępowania karnego","description":"wprowadzenia prostszych i bardziej przejrzystych pouczeń dla świadków, pokrzywdzonych i oskarżonych oraz rozszerzenia informacji o przysługujących im prawach","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-07-30","print_number":"2997","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,'[{"kind": "committee", "ref": "NKK/68/2026-10-06+17:00+sala im. Tadeusza Mazowieckiego (nr 23, bud. G)", "date": "2026-10-06", "end_date": null, "start_time": "17:00:00", "committee_code": "NKK", "committee_name": "Komisja Nadzwyczajna do spraw zmian w kodyfikacjach", "sitting_number": 68, "room": "sala im. Tadeusza Mazowieckiego (nr 23, bud. G)", "text": "Rozpatrzenie rządowego projektu ustawy o zmianie ustawy - Kodeks postępowania karnego (druk nr 2997).", "video_url": "https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=839E2FDA7A84AB6BC1258E820031E222", "condition": null, "closed": false, "apply_email": null, "apply_by": null}]',NULL,NULL,NULL,NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-30","print_number":"2997","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-08-11","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-11","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"committee_name":"Komisja Nadzwyczajna do spraw zmian w kodyfikacjach","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/2997/2997.pdf","kind":"print","extra_urls":[]},"analysis_sha256":"4de1a98333983b34fcca93efc8641bdeaa8323d09fbbe52b80ffa5e365197b1b","analysis_revision":1,"seen_supplements":[]}',0,NULL,NULL,NULL,'full','relevant_analysis');
INSERT INTO "bills" VALUES(10,'3004','Rządowy projekt ustawy o zmianie ustawy o Krajowym Rejestrze Sądowym oraz niektórych innych ustaw','2026-09-18T14:26:32+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3004","title":"Rządowy projekt ustawy o zmianie ustawy o Krajowym Rejestrze Sądowym oraz niektórych innych ustaw","description":"projekt dotyczy: zmniejszenia obciążeń administracyjnych związanych z funkcjonowaniem Krajowego Rejestru Sądowego dzięki automatyzacji i informatyzacji procesów. Stworzenie specjalnych kont i automatyczna aktualizacja danych z rejestru PESEL ograniczy liczbę dokumentów papierowych i czynności kancelaryjnych. Uproszczone zostaną także zasady postępowania dotyczące tzw. \"martwych podmiotów\" oraz składania sprawozdań finansowych. Zmiany usprawnią też pracę sądów rejestrowych. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-06","document_date":"2026-08-06","change_date":"2026-09-18T14:26:32Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-125-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-125-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-06","print_number":"3004","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-08-11","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-11","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"SPC","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-06","print_number":"3004","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-08-11","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-11","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"SPC","sub_committee":false,"committee_name":"Komisja Sprawiedliwości i Praw Człowieka","children":[]}]}]','9986be76a31f468990b2b11496355851f84cde10eeebc4f1e41fd8ef88b42fec','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект меняет работу KRS (Krajowy Rejestr Sądowy, судебный реестр компаний и организаций): вся переписка с судом идёт через электронную систему и счёт организации, упрощается ликвидация «мёртвых» фирм. Иностранцев касается лишь уточнённое заявление о статусе cudzoziemca у покупателя долей и акций.","key_changes":["В заявке о покупке долей/акций указывается, является ли приобретатель cudzoziemcem по ustawa z 1920 r.","Если приобретатель — иностранец, заявляется, владеет ли компания недвижимостью в Польше","Для адреса регистрации фирмы нужно правовое основание на помещение, документ прилагается к заявке","Заявления и письма в реестровый суд — только через ИТ-систему и счёт организации","Пометка в KRS о несдаче финансовой отчётности; через год — роспуск фирмы без ликвидации"],"affected_groups":["иностранцы — покупатели и учредители долей и акций польских компаний","иностранцы — владельцы и члены правления компаний, зарегистрированных в KRS"],"practical_impact":"При покупке долей или акций польской компании иностранцем в заявке в KRS нужно указать его статус и наличие у компании недвижимости в Польше. Для всех фирм, включая принадлежащие иностранцам, обязательны электронная переписка с судом и документ о праве на помещение по адресу регистрации.","effective_date":"Закон вступает в силу 1 октября 2027 г., за исключением положений о пометке о несдаче финансовой отчётности и связанных норм, которые вступают в силу 1 октября 2028 г.","confidence":0.8,"rationale":"Проект касается корпоративного реестра в целом, а иностранцы затронуты лишь уточнением декларации по закону о приобретении недвижимости иностранцами, поэтому влияние маргинальное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":188666,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3004/3004.pdf","source_kind":"print","revision":2,"text_sha256":"6de93675eb8a39b3ebdbc22f6ce78a830901c2feeeaca7cc1938b70d36843812","source_checked_at":"2026-09-28T15:56:32Z"}',0,NULL,'2026-09-18T19:03:52+00:00','2026-09-30T16:00:56+00:00','{"term":10,"number":"RPW/27047/2026","title":"Rządowy projekt ustawy o zmianie ustawy o Krajowym Rejestrze Sądowym oraz niektórych innych ustaw","description":"zmniejszenia obciążeń administracyjnych związanych z funkcjonowaniem Krajowego Rejestru Sądowego dzięki automatyzacji i informatyzacji procesów. Stworzenie specjalnych kont i automatyczna aktualizacja danych z rejestru PESEL ograniczy liczbę dokumentów papierowych i czynności kancelaryjnych. Uproszczone zostaną także zasady postępowania dotyczące tzw. \"martwych podmiotów\" oraz składania sprawozdań finansowych. Zmiany usprawnią też pracę sądów rejestrowych. Nowe przepisy realizują działania deregulacyjne rządu.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-08-06","print_number":"3004","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RCL/12402301',NULL,NULL,NULL,NULL,NULL,NULL,'UDER49',NULL,'["3004-001"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-06","print_number":"3004","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-08-11","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-11","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"SPC","sub_committee":false,"committee_name":"Komisja Sprawiedliwości i Praw Człowieka","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3004/3004.pdf","kind":"print","extra_urls":[]},"analysis_sha256":"6de93675eb8a39b3ebdbc22f6ce78a830901c2feeeaca7cc1938b70d36843812","analysis_revision":2,"seen_supplements":["3004-001"]}',2,NULL,NULL,NULL,'full','relevant_analysis');
INSERT INTO "bills" VALUES(10,'RPW/31562/2026','Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o zmianie ustawy o zapasach ropy naftowej, produktów naftowych i gazu ziemnego oraz zasadach postępowania w sytuacjach zagrożenia bezpieczeństwa paliwowego państwa i zakłóceń na rynku naftowym oraz niektórych innych ustaw','2026-09-18T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"RPW/31562/2026","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o zmianie ustawy o zapasach ropy naftowej, produktów naftowych i gazu ziemnego oraz zasadach postępowania w sytuacjach zagrożenia bezpieczeństwa paliwowego państwa i zakłóceń na rynku naftowym oraz niektórych innych ustaw","description":"wprowadzenia nadzwyczajnego, czasowego mechanizmu interwencyjnego służącego ograniczeniu negatywnych skutków wzrostu cen paliw ciekłych dla gospodarstw domowych, przedsiębiorców oraz całej gospodarki","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-18","document_date":"2026-09-18","change_date":"2026-09-18T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"president"}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-09-18T19:03:54+00:00','2026-09-19T13:56:40+00:00','{"term":10,"number":"RPW/31562/2026","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o zmianie ustawy o zapasach ropy naftowej, produktów naftowych i gazu ziemnego oraz zasadach postępowania w sytuacjach zagrożenia bezpieczeństwa paliwowego państwa i zakłóceń na rynku naftowym oraz niektórych innych ustaw","description":"wprowadzenia nadzwyczajnego, czasowego mechanizmu interwencyjnego służącego ograniczeniu negatywnych skutków wzrostu cen paliw ciekłych dla gospodarstw domowych, przedsiębiorców oraz całej gospodarki","applicant":"president","status":"ACTIVE","sub