INSERT INTO "bills" VALUES(10,'RPW/31837/2026','Poselski projekt ustawy o zmianie ustawy o finansach publicznych oraz ustawy - Prawo oświatowe','2026-09-22T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"RPW/31837/2026","title":"Poselski projekt ustawy o zmianie ustawy o finansach publicznych oraz ustawy - Prawo oświatowe","description":"rozszerzenia katalogu źródeł dochodów wydzielonego rachunku, obejmując nim odpłatne udostępnianie mienia (kuchnie i stołówki, sale lekcyjne i gimnastyczne, pracownie, aule, sale koncertowe i baletowe, boiska, sprzęt sportowy i muzyczny), odpłatne świadczenie usług przy jego wykorzystaniu, sprzedaż rzeczy wytworzonych oraz odsetki. Wprowadzenia warunków dopuszczalności tj. zakazu ograniczania zadań statutowych oraz wymogu ustalania wynagrodzenia na poziomie nie niższym niż suma kosztów. Projekt ustawy uchyla obowiązek odprowadzania środków na koniec roku budżetowego, utrzymuje limit wydatków do wysokości środków zgromadzonych na rachunku, nakłada obowiązek wyodrębnionej ewidencji księgowej oraz rocznej informacji dla organu wykonawczego. Projekt ustawy przesądza dopuszczalność odpłatnego przygotowywania i wydawania posiłków na rzecz osób spoza szkoły, po zapłacie pełnego kosztu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-22","document_date":"2026-09-22","change_date":"2026-09-22T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"deputies"}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-09-22T15:58:29+00:00','2026-09-23T00:53:04+00:00','{"term":10,"number":"RPW/31837/2026","title":"Poselski projekt ustawy o zmianie ustawy o finansach publicznych oraz ustawy - Prawo oświatowe","description":"rozszerzenia katalogu źródeł dochodów wydzielonego rachunku, obejmując nim odpłatne udostępnianie mienia (kuchnie i stołówki, sale lekcyjne i gimnastyczne, pracownie, aule, sale koncertowe i baletowe, boiska, sprzęt sportowy i muzyczny), odpłatne świadczenie usług przy jego wykorzystaniu, sprzedaż rzeczy wytworzonych oraz odsetki. Wprowadzenia warunków dopuszczalności tj. zakazu ograniczania zadań statutowych oraz wymogu ustalania wynagrodzenia na poziomie nie niższym niż suma kosztów. Projekt ustawy uchyla obowiązek odprowadzania środków na koniec roku budżetowego, utrzymuje limit wydatków do wysokości środków zgromadzonych na rachunku, nakłada obowiązek wyodrębnionej ewidencji księgowej oraz rocznej informacji dla organu wykonawczego. Projekt ustawy przesądza dopuszczalność odpłatnego przygotowywania i wydawania posiłków na rzecz osób spoza szkoły, po zapłacie pełnego kosztu.","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-22","print_number":null,"eu_related":false,"public_consultation":true,"consultation_start":"2026-09-23","consultation_end":"2026-10-23","consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'RCL/12404454','Projekt ustawy o stażach','2026-09-23T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:obywatele_ukrainy", "text:zatrudnianie_cudzoziemcow", "text:pracownicy_delegowani", "text:obywatele_innych_panstw", "text:uznawanie_kwalifikacji"]','{"term":10,"number":"RCL/12404454","title":"Projekt ustawy o stażach","description":"PRACA; praca","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-11-21","document_date":"2025-11-21","change_date":"2026-09-23T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12404454","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]}]','3ddc21501cb2426ff4b0f2d7cde01257deb8f9e8f1496f79f0e5572241e15bde','{"analysis":{"relevant":true,"score":4,"category":"employment","summary":"Проект вводит новый закон о стажировках (staże) вместо ustawa o praktykach absolwenckich (закон о выпускных практиках): стажировки становятся обязательно оплачиваемыми, с письменным договором и страхованием. Закон распространяется на граждан ЕС/ЕЭЗ и на иностранцев, перечисленных в ст. 3 ч. 1 ustawa o warunkach dopuszczalności powierzania pracy cudzoziemcom (закон о допустимости поручения работы иностранцам).","key_changes":["Отмена ustawa o praktykach absolwenckich; бесплатные выпускные практики больше невозможны","Круг участников: поляки, граждане ЕС/ЕЭЗ и иностранцы из ст. 3 ч. 1 закона о поручении работы иностранцам","Денежная выплата стажёру: не менее 35% среднего заработка и не выше среднего заработка","Договор о стажировке — письменный, максимум 6 месяцев, срок предупреждения 7 или 14 дней","Стажёр подлежит соцстрахованию как исполнитель zlecenie и медстрахованию NFZ через организатора"],"affected_groups":["граждане ЕС/ЕЭЗ в Польше","иностранцы со свободным доступом к рынку труда по ст. 3 ч. 1 закона о поручении работы иностранцам","граждане Украины, охваченные специальным законом (в части ст. 26)","молодёжь и выпускники, включая несовершеннолетних стажёров"],"practical_impact":"Иностранцы, имеющие доступ к польскому рынку труда, смогут проходить стажировку только по письменному договору и за оплату не ниже 35% среднего заработка, с социальным и медицинским страхованием; бесплатные практики исчезнут. Для иностранцев без такого доступа стажировки по этому закону недоступны.","effective_date":"Закон вступает в силу по истечении 6 месяцев со дня опубликования.","confidence":0.8,"rationale":"Закон прямо определяет круг иностранцев, которым разрешены стажировки, и регулирует условия их оплачиваемого труда, что относится к сфере занятости.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v9","input_chars":96624,"truncated":false,"text_source":"documents","created_at":"2026-09-22T16:00:01Z","input_tokens":49715,"output_tokens":1125,"cache_read_input_tokens":0,"cache_creation_input_tokens":2652,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171166/13171167/dokument749803.pdf","source_kind":"rcl","revision":1,"text_sha256":"96b2a36ffb972cede864176f0bd61797487a2189acea3e6a32c4a293080369d1","law_sha256":null,"source_checked_at":"2026-09-22T16:00:01Z"}',0,NULL,'2026-09-22T15:59:03+00:00','2026-09-30T15:59:25+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12404454,"title":"Projekt ustawy o stażach","applicant":"Minister Rodziny, Pracy i Polityki Społecznej","wykaz_number":"UD307","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2025-11-21","modified":"2026-09-23","departments":["praca"],"keywords":["PRACA"],"status":"otwarty","term_label":"X","stages":[{"id":13171153,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13171154,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2026-09-23","folders":[{"id":13171155,"name":"Projekt","modified":"2026-04-21","documents":[{"id":749794,"name":"Projekt ustawy o stażach 17.11.2025","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171155/dokument749794.pdf","created":"2025-11-21","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":749795,"name":"Uzasadnienie do projektu ustawy o stażach 17.11.2025","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171155/dokument749795.pdf","created":"2025-11-21","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":749796,"name":"OSR do projektu ustawy o stażach 17.11.2025","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171155/dokument749796.pdf","created":"2025-11-21","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":749797,"name":"Tabela uwag do projektu ustawy o stażach","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171155/dokument749797.pdf","created":"2025-11-21","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":772878,"name":"Projekt ustawy o stażach 20.04.2026 r.","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171155/dokument772878.docx","created":"2026-04-21","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":772879,"name":"Uzasadnienie do ustawy o stażach 20.04.2026 r.","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171155/dokument772879.docx","created":"2026-04-21","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":772880,"name":"OSR do projektu ustawy o stażach 20.04.2026 r.","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171155/dokument772880.doc","created":"2026-04-21","author":"Minister Rodziny, Pracy i Polityki Społecznej"}]},{"id":13171156,"name":"Pisma kierujące projekt do uzgodnień","modified":"2026-04-21","documents":[{"id":749798,"name":"Pismo przekazujące projekt ustawy o stażach do uzgodnień","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171156/dokument749798.pdf","created":"2025-11-21","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":772881,"name":"Pismo przekazujące nowy tekst ustawy o stażach do uzgodnień międzyresortowych.","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171156/dokument772881.pdf","created":"2026-04-21","author":"Minister Rodziny, Pracy i Polityki Społecznej"}]},{"id":13171157,"name":"Stanowiska zgłoszone w ramach uzgodnień","modified":"2026-09-23","documents":[{"id":773488,"name":"1 Minister Cyfryzacji pismo - wersja 17.11.2025.","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171157/dokument773488.pdf","created":"2026-04-24","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":773489,"name":"1 Minister Cyfryzacji zał. uwagi - wersja 17.11.2025.","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171157/dokument773489.pdf","created":"2026-04-24","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":773491,"name":"2 Minister Spraw Zagranicznych pismo - wersja 17.11.2025.","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171157/dokument773491.pdf","created":"2026-04-24","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":773492,"name":"2 Minister Spraw Zagranicznych zał. uwagi - wersja 17.11.2025.","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171157/dokument773492.pdf","created":"2026-04-24","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":773493,"name":"3 Minster Rolnictwa i Rozwoju Wsi pismo - wersja 17.11.2025.","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171157/dokument773493.pdf","created":"2026-04-24","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":773494,"name":"3 Minster Rolnictwa i Rozwoju Wsi zał. uwagi - wersja 17.11.2025.","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171157/dokument7734