INSERT INTO "bills" VALUES(10,'3134','Rządowy projekt ustawy o zmianie ustawy o systemie monitorowania i kontrolowania jakości paliw','2026-09-28T11:38:59+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3134","title":"Rządowy projekt ustawy o zmianie ustawy o systemie monitorowania i kontrolowania jakości paliw","description":"projekt dotyczy wprowadzenia jednolitych wymagań jakościowych dla biopaliw stałych oraz objęcie ich systemem kontroli jakości paliw. Dzięki temu do sprzedaży nie będzie mogła trafiać biomasa niespełniająca określonych wymagań, co ma ograniczyć spalanie paliw złej jakości i przyczynić się do poprawy jakości powietrza. Projekt umożliwia objęcie normami jakości zarówno biopaliwa pochodzenia drzewnego, jak i rolniczego. Da to podstawy do rozwoju rynku biopaliw pochodzenia rolniczego, w tym agropeletu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-17","document_date":"2026-09-17","change_date":"2026-09-28T11:38:59Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-17","print_number":"3134","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ESK","sub_committee":false,"committee_name":"Komisja do Spraw Energii, Klimatu i Aktywów Państwowych","children":[]}]}]','dce3f3e3587d05b9f2f587f7732fe0504520e9b444fc923aa7a0f45be3864740',NULL,0,'text prefilter: no keyword hits','2026-09-28T11:40:07+00:00','2026-09-29T17:20:37+00:00','{"term":10,"number":"RPW/31391/2026","title":"Rządowy projekt ustawy o zmianie ustawy o systemie monitorowania i kontrolowania jakości paliw","description":"wprowadzenia jednolitych wymagań jakościowych dla biopaliw stałych oraz objęcie ich systemem kontroli jakości paliw. Dzięki temu do sprzedaży nie będzie mogła trafiać biomasa niespełniająca określonych wymagań, co ma ograniczyć spalanie paliw złej jakości i przyczynić się do poprawy jakości powietrza. Projekt umożliwia objęcie normami jakości zarówno biopaliwa pochodzenia drzewnego, jak i rolniczego. Da to podstawy do rozwoju rynku biopaliw pochodzenia rolniczego, w tym agropeletu.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-17","print_number":"3134","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RPW/31391/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-17","print_number":"3134","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ESK","sub_committee":false,"committee_name":"Komisja do Spraw Energii, Klimatu i Aktywów Państwowych","children":[]}]}],"passed":false,"analysis_revision":0}',0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'RCL/12408900','projekt ustawy o biegłych sądowych oraz instytucjach opiniujących','2026-09-28T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:obcokrajowcy", "text:obywatelstwo"]','{"term":10,"number":"RCL/12408900","title":"projekt ustawy o biegłych sądowych oraz instytucjach opiniujących","description":"BIEGLI SĄDOWI; sprawiedliwość","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-04-03","document_date":"2026-04-03","change_date":"2026-09-28T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12408900","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","date":"2026-09-28","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","date":"2026-08-19","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","date":"2026-09-28","sub_committee":false,"children":[]}]','304840ef571d0fff429c55dd0d4741019149e7b2d6b6c21509f51fbf8d9f829d','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект вводит новую систему судебных экспертов (biegli sądowi): сертификация через Państwowa Komisja Certyfikacyjna и единый реестр. Иностранцев касается требование гражданства: экспертом может стать только гражданин Польши, ЕС, ЕАСТ/ЕЭЗ или Швейцарии, владеющий польским языком.","key_changes":["Судебным экспертом может быть только гражданин Польши, ЕС, ЕАСТ/ЕЭЗ или Швейцарии","Обязательно достаточное владение польским языком, возраст от 25 лет, 5 лет практики","Иностранные документы подаются с заверенным переводом на польский язык","Без PESEL в заявлении указывается паспорт или документ иностранца по ustawa o cudzoziemcach","Сертификат на 5 лет выдаёт Państwowa Komisja Certyfikacyjna, эксперт вносится в общенациональный реестр"],"affected_groups":["граждане третьих стран, желающие работать судебными экспертами в Польше","граждане ЕС/ЕАСТ/Швейцарии — кандидаты в судебные эксперты","действующие судебные эксперты"],"practical_impact":"Граждане стран вне ЕС/ЕАСТ/Швейцарии (например, Украины или Беларуси) не смогут получить сертификат судебного эксперта, даже при наличии квалификации. Граждане ЕС должны подтвердить знание польского языка и предоставить заверенные переводы документов.","effective_date":"Закон вступает в силу 1 января 2027 г., за исключением ст. 55–63 (реестр) — с 1 апреля 2027 г. и ст. 88–90 — с 1 октября 2026 г.","confidence":0.8,"rationale":"Общий закон о профессии судебного эксперта с конкретным аспектом для иностранцев — требованием гражданства Польши/ЕС/ЕАСТ/Швейцарии, поэтому косвенное влияние.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":305859,"truncated":false,"text_source":"documents","created_at":"2026-09-28T11:48:49Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408900/13196264/13196265/dokument770060.docm","source_kind":"rcl","revision":1,"text_sha256":"1356ca7516fc78b98838020f119582553ec383c6571febcb797990440caef1be","law_sha256":null,"source_checked_at":"2026-09-28T11:48:49Z"}',0,NULL,'2026-09-28T11:40:37+00:00','2026-09-30T16:00:28+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12408900,"title":"projekt ustawy o biegłych sądowych oraz instytucjach opiniujących","applicant":"Minister Sprawiedliwości","wykaz_number":"UD265","wykaz_url":"https://legislacja.rcl.gov.pl/","created":"2026-04-03","modified":"2026-09-28","departments":["sprawiedliwość"],"keywords":["BIEGLI SĄDOWI"],"status":"otwarty","term_label":"X","stages":[{"id":13196251,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13196252,"number":2,"name":"Uzgodnienia","state":"reached","started":"2026-09-28","ended":"2026-09-28","modified":"2026-09-28","folders":[{"id":13196253,"nam