INSERT INTO "bills" VALUES(10,'3135','Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług','2026-09-28T11:40:27+00:00',NULL,0,'skipped_text_prefilter','["text:pobyt_kwalifikowany"]','{"term":10,"number":"3135","title":"Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług","description":"projekt dotyczy zlikwidowania preferencyjnego opodatkowania napojów będących bezalkoholowymi odpowiednikami napojów alkoholowych, jak również napojów energetyzujących; podwyższenia stawki VAT do 23% na określone napoje bezalkoholowe, które zawierają w swoim składzie co najmniej 20% soku owocowego, warzywnego lub owocowo-warzywnego","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-24","document_date":"2026-09-23","change_date":"2026-09-28T11:40:27Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (pobyt_kwalifikowany×1)','2026-09-28T11:48:52+00:00','2026-09-29T17:20:37+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3137','Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych, ustawy o podatku dochodowym od osób prawnych oraz ustawy o zryczałtowanym podatku dochodowym od niektórych przychodów osiąganych przez osoby fizyczne','2026-09-28T11:41:27+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3137","title":"Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych, ustawy o podatku dochodowym od osób prawnych oraz ustawy o zryczałtowanym podatku dochodowym od niektórych przychodów osiąganych przez osoby fizyczne","description":"projekt dotyczy ujednolicenia m.in. zasad opodatkowania świadczeń na zaspokojenie potrzeb rodziny, rozszerzenia zwolnienia podatkowego dla organizacji pozarządowych oraz doprecyzowania zasad obliczania daniny solidarnościowej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-24","document_date":"2026-09-24","change_date":"2026-09-28T11:41:27Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-158-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-158-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-24","print_number":"3137","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"Sejm","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-24","print_number":"3137","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"Sejm","sub_committee":false,"children":[]}]}]','e362eaa25d14d323d749302e7409b76925aa7fa434b198febbb6871cfa1cce8c','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект касается изменений в налогах на доходы физических и юридических лиц (PIT/CIT) в Польше и не затрагивает специфически иностранцев, их пребывание, работу или статус.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Законопроект касается изменений в налогах на доходы физических и юридических лиц (PIT/CIT) в Польше и не затрагивает специфически иностранцев, их пребывание, работу или статус.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":6004,"truncated":true,"text_source":"excerpts","created_at":"2026-09-15T15:47:21Z","input_tokens":4238,"output_tokens":98,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-28T11:48:52+00:00','2026-09-30T16:01:01+00:00',NULL,'RCL/12402157',NULL,NULL,NULL,NULL,NULL,NULL,'UD116',NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-24","print_number":"3137","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"Sejm","sub_committee":false,"children":[]}]}],"passed":false,"analysis_revision":1,"seen_supplements":[]}',1,NULL,NULL,NULL,'metadata','not_relevant');
INSERT INTO "bills" VALUES(10,'3138','Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób prawnych oraz ustawy o portach i przystaniach morskich','2026-09-28T11:39:47+00:00',NULL,0,'skipped_text_prefilter','["text:straz_graniczna"]','{"term":10,"number":"3138","title":"Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób prawnych oraz ustawy o portach i przystaniach morskich","description":"projekt dotyczy dostosowania zasad korzystania ze zwolnienia podatkowego przez podmioty zarządzające portami morskimi do wymogów unijnego prawa pomocy publicznej. Zwolnieniem zostaną objęte m.in. wydatki na: budowę, wymianę i modernizację infrastruktury portowej oraz infrastruktury zapewniającej dostęp do portów od strony morza i lądu, pogłębianie, planowanie tych inwestycji, zadania o charakterze niegospodarczym, m.in. związane z bezpieczeństwem ruchu morskiego, ochroną przeciwpożarową i ochroną portów.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-09-28T11:39:47Z","passed":false,"urgency_status":"NORMAL","eu_related":true,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: weak patterns only (straz_graniczna×2)','2026-09-28T11:48:53+00:00','2026-09-29T17:20:37+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3136','Rządowy projekt ustawy o zmianie ustawy o podatku akcyzowym oraz ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych','2026-09-28T11:56:52+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3136","title":"Rządowy projekt ustawy o zmianie ustawy o podatku akcyzowym oraz ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych","description":"projekt dotyczy podwyżki stawek akcyzy w 2027 r. na alkohol etylowy, piwo, wino, napoje fermentowane i wyroby pośrednie; przeznaczenia dodatkowych wpływów z akcyzy na zwiększenie dotacji podmiotowej dla Narodowego Funduszu Zdrowia, a tym samym na finansowanie świadczeń opieki zdrowotnej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-24","document_date":"2026-09-24","change_date":"2026-09-28T11:56:52Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-28T15:32:09+00:00','2026-09-29T17:20:37+00:00','{"term":10,"number":"RPW/32222/2026","title":"Rządowy projekt ustawy o zmianie ustawy o podatku akcyzowym oraz ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych","description":"podwyżki stawek akcyzy w 2027 r. na alkohol etylowy, piwo, wino, napoje fermentowane i wyroby pośrednie; przeznaczenia dodatkowych wpływów z akcyzy na zwiększenie dotacji podmiotowej dla Narodowego Funduszu Zdrowia, a tym samym na finansowanie świadczeń opieki zdrowotnej","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-24","print_number":"3136","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3139','Rządowy projekt ustawy o ratyfikacji Wzmocnionej umowy o partnerstwie i współpracy między Unią Europejską i jej państwami członkowskimi, z jednej strony, a Republiką Kirgiską, z drugiej strony, sporządzonej w Brukseli dnia 25 czerwca 2024 r.','2026-09-28T12:09:47+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:obcokrajowcy", "text:migracja", "text:azyl", "text:uchodzcy", "text:repatriacja", "text:obywatelstwo", "text:wizy", "text:pobyt_kwalifikowany", "text:straz_graniczna", "text:ochrona_miedzynarodowa", "text:nostryfikacja", "text:status_uchodzcy", "text:obywatele_innych_panstw", "text:uznawanie_kwalifikacji", "text:nierezydenci"]','{"term":10,"number":"3139","title":"Rządowy projekt ustawy o ratyfikacji Wzmocnionej umowy o partnerstwie i współpracy między Unią Europejską i jej państwami członkowskimi, z jednej strony, a Republiką Kirgiską, z drugiej strony, sporządzonej w Brukseli dnia 25 czerwca 2024 r.","description":"projekt dotyczy wprowadzenia lepszej ochrony praw własności intelektualnej poprzez ustanowienie 167 oznaczeń geograficznych produktów pochodzących z Unii Europejskiej, które będą chronione w Republice Kirgiskiej bezpośrednio na podstawie Umowy. W przypadku Rzeczypospolitej Polskiej, postanowienia te dotyczą napojów spirytusowych, a w szczególności Wódki ziołowej z Niziny Północnopodlaskiej aromatyzowanej ekstraktem z trawy żubrowej i Polskiej Wódki. Umowa stworzy również ramy prawne do bardziej zaawansowanej współpracy w dziedzinie wzajemnej pomocy prawnej i ekstradycji w oparciu o odpowiednie umowy międzynarodowe","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-09-28T12:09:47Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3139","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SZA","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SUE","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3139","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SZA","sub_committee":false,"committee_name":"Komisja Spraw Zagranicznych","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SUE","sub_committee":false,"committee_name":"Komisja do Spraw Unii Europejskiej","children":[]}]}]','45aa5992559dc337c7843fb97ae77aa42d762aac9de4ccc9a4ae742545fcd4d7','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект даёт согласие на ратификацию нового соглашения о партнёрстве и сотрудничестве ЕС с Кыргызстаном, заменяющего договор 1995 года. Соглашение касается торговли, инвестиций, защиты географических указаний, а также сотрудничества в сфере миграции, реадмиссии и правовой помощи. Прямо права граждан Кыргызстана в Польше не меняет.","key_changes":["Кыргызстан обязуется принимать обратно своих граждан, не имеющих права находиться в странах ЕС, без дальнейших формальностей","Допускается использование европейского проездного документа для возврата нелегально пребывающих лиц","Стороны могут договориться о соглашении ЕС–Кыргызстан об упрощении визового режима и о реадмиссии","Внутрикорпоративные переводы: руководители и специалисты — до 3 лет, стажёры — до 1 года, при соблюдении национальных правил","Граждане Кыргызстана могут получать консульскую защиту в странах ЕС без его представительства"],"affected_groups":["граждане Кыргызстана в Польше и ЕС","граждане Кыргызстана без законных оснований для пребывания","сотрудники кыргызских компаний, переводимые внутри корпорации","инвесторы из Кыргызстана"],"practical_impact":"Для граждан Кыргызстана в Польше правила получения виз, разрешений на пребывание и работу не меняются: соглашение прямо указывает, что национальное законодательство о въезде, пребывании и работе продолжает действовать. Возможно упрощение возврата лиц без законного статуса в Кыргызстан.","effective_date":"Закон вступает в силу через 14 дней со дня опубликования; само соглашение — в первый день второго месяца после взаимного уведомления сторон о завершении внутренних процедур.","confidence":0.8,"rationale":"Ратификация двустороннего соглашения, затрагивающего миграцию и реадмиссию лишь на уровне рамочного сотрудничества без изменения национальных правил пребывания, соответствует косвенному влиянию (оценка 2).","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":1268621,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3139/3139.pdf","source_kind":"print","revision":1,"text_sha256":"f95398d40b3ad92b97a13150325f6533e52d48eed4dc3c935c8b00a65d342a7f","source_checked_at":"2026-09-28T15:56:31Z"}',0,NULL,'2026-09-28T15:32:09+00:00','2026-09-30T16:01:01+00:00','{"term":10,"number":"RPW/32110/2026","title":"Rządowy projekt ustawy o ratyfikacji Wzmocnionej umowy o partnerstwie i współpracy między Unią Europejską i jej państwami członkowskimi, z jednej strony, a Republiką Kirgiską, z drugiej strony, sporządzonej w Brukseli dnia 25 czerwca 2024 r.","description":"wprowadzenia lepszej ochrony praw własności intelektualnej poprzez ustanowienie 167 oznaczeń geograficznych produktów pochodzących z Unii Europejskiej, które będą chronione w Republice Kirgiskiej bezpośrednio na podstawie Umowy. W przypadku Rzeczypospolitej Polskiej, postanowienia te dotyczą napojów spirytusowych, a w szczególności Wódki ziołowej z Niziny Północnopodlaskiej aromatyzowanej ekstraktem z trawy żubrowej i Polskiej Wódki. Umowa stworzy również ramy prawne do bardziej zaawansowanej współpracy w dziedzinie wzajemnej pomocy prawnej i ekstradycji w oparciu o odpowiednie umowy międzynarodowe","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-23","print_number":"3139","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3139","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SZA","sub_committee":false,"committee_name":"Komisja Spraw Zagranicznych","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SUE","sub_committee":false,"committee_name":"Komisja do Spraw Unii Europejskiej","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3139/3139.pdf","kind":"print","extra_urls":[]},"analysis_sha256":"f95398d40b3ad92b97a13150325f6533e52d48eed4dc3c935c8b00a65d342a7f","analysis_revision":1,"seen_supplements":[]}',1,NULL,NULL,NULL,'full','relevant_analysis');
INSERT INTO "bills" VALUES(10,'3140','Rządowy projekt ustawy o ratyfikacji Wzmocnionej umowy o partnerstwie i współpracy między Unią Europejską i jej państwami członkowskimi, z jednej strony, a Republiką Uzbekistanu, z drugiej strony, sporządzonej w Brukseli dnia 24 października 2025 r','2026-09-28T11:52:32+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:obcokrajowcy", "text:migracja", "text:azyl", "text:uchodzcy", "text:repatriacja", "text:obywatelstwo", "text:wizy", "text:ochrona_miedzynarodowa", "text:zatrudnianie_cudzoziemcow", "text:obywatele_innych_panstw", "text:uznawanie_kwalifikacji", "text:nierezydenci"]','{"term":10,"number":"3140","title":"Rządowy projekt ustawy o ratyfikacji Wzmocnionej umowy o partnerstwie i współpracy między Unią Europejską i jej państwami członkowskimi, z jednej strony, a Republiką Uzbekistanu, z drugiej strony, sporządzonej w Brukseli dnia 24 października 2025 r","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-09-28T11:52:32Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3140","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SZA","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SUE","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3140","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SZA","sub_committee":false,"committee_name":"Komisja Spraw Zagranicznych","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SUE","sub_committee":false,"committee_name":"Komisja do Spraw Unii Europejskiej","children":[]}]}]','0b692e13483a07bc627b009e904be7189ab095bb2d750525d4b9ca93e55ad32d','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект даёт согласие на ратификацию Расширенного соглашения о партнёрстве и сотрудничестве между ЕС и Узбекистаном. Соглашение в основном касается торговли и сотрудничества, но содержит положения о миграции, реадмиссии граждан без права пребывания и деловых поездках. Прямо польское право оно не меняет.","key_changes":["Узбекистан и страны ЕС обязуются без промедления принимать обратно своих граждан, не имеющих права на пребывание","Документы для возврата выдаются в течение 30 дней после запроса о реадмиссии","Предусмотрен диалог о легальной миграции, защите прав легальных мигрантов и интеграции","Стороны могут начать переговоры о соглашении об упрощении визового режима","Внутрикорпоративный перевод: пребывание до 3 лет; бизнес-визиты для создания компании — до 90 дней"],"affected_groups":["граждане Узбекистана в Польше","граждане Узбекистана без законного права на пребывание","сотрудники компаний, переводимые внутри корпорации","поставщики услуг по контракту из Узбекистана"],"practical_impact":"Для граждан Узбекистана, не имеющих законного права на пребывание в Польше, упрощается процедура возврата на родину (реадмиссии). Требования ustawa o cudzoziemcach (закон об иностранцах) к въезду, пребыванию и работе продолжают действовать; соглашение не даёт физическим лицам прав, на которые можно ссылаться напрямую.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.8,"rationale":"Ратификация двустороннего соглашения с миграционными и реадмиссионными положениями, не меняющего польское право напрямую, относится к косвенному влиянию (балл 2).","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":1199982,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3140/3140.pdf","source_kind":"print","revision":1,"text_sha256":"c9e3239a71f94f23614e5789a1164dce5b9300379487c172b974aeb046cf0215","source_checked_at":"2026-09-28T15:56:31Z"}',0,NULL,'2026-09-28T15:32:10+00:00','2026-09-30T16:01:01+00:00','{"term":10,"number":"RPW/32104/2026","title":"Rządowy projekt ustawy o ratyfikacji Wzmocnionej umowy o partnerstwie i współpracy między Unią Europejską i jej państwami członkowskimi, z jednej strony, a Republiką Uzbekistanu, z drugiej strony, sporządzonej w Brukseli dnia 24 października 2025 r","description":null,"applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-23","print_number":"3140","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3140","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SZA","sub_committee":false,"committee_name":"Komisja Spraw Zagranicznych","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SUE","sub_committee":false,"committee_name":"Komisja do Spraw Unii Europejskiej","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3140/3140.pdf","kind":"print","extra_urls":[]},"analysis_sha256":"c9e3239a71f94f23614e5789a1164dce5b9300379487c172b974aeb046cf0215","analysis_revision":1,"seen_supplements":[]}',1,NULL,NULL,NULL,'full','relevant_analysis');
INSERT INTO "bills" VALUES(10,'3141','Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw','2026-09-28T11:54:29+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3141","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw","description":"projekt dotyczy wprowadzenia zasad powoływania Ośrodków Eksperckich Chorób Rzadkich; uszczelnienia systemu ubezpieczenia zdrowotnego w stosunku do osób w sytuacjach transgranicznych związanych ze stosowaniem unijnych przepisów o koordynacji systemów zabezpieczenia społecznego wobec braku zgodności przepisów w zakresie transgranicznej opieki zdrowotnej z wymogami prawa unijnego oraz występowania tzw. luk prawnych w zakresie uregulowań dotyczących pobierania składek na ubezpieczenie zdrowotne z emerytur i rent transferowanych na rachunki bankowe z innych państw członkowskich Unii Europejskiej lub państwa członkowskiego Europejskiego Porozumienia o Wolnym Handlu i Zjednoczonego Królestwa Wielkiej Brytanii i Irlandii Północnej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-24","document_date":"2026-09-23","change_date":"2026-09-28T11:54:29Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-155-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-155-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-24","print_number":"3141","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ZDR","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-24","print_number":"3141","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ZDR","sub_committee":false,"committee_name":"Komisja Zdrowia","children":[]}]}]','9d4c48d92bdeed628f7aeeff4a5f4f2ed1c6bf4f72756f188b1ba0b62ec10a40','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет правила медстрахования NFZ в трансграничных ситуациях ЕС/EFTA/Великобритании и порядок возмещения расходов на лечение за границей. Он также включает в медстрахование слушателей курсов польского языка и выпускников медицинских направлений на практическом обучении.","key_changes":["Новая процедура возмещения NFZ расходов на необходимое лечение в ЕС/EFTA/UK по правилам координации (art. 42ia)","К заявлению на согласие NFZ можно приложить заключение врача из ЕС/EFTA/UK с присяжным переводом","Медстрахование для слушателей курсов польского языка и подготовительных курсов, если нет другого основания","Пенсионеры должны в течение 14 дней сообщить в ZUS/KRUS об окончании работы в ЕС/EFTA/UK, иначе долг удержат из пенсии","NFZ сможет сам зарегистрировать члена семьи в медстраховании, если по правилам координации он должен быть застрахован в Польше"],"affected_groups":["слушатели курсов польского языка и подготовительных курсов к учёбе на польском","выпускники медицинских направлений на иностранном языке, проходящие практическое обучение в Польше","получатели пенсий из ЕС/EFTA/UK, проживающие в Польше","члены семей застрахованных в трансграничных ситуациях","пациенты, лечащиеся в других странах ЕС/EFTA/UK"],"practical_impact":"Слушатели курсов польского языка и выпускники-медики на практике получают право на медстрахование NFZ, если у них нет другого основания, а пенсионеры с работой в ЕС/EFTA/UK должны в течение 14 дней уведомить пенсионный орган об её окончании. Возмещение расходов на лечение за границей получает единую процедуру; к заявлению можно приложить заключение зарубежного врача с присяжным переводом.","effective_date":"Через 14 дней после опубликования, кроме art. 1 pkt 9 lit. e и g, pkt 13 и art. 2 — через 12 месяцев, а также art. 1 pkt 25 и art. 3 — через 9 месяцев после опубликования.","confidence":0.85,"rationale":"Проект касается медстрахования NFZ и доступа к лечению, в том числе для слушателей языковых курсов и лиц в трансграничных ситуациях, что относится к социальной сфере (оценка 3).","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":151007,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T17:19:34Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3141/3141.pdf","source_kind":"print","revision":3,"text_sha256":"113c0c5c2684218532aecbd424c368a1387f7d38da08037118210464ea3724bf","source_checked_at":"2026-09-28T17:19:34Z"}',0,NULL,'2026-09-28T15:32:10+00:00','2026-09-30T16:00:50+00:00','{"term":10,"number":"RPW/32097/2026","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw","description":"wprowadzenia zasad powoływania Ośrodków Eksperckich Chorób Rzadkich; uszczelnienia systemu ubezpieczenia zdrowotnego w stosunku do osób w sytuacjach transgranicznych związanych ze stosowaniem unijnych przepisów o koordynacji systemów zabezpieczenia społecznego wobec braku zgodności przepisów w zakresie transgranicznej opieki zdrowotnej z wymogami prawa unijnego oraz występowania tzw. luk prawnych w zakresie uregulowań dotyczących pobierania składek na ubezpieczenie zdrowotne z emerytur i rent transferowanych na rachunki bankowe z innych państw członkowskich Unii Europejskiej lub państwa członkowskiego Europejskiego Porozumienia o Wolnym Handlu i Zjednoczonego Królestwa Wielkiej Brytanii i Irlandii Północnej","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-23","print_number":"3141","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RCL/12412454',NULL,NULL,NULL,'[{"kind": "committee", "ref": "ZDR/168/2026-10-08+15:30+sala im. Olgi Krzyżanowskiej (nr 412, bud. U)", "date": "2026-10-08", "end_date": null, "start_time": "15:30:00", "committee_code": "ZDR", "committee_name": "Komisja Zdrowia", "sitting_number": 168, "room": "sala im. Olgi Krzyżanowskiej (nr 412, bud. U)", "text": "Pierwsze czytanie rządowego projektu ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw (druk nr 3141) – uzasadnia Minister Zdrowia.", "video_url": "https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=19F7DDA771ED23C7C1258E82003C53EE", "condition": null, "closed": false, "apply_email": null, "apply_by": null}]',NULL,NULL,'UD428',NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-24","print_number":"3141","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ZDR","sub_committee":false,"committee_name":"Komisja Zdrowia","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3141/3141.pdf","kind":"print","extra_urls":[]},"analysis_sha256":"113c0c5c2684218532aecbd424c368a1387f7d38da08037118210464ea3724bf","analysis_revision":3,"seen_supplements":[]}',3,NULL,NULL,NULL,'full','telegram_thread');
INSERT INTO "bills" VALUES(10,'3142','Rządowy projekt ustawy zmieniającej ustawę o zmianie ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi','2026-09-28T12:08:02+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3142","title":"Rządowy projekt ustawy zmieniającej ustawę o zmianie ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi","description":"projekt dotyczy zmiany daty końcowej obowiązywania wykazu świadczeniodawców zakwalifikowanych do systemu podstawowego szpitalnego zabezpieczenia świadczeń opieki\nzdrowotnej, z dnia 30 czerwca 2027 r., na dzień 30 czerwca 2029 r","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-09-28T12:08:02Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-28T15:32:10+00:00','2026-09-29T17:20:37+00:00','{"term":10,"number":"RPW/32087/2026","title":"Rządowy projekt ustawy zmieniającej ustawę o zmianie ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi","description":"zmiany daty końcowej obowiązywania wykazu świadczeniodawców zakwalifikowanych do systemu podstawowego szpitalnego zabezpieczenia świadczeń opieki\nzdrowotnej, z dnia 30 czerwca 2027 r., na dzień 30 czerwca 2029 r","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-23","print_number":"3142","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3143','Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi','2026-09-28T12:08:08+00:00',NULL,0,'analyzed','["text:obywatele_ukrainy"]','{"term":10,"number":"3143","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi","description":"projekt dotyczy określenia sposobu finansowania świadczeń opieki zdrowotnej udzielanych: osadzonym w zakładach penitencjarnych w ramach programu polityki zdrowotnej leczenia wirusowego zapalenia wątroby typu C (HCV) i osobom nieposiadającym uprawnień z tytułu ubezpieczenia zdrowotnego w ramach programu polityki zdrowotnej leczenia antyretrowirusowego osób zakażonych HIV. Świadczenia te będą finansowane przez NFZ, niezależnie od tego, czy dana osoba posiada ubezpieczenie zdrowotne.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-09-28T12:08:08Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-159-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-159-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3143","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ZDR","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3143","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ZDR","sub_committee":false,"committee_name":"Komisja Zdrowia","children":[]}]}]','ab53bdb954d41412af5191888e8bf74911a521ac2caed09d988ff90acf4241df','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект уточняет, кто оплачивает медицинские услуги в двух государственных программах: лечение ВИЧ для людей без медицинской страховки и лечение гепатита C у заключённых. Визиты и анализы в программе лечения ВИЧ для незастрахованных будут оплачиваться из госбюджета. Иностранцы прямо не упоминаются, но касается это и незастрахованных иностранцев.","key_changes":["Услуги, связанные с антиретровирусным лечением ВИЧ, для лиц без права на страховку NFZ оплачиваются из госбюджета (бюджет министра здравоохранения)","Цель — устранить практику, когда за визиты и анализы в программе лечения ВИЧ с незастрахованных брали плату","NFZ сможет финансировать не только лекарства, но и медицинские услуги в программе лечения гепатита C у заключённых","Средства NFZ на программы передаются на счета бюджетных учреждений в сроках и суммах, определяемых министром здравоохранения"],"affected_groups":["люди, живущие с ВИЧ, без медицинской страховки в Польше, в том числе иностранцы","заключённые с хроническим гепатитом C","медучреждения, реализующие программу лечения ВИЧ"],"practical_impact":"Незастрахованный иностранец с ВИЧ, находящийся в Польше, должен получать в рамках программы не только бесплатные лекарства, но и бесплатные визиты к врачу и анализы, без оплаты из собственного кармана.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.65,"rationale":"Законопроект не касается иностранцев как таковых, но улучшает доступ к лечению ВИЧ для всех незастрахованных, среди которых значительную часть составляют иностранцы, поэтому влияние косвенное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":23123,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3143/3143.pdf","source_kind":"print","revision":1,"text_sha256":"8bb9393c139e45c2aaf392d29025b78844821bb0d8aedc9feba2246a43f5b254","source_checked_at":"2026-09-28T15:56:31Z"}',0,NULL,'2026-09-28T15:32:11+00:00','2026-09-30T16:01:01+00:00','{"term":10,"number":"RPW/32111/2026","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi","description":"określenia sposobu finansowania świadczeń opieki zdrowotnej udzielanych: osadzonym w zakładach penitencjarnych w ramach programu polityki zdrowotnej leczenia wirusowego zapalenia wątroby typu C (HCV) i osobom nieposiadającym uprawnień z tytułu ubezpieczenia zdrowotnego w ramach programu polityki zdrowotnej leczenia antyretrowirusowego osób zakażonych HIV. Świadczenia te będą finansowane przez NFZ, niezależnie od tego, czy dana osoba posiada ubezpieczenie zdrowotne.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-23","print_number":"3143","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,'[{"kind": "committee", "ref": "ZDR/169/2026-10-08+13:00+sala im. Leszka Moczulskiego (nr 211, bud. U)", "date": "2026-10-08", "end_date": null, "start_time": "13:00:00", "committee_code": "ZDR", "committee_name": "Komisja Zdrowia", "sitting_number": 169, "room": "sala im. Leszka Moczulskiego (nr 211, bud. U)", "text": "Pierwsze czytanie rządowego projektu ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi (druk nr 3143)", "video_url": "https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=356C25BF3DD66CD1C1258E8200442D99", "condition": null, "closed": false, "apply_email": null, "apply_by": null}]',NULL,NULL,NULL,NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3143","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ZDR","sub_committee":false,"committee_name":"Komisja Zdrowia","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3143/3143.pdf","kind":"print","extra_urls":[]},"analysis_sha256":"8bb9393c139e45c2aaf392d29025b78844821bb0d8aedc9feba2246a43f5b254","analysis_revision":1,"seen_supplements":[]}',1,NULL,NULL,NULL,'full','relevant_analysis');
INSERT INTO "bills" VALUES(10,'3144','Rządowy projekt ustawy o zmianie ustawy o działalności leczniczej oraz ustawy o systemie informacji w ochronie zdrowia','2026-09-28T11:54:49+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3144","title":"Rządowy projekt ustawy o zmianie ustawy o działalności leczniczej oraz ustawy o systemie informacji w ochronie zdrowia","description":"projekt dotyczy wprowadzenia większej jawności konkursów na udzielanie świadczeń zdrowotnych oraz zawieranych umów. Podmioty lecznicze będą publikować m.in. informacje o konkursach, ich wynikach oraz warunkach finansowych ofert. Dane będą udostępniane na stronach internetowych, jak i w centralnej aplikacji","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-09-28T11:54:49Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-28T15:32:11+00:00','2026-09-29T17:20:37+00:00','{"term":10,"number":"RPW/32098/2026","title":"Rządowy projekt ustawy o zmianie ustawy o działalności leczniczej oraz ustawy o systemie informacji w ochronie zdrowia","description":"wprowadzenia większej jawności konkursów na udzielanie świadczeń zdrowotnych oraz zawieranych umów. Podmioty lecznicze będą publikować m.in. informacje o konkursach, ich wynikach oraz warunkach finansowych ofert. Dane będą udostępniane na stronach internetowych, jak i w centralnej aplikacji","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-23","print_number":"3144","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3145','Rządowy projekt ustawy o zmianie ustawy o zdrowiu publicznym oraz niektórych innych ustaw','2026-09-28T11:57:26+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3145","title":"Rządowy projekt ustawy o zmianie ustawy o zdrowiu publicznym oraz niektórych innych ustaw","description":"projekt dotyczy uproszczenia poboru opłaty od środków spożywczych oraz wyeliminowania zidentyfikowanych ograniczeń i wątpliwości interpretacyjnych związanych ze stosowaniem obowiązujących przepisów dotyczących opłaty od środków spożywczych. W szczególności proponuje się doprecyzowanie definicji napoju podlegającego opłacie oraz skonkretyzowanie zdarzeń powodujących powstanie obowiązku zapłaty opłaty. Istotną zmianą zaproponowaną w projekcie jest powiązanie obowiązku zapłaty opłaty z pierwszą sprzedażą napoju, a nie jak było dotychczas - z wprowadzeniem napoju na rynek krajowy.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-24","document_date":"2026-09-24","change_date":"2026-09-28T11:57:26Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-28T15:32:12+00:00','2026-09-29T17:20:37+00:00','{"term":10,"number":"RPW/32223/2026","title":"Rządowy projekt ustawy o zmianie ustawy o zdrowiu publicznym oraz niektórych innych ustaw","description":"uproszczenia poboru opłaty od środków spożywczych oraz wyeliminowania zidentyfikowanych ograniczeń i wątpliwości interpretacyjnych związanych ze stosowaniem obowiązujących przepisów dotyczących opłaty od środków spożywczych. W szczególności proponuje się doprecyzowanie definicji napoju podlegającego opłacie oraz skonkretyzowanie zdarzeń powodujących powstanie obowiązku zapłaty opłaty. Istotną zmianą zaproponowaną w projekcie jest powiązanie obowiązku zapłaty opłaty z pierwszą sprzedażą napoju, a nie jak było dotychczas ? z wprowadzeniem napoju na rynek krajowy.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-24","print_number":"3145","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3146','Rządowy projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw','2026-09-28T11:54:34+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:migracja", "text:straz_graniczna", "text:granica_panstwowa", "text:schengen", "text:pracownicy_delegowani"]','{"term":10,"number":"3146","title":"Rządowy projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw","description":"projekt dotyczy zapewnienia stosowania przepisów rozporządzenia Parlamentu Europejskiego i Rady (UE) 2019/1896; rozszerzenia w sposób istotny zakres działania Europejskiej Agencji Straży Granicznej i Przybrzeżnej, jako podmiotu, który ma dysponować znacznie większymi niż dotychczas zasobami kadrowymi i sprzętowymi. Rozporządzenie 2019/1896, w ramach rozszerzania mandatu Agencji Frontex, tworzy stałą służbę Europejskiej Straży Granicznej i Przybrzeżnej, aby skuteczniej wspierać państwa członkowskie w zakresie ochrony granic zewnętrznych, walki z przestępczością transgraniczną oraz zwiększać skuteczność i trwały charakter powrotów migrantów o nieuregulowanym statusie","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-09-28T11:54:34Z","passed":false,"urgency_status":"NORMAL","eu_related":true,"rcl_num":"RM-0610-143-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-143-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3146","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ASW","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3146","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]}]','4db6045f25ab65a5b3dc8fb1debef0d4ddfbf70d8e711d603ebc14f30014b11f','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект приводит польское законодательство в соответствие с регламентом ЕС 2019/1896 о Frontex. Для иностранцев главное: в ustawa o cudzoziemcach (закон об иностранцах) появляется правовая база для операций и интервенций по возвращению (выдворению) при участии Frontex на территории Польши.","key_changes":["В ustawa o cudzoziemcach вводятся понятия «operacja powrotowa» и «interwencja powrotowa» по регламенту ЕС 2019/1896","Komendant Główny SG сможет запрашивать у Frontex операции возвращения и давать согласие на них в Польше","Персонал Frontex и погранслужб стран ЕС сможет выполнять задачи по возвращению в Польше, включая применение силы","Польских пограничников можно будет направлять офицерами по возвращению (EURLO) в третьи страны для установления личности иностранцев","Frontex получает право регистрировать свои служебные машины, которые приравнены к спецтранспорту"],"affected_groups":["иностранцы, обязанные покинуть Польшу по решению о возвращении","иностранцы на внешней границе ЕС","сотрудники Straży Granicznej"],"practical_impact":"Права и процедуры для иностранцев не меняются, но выдворение из Польши и контроль на внешней границе смогут проводиться с участием сотрудников Frontex и других стран ЕС, в том числе с применением силы по правилам регламента ЕС.","effective_date":"Через 14 дней со дня опубликования.","confidence":0.85,"rationale":"Проект касается исполнения возвращений и пограничного контроля, но не меняет основания легализации и права иностранцев, поэтому это косвенное влияние.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":118838,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T16:14:59Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3146/3146.pdf","source_kind":"print","revision":2,"text_sha256":"e4d525e776970059034fef2588e362ef0b3f7fa209c5cc7bdcce3efc3dbd753a","source_checked_at":"2026-09-28T16:14:59Z"}',0,NULL,'2026-09-28T15:32:12+00:00','2026-09-30T16:01:01+00:00','{"term":10,"number":"RPW/32084/2026","title":"Rządowy projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw","description":"zapewnienia stosowania przepisów rozporządzenia Parlamentu Europejskiego i Rady (UE) 2019/1896; rozszerzenia w sposób istotny zakres działania Europejskiej Agencji Straży Granicznej i Przybrzeżnej, jako podmiotu, który ma dysponować znacznie większymi niż dotychczas zasobami kadrowymi i sprzętowymi. Rozporządzenie 2019/1896, w ramach rozszerzania mandatu Agencji Frontex, tworzy stałą służbę Europejskiej Straży Granicznej i Przybrzeżnej, aby skuteczniej wspierać państwa członkowskie w zakresie ochrony granic zewnętrznych, walki z przestępczością transgraniczną oraz zwiększać skuteczność i trwały charakter powrotów migrantów o nieuregulowanym statusie","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-23","print_number":"3146","eu_related":true,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RCL/12405005',NULL,NULL,NULL,NULL,NULL,NULL,'UC126',NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3146","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3146/3146.pdf","kind":"print","extra_urls":[]},"analysis_sha256":"e4d525e776970059034fef2588e362ef0b3f7fa209c5cc7bdcce3efc3dbd753a","analysis_revision":2,"seen_supplements":[]}',3,NULL,NULL,NULL,'full','relevant_analysis');
INSERT INTO "bills" VALUES(10,'3074','Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz niektórych innych ustaw','2026-09-18T12:21:29+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3074","title":"Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz niektórych innych ustaw","description":"projekt dotyczy usprawnienia zasad rozliczania VAT przy sprzedaży on-line towarów i usług w innych państwach Unii Europejskiej. Zmiany mają ułatwić przedsiębiorcom korzystanie z unijnego systemu OSS, ograniczyć obowiązki związane z rejestracją VAT w różnych krajach UE oraz doprecyzować przepisy dotyczące sprzedaży wysyłkowej.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-08","document_date":"2026-09-07","change_date":"2026-09-18T12:21:29Z","passed":false,"urgency_status":"NORMAL","eu_related":true,"rcl_num":"RM-0610-135-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-135-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-08","print_number":"3074","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-10","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-10","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-17","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-17","committee_code":"FPB","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-08","print_number":"3074","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-10","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-10","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-17","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-17","committee_code":"FPB","sub_committee":false,"committee_name":"Komisja Finansów Publicznych","children":[]}]}]','e8d9a5fb8124191629f09344af4b9b8bf54183030209814bd68675f89898cc1d','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект касается изменений в налоге на товары и услуги (VAT) в связи с внедрением директивы ЕС о цифровой эпохе НДС, и не затрагивает напрямую вопросы пребывания, работы или прав иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Проект касается изменений в налоге на товары и услуги (VAT) в связи с внедрением директивы ЕС о цифровой эпохе НДС, и не затрагивает напрямую вопросы пребывания, работы или прав иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":6004,"truncated":true,"text_source":"excerpts","created_at":"2026-09-15T15:48:04Z","input_tokens":4322,"output_tokens":113,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-28T17:20:42+00:00','2026-09-30T16:00:59+00:00',NULL,'RCL/12409802',NULL,NULL,NULL,'[{"kind": "committee", "ref": "FPB/328/2026-10-06+12:30+sala im. Konstytucji 3-go Maja (nr 118, bud. C)", "date": "2026-10-06", "end_date": null, "start_time": "12:30:00", "committee_code": "FPB", "committee_name": "Komisja Finansów Publicznych", "sitting_number": 328, "room": "sala im. Konstytucji 3-go Maja (nr 118, bud. C)", "text": "Rozpatrzenie rządowego projektu ustawy o