INSERT INTO "bills" VALUES(10,'RCL/12415151','projekt ustawy o zmianie ustawy – Prawo geologiczne i górnicze oraz ustawy o odpadach','2026-09-29T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','["text:migracja"]','{"term":10,"number":"RCL/12415151","title":"projekt ustawy o zmianie ustawy – Prawo geologiczne i górnicze oraz ustawy o odpadach","description":"GÓRNICZE I GEOLOGICZNE PRAWO; środowisko. Numer i tytuł aktu prawnego Unii Europejskiej: 1. dyrektywa Rady 1999/31/WE z dnia 26 kwietnia 1999 r. w sprawie składowania odpadów 2. decyzja Rady nr 2003/33/WE z dnia 19 grudnia 2002 r. ustanawiającej kryteria i procedury przyjęcia odpadów na składowiska, na podstawie art. 16 i załącznika II do dyrektywy 1999/31/WE","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-29","document_date":"2026-09-29","change_date":"2026-09-29T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12415151","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]}]','679c05afd5fa16cafb3eca98bb074aa4526077b6cd186b114ca848e071a42c29',NULL,0,'text prefilter: under the threshold of 2 distinct patterns (migracja×1)','2026-09-29T11:26:58+00:00','2026-09-29T11:26:58+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12415151,"title":"projekt ustawy o zmianie ustawy – Prawo geologiczne i górnicze oraz ustawy o odpadach","applicant":"Minister Klimatu i Środowiska","wykaz_number":"UD400","wykaz_url":"https://www.gov.pl/web/premier/projekt-ustawy-o-zmianie-ustawy--prawo-geologiczne-i-gornicze-oraz-ustawy-o-odpadach","created":"2026-09-29","modified":"2026-09-29","departments":["środowisko"],"keywords":["GÓRNICZE I GEOLOGICZNE PRAWO"],"status":"otwarty","eu_n