INSERT INTO "bills" VALUES(10,'3147','Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych, ustawy o podatku dochodowym od osób prawnych oraz ustawy o zryczałtowanym podatku dochodowym od niektórych przychodów osiąganych przez osoby fizyczne','2026-09-29T14:08:49+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3147","title":"Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych, ustawy o podatku dochodowym od osób prawnych oraz ustawy o zryczałtowanym podatku dochodowym od niektórych przychodów osiąganych przez osoby fizyczne","description":"projekt dotyczy podniesienia pierwszego progu podatkowego do 130 tys. zł oraz wprowadzenie 24% stawki dla dochodów powyżej 130 tys. zł do 150 tys. zł., trzecia, najwyższa stawka 32% będzie dotyczyć dochodów powyżej 150 tys. zł.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-29","document_date":"2026-09-29","change_date":"2026-09-29T14:08:49Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-165-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-165-26","prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-29T17:20:37+00:00','2026-09-30T18:28:42+00:00','{"term":10,"number":"RPW/32719/2026","title":"Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych, ustawy o podatku dochodowym od osób prawnych oraz ustawy o zryczałtowanym podatku dochodowym od niektórych przychodów osiąganych przez osoby fizyczne","description":"podniesienia pierwszego progu podatkowego do 130 tys. zł oraz wprowadzenie 24% stawki dla dochodów powyżej 130 tys. zł do 150 tys. zł., trzecia, najwyższa stawka 32% będzie dotyczyć dochodów powyżej 150 tys. zł.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-29","print_number":"3147","eu_related":false,"public_consultation":false,"con