INSERT INTO "bills" VALUES(10,'3148','Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku dochodowym od osób prawnych','2026-09-29T14:05:42+00:00',NULL,0,'skipped_text_prefilter','["text:nierezydenci"]','{"term":10,"number":"3148","title":"Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku dochodowym od osób prawnych","description":"projekt dotyczy uszczelnienia zasad opodatkowania fundacji rodzinnych i ograniczenia możliwości wykorzystywania preferencji podatkowych niezgodnie z celem, dla którego powstała ta instytucja. Nowe przepisy obejmą m.in. dochody zagraniczne, krótkoterminowy najem nieruchomości oraz sprzedaż majątku wniesionego do fundacji. Jednocześnie projekt rozszerza zwolnienie z PIT na świadczenia otrzymywane przez dzieci i wnuki rodzeństwa fundatora oraz dzieci i wnuki jego pasierba.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-29","document_date":"2026-09-29","change_date":"2026-09-29T14:05:42Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-167-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-167-26","prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: weak patterns only (nierezydenci×2)','2026-09-29T17:20:39+00:00','2026-09-30T18:28:42+00:00','{"term":10,"number":"RPW/32717/2026","title":"Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku dochodowym od osób prawnych","description":"uszczelnienia zasad opodatkowania fundacji rodzinnych i ograniczenia możliwości wykorzystywania preferencji podatkowych niezgodnie z celem, dla którego powstała ta instytucja. Nowe przepisy obejmą m.in. dochody zagraniczne, krótkoterminowy najem nieruchomości oraz sprzedaż majątku wniesionego do fundacji. Jednocześnie projekt rozszerza zwolnienie z PIT na świadczenia otrzymywane przez dzieci i wnuki rodzeństwa fundatora oraz dzieci i wnuki jego pasierba.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-29","print_number":"3148","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL);
