INSERT INTO "bills" VALUES(10,'RCL/12341804','Projekt ustawy o zmianie ustawy – Prawo bankowe i niektórych innych ustaw','2026-09-29T00:00:00+00:00',NULL,NULL,'analyzed','["text:obywatelstwo", "text:straz_graniczna"]','{"term":10,"number":"RCL/12341804","title":"Projekt ustawy o zmianie ustawy – Prawo bankowe i niektórych innych ustaw","description":"BANKOWE PRAWO; instytucje finansowe. Numer i tytuł aktu prawnego Unii Europejskiej: Niniejsza ustawa w zakresie swojej regulacji: 1) wdraża dyrektywę Parlamentu Europejskiego i Rady (UE) 2019/878 z dnia 20 maja 2019 r. zmieniającą dyrektywę 2013/36/UE w odniesieniu do podmiotów zwolnionych, finansowych spółek holdingowych, finansowych spółek holdingowych o działalności mieszanej, wynagrodzeń, środków i uprawnień nadzorczych oraz środków ochrony kapitału (Dz. Urz. UE L 150 z 7.6.2019, str. 253); 2) służy stosowaniu rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 575/2013 z dnia 26 czerwca 2013 r. w sprawie wymogów ostrożnościowych dla instytucji kredytowych i firm inwestycyjnych, zmieniającego rozporządzenie (UE) nr 648/2012 (Dz. Urz. UE L 176 z 27.06.2013, str. 1, Dz. Urz. UE L 208 z 02.08.2013, str. 68, Dz. Urz. UE L 321 z 30.11.2013, str. 6, Dz. Urz. UE L 165 z 04.06.2014, str. 31, Dz. Urz. UE L 11 z 17.01.2015, str. 37, Dz. Urz. UE L 143 z 09.06.2015, str. 7, Dz. Urz. UE L 328 z 12.12.2015, str. 108, Dz. Urz. UE L 151 z 08.06.2016, str. 4, Dz. Urz. UE L 171 z 29.06.2016, str. 153, Dz. Urz. UE L 336 z 10.12.2016, str. 36, Dz. Urz. UE L 20 z 25.01.2017, str. 4, Dz. Urz. UE L 144 z 07.06.2017, str. 14, Dz. Urz. UE L 310 z 25.11.2017, str. 1, Dz. Urz. UE L 322 z 07.12.2017, str. 27, Dz. Urz. UE L 345 z 27.12.2017, str. 27, Dz. Urz. UE L 347 z 28.12.2017, str. 1 oraz Dz. Urz. UE L 137 z 04.06.2018, str. 3).","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2020-12-29","document_date":"2020-12-29","change_date":"2026-09-29T00:00:00Z","eu_related":true,"rcl_num":"RM-10-108-20","rcl_link":"https://legislacja.rcl.gov.pl/projekt/12341804","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"11. Potwierdzenie projektu przez Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"12. Rada Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"14. Skierowanie projektu ustawy do Sejmu","stage_type":"RclStage","sub_committee":false,"children":[]}]','90e626431414be400e2a5caf22a0773703be4164068163c5d45db78c28591ba9','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект касается банковского права, надзора за банками и финансовыми холдингами, требований к капиталу и оценке членов правления банков; упоминание гражданства и Straży Granicznej — лишь техническая деталь среди перечня требований, не создающая изменений в правах или процедурах для иностранцев как таковых.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Проект касается банковского права, надзора за банками и финансовыми холдингами, требований к капиталу и оценке членов правления банков; упоминание гражданства и Straży Granicznej — лишь техническая деталь среди перечня требований, не создающая изменений в правах или процедурах для иностранцев как таковых.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_chars":10848,"truncated":true,"text_source":"excerpts","created_at":"2026-09-29T17:22:33Z","input_tokens":7326,"output_tokens":137,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"law_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-29T17:22:00+00:00','2026-09-30T18:28:52+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12341804,"title":"Projekt ustawy o zmianie ustawy – Prawo bankowe i niektórych innych ustaw","applicant":"Minister Finansów, Funduszy i Polityki Regionalnej","