INSERT INTO "bills" VALUES(10,'RCL/12332403','Projekt ustawy o zmianie ustawy – Prawo bankowe i niektórych innych ustaw','2026-09-29T00:00:00+00:00',NULL,NULL,'skipped_prefilter','[]','{"term":10,"number":"RCL/12332403","title":"Projekt ustawy o zmianie ustawy – Prawo bankowe i niektórych innych ustaw","description":"BANKOWE PRAWO; instytucje finansowe. Numer i tytuł aktu prawnego Unii Europejskiej: Niniejsza ustawa w zakresie swojej regulacji: 1) wdraża dyrektywę Parlamentu Europejskiego i Rady (UE) 2019/878 z dnia 20 maja 2019 r. zmieniającą dyrektywę 2013/36/UE w odniesieniu do podmiotów zwolnionych, finansowych spółek holdingowych, finansowych spółek holdingowych o działalności mieszanej, wynagrodzeń, środków i uprawnień nadzorczych oraz środków ochrony kapitału (Dz. Urz. UE L 150 z 7.6.2019, str. 253); 2) służy stosowaniu rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 575/2013 z dnia 26 czerwca 2013 r. w sprawie wymogów ostrożnościowych dla instytucji kredytowych i firm inwestycyjnych, zmieniającego rozporządzenie (UE) nr 648/2012 (Dz. Urz. UE L 176 z 27.06.2013, str. 1, Dz. Urz. UE L 208 z 02.08.2013, str. 68, Dz. Urz. UE L 321 z 30.11.2013, str. 6, Dz. Urz. UE L 165 z 04.06.2014, str. 31, Dz. Urz. UE L 11 z 17.01.2015, str. 37, Dz. Urz. UE L 143 z 09.06.2015, str. 7, Dz. Urz. UE L 328 z 12.12.2015, str. 108, Dz. Urz. UE L 151 z 08.06.2016, str. 4, Dz. Urz. UE L 171 z 29.06.2016, str. 153, Dz. Urz. UE L 336 z 10.12.2016, str. 36, Dz. Urz. UE L 20 z 25.01.2017, str. 4, Dz. Urz. UE L 144 z 07.06.2017, str. 14, Dz. Urz. UE L 310 z 25.11.2017, str. 1, Dz. Urz. UE L 322 z 07.12.2017, str. 27, Dz. Urz. UE L 345 z 27.12.2017, str. 27, Dz. Urz. UE L 347 z 28.12.2017, str. 1 oraz Dz. Urz. UE L 137 z 04.06.2018, str. 3).","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2020-04-09","document_date":"2020-04-09","change_date":"2026-09-29T00:00:00Z","eu_related":true,"rcl_num":"RM-10-108-20","rcl_link":"https://legislacja.rcl.gov.p