INSERT INTO "bills" VALUES(10,'3155','Rządowy projekt ustawy o zmianie ustawy o zdrowiu publicznym','2026-09-30T10:49:50+00:00',NULL,0,'skipped_text_prefilter','["text:pobyt_kwalifikowany"]','{"term":10,"number":"3155","title":"Rządowy projekt ustawy o zmianie ustawy o zdrowiu publicznym","description":"projekt dotyczy zwiększenia skuteczności poboru opłaty od środków spożywczych (tzw. opłaty cukrowej) przez rozszerzenie katalogu napojów objętych opłatą oraz aktualizację jej wysokości. Projektowane zmiany umożliwią również zwiększenie przychodów Narodowego Funduszu Zdrowia, które zostaną przeznaczone na działania edukacyjne i profilaktyczne oraz na finansowanie świadczeń opieki zdrowotnej, w szczególności w zakresie leczenia chorób związanych z nieprawidłowymi\nnawykami żywieniowymi, takich jak nadwaga i otyłość.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-29","document_date":"2026-09-29","change_date":"2026-09-30T10:49:50Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-166-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-166-26","prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-29","print_number":"3155","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-30","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-30","committee_code":"Sejm","sub_committee":false,"children":[]}]}]','785c6cb2e9d6a80793020e75a8f8c33dd2ef33d0a1be7885cf01d5358b630f01',NULL,0,'text prefilter: under the threshold of 2 distinct patterns (pobyt_kwalifikowany×1)','2026-09-30T11:14:23+00:00','2026-09-30T18:28:42+00:00','{"term":10,"number":"RPW/32721/2026","title":"Rządowy projekt ustawy o zmianie ustawy o zdrowiu publicznym","description":"zwiększenia skuteczności poboru opłaty od środków spożywczych (tzw. opłaty cukrowej) przez rozszerzenie katalogu napojów objętych opłatą oraz aktualizację jej wysokości. Projektowane zmiany umożliwią również zwiększenie przychodów Narodowego Funduszu Zdrowia, które zostaną przeznaczone na działania edukacyjne i profilaktyczne oraz na finansowanie świadczeń opieki zdrowotnej, w szczególności w zakresie leczenia chorób związanych z nieprawidłowymi\nnawykami żywieniowymi, takich jak nadwaga i otyłość.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-29","print_number":"3155","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RPW/32721/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-29","print_number":"3155","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-30","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-30","committee_code":"Sejm","sub_committee":false,"children":[]}]}],"passed":false,"analysis_revision":0}',0,NULL,NULL,NULL,NULL,NULL);
