INSERT INTO "bills" VALUES(10,'RCL/12405803','Projekt ustawy o zmianie ustawy o funduszach inwestycyjnych i zarządzaniu alternatywnymi funduszami inwestycyjnymi oraz niektórych innych ustaw','2026-09-30T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','[]','{"term":10,"number":"RCL/12405803","title":"Projekt ustawy o zmianie ustawy o funduszach inwestycyjnych i zarządzaniu alternatywnymi funduszami inwestycyjnymi oraz niektórych innych ustaw","description":"FUNDUSZE INWESTYCYJNE; instytucje finansowe. Numer i tytuł aktu prawnego Unii Europejskiej: Dyrektywa Parlamentu Europejskiego i Rady (UE) 2024/927 z dnia 13 marca 2024 r. zmieniająca dyrektywy 2011/61/UE i 2009/65/WE w zakresie ustaleń dotyczących przekazywania, zarządzania ryzykiem utraty płynności, sprawozdawczości nadzorczej, świadczenia usług depozytariusza i usług powierniczych oraz udzielania pożyczek przez alternatywne fundusze inwestycyjne (Dz. Urz. UE L 2024/927 z 26.03.2024),","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-01-05","document_date":"2026-07-20","change_date":"2026-09-30T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12405803","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2026-06-22","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]}]','3223ce11c7a53f1004c4d3e882ee871995dc842c2ad0aea498aba8a1b4d78f9a',NULL,0,'text prefilter: no keyword hits','2026-09-3