INSERT INTO "publications" VALUES(63,10,'RCL/12409801','consultation_results','sent','@lex_inform_pl',64,'[]',NULL,'2026-09-28T15:36:12+00:00','2026-09-28T15:36:12+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"RCL/12409801\",\"title\":\"Projekt ustawy o zmianie ustawy – Prawo o ruchu drogowym oraz niektórych innych ustaw\",\"description\":\"RUCH DROGOWY; informatyzacja\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-04-30\",\"document_date\":\"2026-04-30\",\"change_date\":\"2026-09-28T00:00:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":\"https://legislacja.rcl.gov.pl/projekt/12409801\",\"prints_considered_jointly\":[],\"applicant\":\"government\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[],\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"6672da2ae796ddf843b3f99a2c18d5ea37b2046ef5e88a58c6c3ceac1f2db272\",\"observed_closure_date\":null,\"observed_process\":{\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":null,\"passed\":null,\"document\":{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12409801/13201107/13201108/dokument774418.docx\",\"kind\":\"rcl\",\"extra_urls\":[]},\"analysis_sha256\":\"8668caa4c9a0dea46d0b1a2825f4a257f87d74752d5630ede8bf5d25a339759e\",\"analysis_revision\":1,\"seen_supplements\":null},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект цифровизирует регистрацию автомобилей и выдачу водительских удостоверений: заявления через интернет, электронный dowód rejestracyjny, электронный договор купли-продажи авто. Для иностранцев ключевое — обмен/получение прав и карты квалификации водителя будет требовать номер PESEL.\",\"key_changes\":[\"Получение prawo jazdy требует наличия номера PESEL (новый пункт в art. 11)\",\"Обмен иностранного национального удостоверения на польское — только при наличии PESEL (art. 14)\",\"Karta kwalifikacji kierowcy выдаётся лицам с иностранными правами при наличии PESEL\",\"Ликвидация PKK и профиля профессионального водителя — идентификация по PESEL в CEK\",\"Электронный договор продажи авто доступен только физлицам с PESEL и юрлицам с местом в Польше\"],\"affected_groups\":[\"иностранцы, обменивающие иностранные права на польские\",\"иностранцы-водители профессионального транспорта\",\"владельцы автомобилей без номера PESEL\",\"кандидаты на получение польских прав\"],\"practical_impact\":\"Без номера PESEL нельзя будет получить или обменять польское водительское удостоверение, карту квалификации водителя и пройти профессиональную квалификацию, а также воспользоваться онлайн-договором продажи авто; одновременно большинство процедур (заявление, электронный техпаспорт, доставка документов почтой) станут доступны онлайн и в любом старостве.\",\"effective_date\":\"Закон вступает в силу через 14 дней после опубликования, за исключением многочисленных положений с датами: 29 ноября 2027 г., 1 января 2028 г., 5 июня 2028 г., 13 ноября 2028 г., 15 января 2029 г., 2 июля 2029 г. и 14 января 2030 г.\",\"confidence\":0.72,\"rationale\":\"Затрагивает водительские документы и обмен иностранных прав, вводя требование PESEL — сфера повседневных административных прав, а не легализации пребывания.\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v7\",\"input_chars\":145563,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-09-15T11:32:14Z\",\"input_tokens\":72745,\"output_tokens\":955,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":2496,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12409801/13201107/13201108/dokument774418.docx\",\"source_kind\":\"rcl\",\"revision\":1,\"text_sha256\":\"8668caa4c9a0dea46d0b1a2825f4a257f87d74752d5630ede8bf5d25a339759e\",\"source_checked_at\":null},\"analysis_attempts\":0,\"analysis_generation\":0,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":{\"id\":12409801,\"title\":\"Projekt ustawy o zmianie ustawy – Prawo o ruchu drogowym oraz niektórych innych ustaw\",\"applicant\":\"Minister Cyfryzacji\",\"wykaz_number\":\"UDER87\",\"wykaz_url\":\"https://www.gov.pl/web/premier/wplip-rm\",\"created\":\"2026-04-30\",\"modified\":\"2026-09-28\",\"departments\":[\"informatyzacja\"],\"keywords\":[\"RUCH DROGOWY\"],\"status\":\"otwarty\",\"eu_note\":null,\"term_label\":\"X\",\"rm_number\":null,\"sejm_url\":null,\"print_number\":null,\"stages\":[{\"id\":13201094,\"number\":1,\"name\":\"Zgłoszenia lobbingowe\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"catalog_read\":false},{\"id\":13201095,\"number\":2,\"name\":\"Uzgodnienia\",\"state\":\"reached\",\"started\":null,\"ended\":null,\"modified\":\"2026-09-28\",\"folders\":[{\"id\":13201096,\"name\":\"Projekt\",\"modified\":\"2026-04-30\",\"documents\":[{\"id\":774415,\"name\":\"Projekt ustawy_Uzasadnienie_OSR_ust o zm PRD_uzgodnienia_UDER87_po zmianach_wersja do uzgodnień.docx\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12409801/13201095/13201096/dokument774415.docx\",\"created\":\"2026-04-30\",\"author\":\"Minister Cyfryzacji\"}]},{\"id\":13201097,\"name\":\"Pisma kierujące projekt do uzgodnień\",\"modified\":\"2026-09-28\",\"documents\":[{\"id\":774303,\"name\":\"Pismo MC_Uzgodnienia_pr zm ust PRD_UDER87.pdf\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12409801/13201095/13201097/dokument774303.pdf\",\"created\":\"2026-04-30\",\"author\":\"Minister Cyfryzacji\"},{\"id\":774304,\"name\":\"Projekt ustawy_Uzasadnienie_OSR_ust o zm PRD_uzgodnienia_UDER87_po zmianach_wersja do uzgodnień.docx.xades\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12409801/13201095/13201097/dokument