INSERT INTO "publications" VALUES(64,10,'3141','new_bill','sent','@lex_inform_pl',67,'[]',NULL,'2026-09-28T16:17:50+00:00','2026-09-28T16:15:17+00:00',NULL,0,NULL,'b19a9bbe371056f73c9767546c29819d34cc6c1fad2f9248d941aa607955c698','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3141\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy wprowadzenia zasad powoływania Ośrodków Eksperckich Chorób Rzadkich; uszczelnienia systemu ubezpieczenia zdrowotnego w stosunku do osób w sytuacjach transgranicznych związanych ze stosowaniem unijnych przepisów o koordynacji systemów zabezpieczenia społecznego wobec braku zgodności przepisów w zakresie transgranicznej opieki zdrowotnej z wymogami prawa unijnego oraz występowania tzw. luk prawnych w zakresie uregulowań dotyczących pobierania składek na ubezpieczenie zdrowotne z emerytur i rent transferowanych na rachunki bankowe z innych państw członkowskich Unii Europejskiej lub państwa członkowskiego Europejskiego Porozumienia o Wolnym Handlu i Zjednoczonego Królestwa Wielkiej Brytanii i Irlandii Północnej\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-09-24\",\"document_date\":\"2026-09-23\",\"change_date\":\"2026-09-28T11:54:29Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":null,\"prints_considered_jointly\":[],\"applicant\":\"government\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:repatriacja\",\"text:obywatele_ukrainy\",\"text:pobyt_kwalifikowany\",\"text:karta_polaka\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-24\",\"print_number\":\"3141\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-09-28\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-28\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ZDR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}]}],\"stages_fingerprint\":\"9d4c48d92bdeed628f7aeeff4a5f4f2ed1c6bf4f72756f188b1ba0b62ec10a40\",\"observed_closure_date\":null,\"observed_process\":{\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-24\",\"print_number\":\"3141\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-09-28\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-28\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ZDR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3141/3141.pdf\",\"kind\":\"print\",\"extra_urls\":[]},\"analysis_sha256\":\"113c0c5c2684218532aecbd424c368a1387f7d38da08037118210464ea3724bf\",\"analysis_revision\":1,\"seen_supplements\":null},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Поправки к закону о медицинском страховании NFZ. Страховку получат выпускники медвузов на практическом обучении и слушатели курсов польского языка. Меняются правила взносов с пенсий из стран ЕС, EFTA и Великобритании, а также порядок возмещения расходов на лечение за границей.\",\"key_changes\":[\"Обязательное страхование в NFZ для слушателей курсов польского языка и подготовительных курсов, если у них нет другого основания\",\"Страхование для выпускников медвузов (в т.ч. с обучением не на польском) на практическом обучении по art. 15p\",\"Пенсионеры, закончившие работу в ЕС/EFTA/UK, обязаны сообщить об этом в ZUS/KRUS в течение 14 дней, иначе долг по взносам удержат из пенсии\",\"NFZ сможет сам задним числом зарегистрировать члена семьи, застрахованного по ошибке в другом государстве ЕС\",\"Новая процедура возмещения NFZ расходов на лечение в ЕС/EFTA/UK; к заявке можно приложить заключение зарубежного врача с присяжным переводом\"],\"affected_groups\":[\"иностранцы на курсах польского языка и подготовительных курсах\",\"выпускники медицинских факультетов, в т.ч. англоязычных программ\",\"получатели пенсий из стран ЕС, EFTA и Великобритании, живущие в Польше\",\"члены семей застрахованных в трансграничных ситуациях\",\"пациенты, лечащиеся в других странах ЕС/EFTA/UK\"],\"practical_impact\":\"Слушатели курсов польского языка и выпускники медвузов на практике получат страховку NFZ через вуз, а получатели иностранных пенсий будут платить взнос на здравоохранение через банк и должны вовремя уведомлять ZUS об окончании работы за рубежом. Для людей без места жительства в Польше отделение NFZ определяется по последнему адресу в Польше или по месту нахождения плательщика, без выбора.\",\"effective_date\":\"Через 14 дней после опубликования, кроме: art. 1 pkt 9 lit. e и g, pkt 13 и art. 2 — через 12 месяцев; art. 1 pkt 25 и art. 3 — через 9 месяцев после опубликования.\",\"confidence\":0.75,\"rationale\":\"Законопроект меняет доступ к медицинскому страхованию NFZ и взносы для групп, среди которых много иностранцев (курсы польского, иностранные пенсии, трансграничные ситуации), что относится к социальной сфере.\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5-5\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":151007,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-28T15:56:31Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3141/3141.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":\"113c0c5c2684218532aecbd424c368a1387f7d38da08037118210464ea3724bf\",\"source_checked_at\":\"2026-09-28T15:56:31Z\"},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/32097/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"wprowadzenia zasad powoływania Ośrodków Eksperckich Chorób Rzadkich; uszczelnienia systemu ubezpieczenia zdrowotnego w stosunku do osób w sytuacjach transgranicznych związanych ze stosowaniem unijnych przepisów o koordynacji systemów zabezpieczenia społecznego wobec braku zgodności przepisów w zakresie transgranicznej opieki zdrowotnej z wymogami prawa unijnego oraz występowania tzw. luk prawnych w zakresie uregulowań dotyczących pobierania składek na ubezpieczenie zdrowotne z emerytur i rent transferowanych na rachunki bankowe z innych państw członkowskich Unii Europejskiej lub państwa członkowskiego Europejskiego Porozumienia o Wolnym Handlu i Zjednoczonego Królestwa Wielkiej Brytanii i Irlandii Północnej\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-09-23\",\"print_number\":\"3141\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":null,\"joint\":null,\"discontinued_at\":null,\"observation_mode\":null,\"observation_basis\":null,\"first_seen_at\":\"2026-09-28T15:32:10Z\",\"last_checked_at\":\"2026-09-28T15:32:10Z\"}","change_json":"","print_json":"{\"term\":10,\"number\":\"3141\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw.\",\"document_date\":\"2026-09-23\",\"delivery_date\":\"2026-09-28\",\"change_date\":\"2026-09-28T12:58:22Z\",\"attachments\":[{\"print_number\":\"3141\",\"name\":\"3141.pdf\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3141/3141.pdf\"},{\"print_number\":\"3141\",\"name\":\"3141-ustawa.docx\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3141/3141-ustawa.docx\"},{\"print_number\":\"3141\",\"name\":\"3141-uzasadnienie.docx\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3141/3141-uzasadnienie.docx\"}],\"additional_prints\":[]}","primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":null,"held_change_ids":[]}');
INSERT INTO "publications" VALUES(65,10,'2846','new_bill','sent','@lex_inform_pl',66,'[]',NULL,'2026-09-28T16:15:15+00:00','2026-09-28T16:15:16+00:00',NULL,0,NULL,'0b4a183ffa616eef5763aeeff0afafb1b625aa2aa7b4f66462a425b34cd7e290','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"2846\",\"title\":\"Rządowy projekt ustawy o szczególnych rozwiązaniach związanych z organizacją XXVI Światowego Jamboree Skautowego w Polsce w 2027 r.\",\"description\":\"projekt dotyczy uregulowania współpracy administracji i służb odpowiedzialnych za przygotowanie XXVI Światowego Jamboree Skautowego. Wydarzenie odbędzie się od 29 lipca do 9 sierpnia 2027 r. na Wyspie Sobieszewskiej w Gdańsku. Organizatorem jest Związek Harcerstwa Polskiego we współpracy ze Światową Organizacją Ruchu Skautowego.\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-07-23\",\"document_date\":\"2026-07-23\",\"change_date\":\"2026-09-24T12:59:51Z\",\"closure_date\":\"2026-09-18\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-113-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-113-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:obywatelstwo\",\"text:wizy\",\"text:straz_graniczna\",\"text:schengen\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-07-23\",\"print_number\":\"2846\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-07-27\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":nul