INSERT INTO "publications" VALUES(68,10,'3141','status_update','sent','@lex_inform_pl',68,'[]',48,'2026-09-28T16:18:04+00:00','2026-09-28T16:18:05+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3141\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy wprowadzenia zasad powoływania Ośrodków Eksperckich Chorób Rzadkich; uszczelnienia systemu ubezpieczenia zdrowotnego w stosunku do osób w sytuacjach transgranicznych związanych ze stosowaniem unijnych przepisów o koordynacji systemów zabezpieczenia społecznego wobec braku zgodności przepisów w zakresie transgranicznej opieki zdrowotnej z wymogami prawa unijnego oraz występowania tzw. luk prawnych w zakresie uregulowań dotyczących pobierania składek na ubezpieczenie zdrowotne z emerytur i rent transferowanych na rachunki bankowe z innych państw członkowskich Unii Europejskiej lub państwa członkowskiego Europejskiego Porozumienia o Wolnym Handlu i Zjednoczonego Królestwa Wielkiej Brytanii i Irlandii Północnej\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-09-24\",\"document_date\":\"2026-09-23\",\"change_date\":\"2026-09-28T11:54:29Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-155-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-155-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-24\",\"print_number\":\"3141\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-09-28\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-28\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ZDR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Zdrowia\",\"children\":[]}]}],\"stages_fingerprint\":\"9d4c48d92bdeed628f7aeeff4a5f4f2ed1c6bf4f72756f188b1ba0b62ec10a40\",\"observed_closure_date\":null,\"observed_process\":{\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-24\",\"print_number\":\"3141\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-09-28\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-28\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ZDR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Zdrowia\",\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3141/3141.pdf\",\"kind\":\"print\",\"extra_urls\":[]},\"analysis_sha256\":\"113c0c5c2684218532aecbd424c368a1387f7d38da08037118210464ea3724bf\",\"analysis_revision\":1,\"seen_supplements\":[]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект меняет правила медстрахования NFZ и возмещения расходов на лечение в ЕС/EFTA/Великобритании. Он вводит обязанности для получателей польских и зарубежных пенсий и включает в медстрахование выпускников медицинских направлений на практическом обучении и слушателей курсов польского языка.\",\"key_changes\":[\"Отдельная процедура возмещения NFZ расходов на необходимое лечение в ЕС/EFTA/UK по правилам координации (art. 42ia)\",\"К заявлению на согласие NFZ можно приложить заключение врача из ЕС/EFTA/UK с присяжным переводом\",\"Возврат за лекарство в ЕС/ЕЭЗ по польскому рецепту на возмещение, не только по трансграничному\",\"Медстрахование для выпускников на практическом обучении (art. 15p) и слушателей подготовительных курсов польского языка\",\"Сообщить в ZUS/KRUS об окончании работы в ЕС/EFTA/UK в течение 14 дней, иначе долг по взносам удержат из пенсии\"],\"affected_groups\":[\"выпускники медицинских направлений на иностранном языке, проходящие практическое обучение в Польше\",\"слушатели курсов польского языка и подготовительных курсов к учёбе на польском\",\"получатели пенсий из ЕС/EFTA/UK, живущие в Польше\",\"застрахованные в NFZ, лечащиеся в других странах ЕС/EFTA/UK\",\"члены семей застрахованных в трансграничных ситуациях\"],\"practical_impact\":\"Выпускники-медики на практическом обучении и слушатели подготовительных курсов польского языка получают медстрахование, если не застрахованы по другому основанию. Лечение за границей проще согласовать с NFZ по заключению иностранного врача. Пенсионерам после окончания работы в ЕС/EFTA/UK нужно в течение 14 дней уведомить ZUS/KRUS.\",\"effective_date\":\"Через 14 дней после опубликования; art. 1 pkt 9 lit. e и g, pkt 13 и art. 2 — через 12 месяцев; art. 1 pkt 25 и art. 3 — через 9 месяцев после опубликования.\",\"confidence\":0.8,\"rationale\":\"Проект касается медстрахования NFZ и трансграничного лечения, в том числе групп, где много иностранцев (выпускники иноязычных медицинских программ, слушатели курсов польского языка), поэтому это социальная сфера, оценка 3.\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5-5\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":148783,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-09-28T15:56:32Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12412454/13215502/13215503/dokument797859.zip\",\"source_kind\":\"rcl\",\"revision\":2,\"text_sha256\":\"6f722062659c34910b5eef1ce1542166e5b8b7aafdcc48621ceae7deaf0e6f6b\",\"source_checked_at\":\"2026-09-28T15:56:32Z\"},\"analysis_attempts\":0,\"analysis_generation\":2,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/32097/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"wprowadzenia zasad powoływania Ośrodków Eksperckich Chorób Rzadkich; uszczelnienia systemu ubezpieczenia zdrowotnego w stosunku do osób w sytuacjach transgranicznych związanych ze stosowaniem unijnych przepisów o koordynacji systemów zabezpieczenia społecznego wobec braku zgodności przepisów w zakresie transgranicznej opieki zdrowotnej z wymogami prawa unijnego oraz występowania tzw. luk prawnych w zakresie uregulowań dotyczących pobierania składek na ubezpieczenie zdrowotne z emerytur i rent transferowanych na rachunki bankowe z innych państw członkowskich Unii Europejskiej lub państwa członkowskiego Europejskiego Porozumienia o Wolnym Handlu i Zjednoczonego Królestwa Wielkiej Brytanii i Irlandii Północnej\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-09-23\",\"print_number\":\"3141\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":\"RCL/12412454\",\"linked_wykaz_number\":\"UD428\",\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-28T15:32:10Z\",\"last_checked_at\":\"2026-09-28T16:17:50Z\"}","change_json":"{\"id\":48,\"term\":10,\"number\":\"3141\",\"old_fingerprint\":\"RCL/12412454\",\"new_fingerprint\":\"ff72b64950f73c111b6a73d3c5f6c59121a7cf56c120c1a9ad1a4144d52fd813\",\"new_stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-24\",\"print_number\":\"3141\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-09-28\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-28\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"co