INSERT INTO "publications" VALUES(70,10,'3141','status_update','sent','@lex_inform_pl',69,'[]',51,'2026-09-28T17:22:21+00:00','2026-09-28T17:22:21+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3141\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy wprowadzenia zasad powoływania Ośrodków Eksperckich Chorób Rzadkich; uszczelnienia systemu ubezpieczenia zdrowotnego w stosunku do osób w sytuacjach transgranicznych związanych ze stosowaniem unijnych przepisów o koordynacji systemów zabezpieczenia społecznego wobec braku zgodności przepisów w zakresie transgranicznej opieki zdrowotnej z wymogami prawa unijnego oraz występowania tzw. luk prawnych w zakresie uregulowań dotyczących pobierania składek na ubezpieczenie zdrowotne z emerytur i rent transferowanych na rachunki bankowe z innych państw członkowskich Unii Europejskiej lub państwa członkowskiego Europejskiego Porozumienia o Wolnym Handlu i Zjednoczonego Królestwa Wielkiej Brytanii i Irlandii Północnej\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-09-24\",\"document_date\":\"2026-09-23\",\"change_date\":\"2026-09-28T11:54:29Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-155-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-155-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-24\",\"print_number\":\"3141\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-09-28\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-28\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ZDR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Zdrowia\",\"children\":[]}]}],\"stages_fingerprint\":\"9d4c48d92bdeed628f7aeeff4a5f4f2ed1c6bf4f72756f188b1ba0b62ec10a40\",\"observed_closure_date\":null,\"observed_process\":{\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-24\",\"print_number\":\"3141\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-09-28\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-28\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ZDR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Zdrowia\",\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3141/3141.pdf\",\"kind\":\"print\",\"extra_urls\":[]},\"analysis_sha256\":\"113c0c5c2684218532aecbd424c368a1387f7d38da08037118210464ea3724bf\",\"analysis_revision\":3,\"seen_supplements\":[]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект меняет правила медстрахования NFZ в трансграничных ситуациях ЕС/EFTA/Великобритании и порядок возмещения расходов на лечение за границей. Он также включает в медстрахование слушателей курсов польского языка и выпускников медицинских направлений на практическом обучении.\",\"key_changes\":[\"Новая процедура возмещения NFZ расходов на необходимое лечение в ЕС/EFTA/UK по правилам координации (art. 42ia)\",\"К заявлению на согласие NFZ можно приложить заключение врача из ЕС/EFTA/UK с присяжным переводом\",\"Медстрахование для слушателей курсов польского языка и подготовительных курсов, если нет другого основания\",\"Пенсионеры должны в течение 14 дней сообщить в ZUS/KRUS об окончании работы в ЕС/EFTA/UK, иначе долг удержат из пенсии\",\"NFZ сможет сам зарегистрировать члена семьи в медстраховании, если по правилам координации он должен быть застрахован в Польше\"],\"affected_groups\":[\"слушатели курсов польского языка и подготовительных курсов к учёбе на польском\",\"выпускники медицинских направлений на иностранном языке, проходящие практическое обучение в Польше\",\"получатели пенсий из ЕС/EFTA/UK, проживающие в Польше\",\"члены семей застрахованных в трансграничных ситуациях\",\"пациенты, лечащиеся в других странах ЕС/EFTA/UK\"],\"practical_impact\":\"Слушатели курсов польского языка и выпускники-медики на практике получают право на медстрахование NFZ, если у них нет другого основания, а пенсионеры с работой в ЕС/EFTA/UK должны в течение 14 дней уведомить пенсионный орган об её окончании. Возмещение расходов на лечение за границей получает единую процедуру; к заявлению можно приложить заключение зарубежного врача с присяжным переводом.\",\"effective_date\":\"Через 14 дней после опубликования, кроме art. 1 pkt 9 lit. e и g, pkt 13 и art. 2 — через 12 месяцев, а также art. 1 pkt 25 и art. 3 — через 9 месяцев после опубликования.\",\"confidence\":0.85,\"rationale\":\"Проект касается медстрахования NFZ и доступа к лечению, в том числе для слушателей языковых курсов и лиц в трансграничных ситуациях, что относится к социальной сфере (оценка 3).\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5-5\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":151007,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-28T17:19:34Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3141/3141.pdf\",\"source_kind\":\"print\",\"revision\":3,\"text_sha256\":\"113c0c5c2684218532aecbd424c368a1387f7d38da08037118210464ea3724bf\",\"source_checked_at\":\"2026-09-28T17:19:34Z\"},\"analysis_attempts\":0,\"analysis_generation\":3,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/32097/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"wprowadzenia zasad powoływania Ośrodków Eksperckich Chorób Rzadkich; uszczelnienia systemu ubezpieczenia zdrowotnego w stosunku do osób w sytuacjach transgranicznych związanych ze stosowaniem unijnych przepisów o koordynacji systemów zabezpieczenia społecznego wobec braku zgodności przepisów w zakresie transgranicznej opieki zdrowotnej z wymogami prawa unijnego oraz występowania tzw. luk prawnych w zakresie uregulowań dotyczących pobierania składek na ubezpieczenie zdrowotne z emerytur i rent transferowanych na rachunki bankowe z innych państw członkowskich Unii Europejskiej lub państwa członkowskiego Europejskiego Porozumienia o Wolnym Handlu i Zjednoczonego Królestwa Wielkiej Brytanii i Irlandii Północnej\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-09-23\",\"print_number\":\"3141\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":\"RCL/12412454\",\"linked_wykaz_number\":\"UD428\",\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-28T15:32:10Z\",\"last_checked_at\":\"2026-09-28T17:22:21Z\"}","change_json":"{\"id\":51,\"term\":10,\"number\":\"3141\",\"old_fingerprint\":\"9d4c48d92bdeed628f7aeeff4a5f4f2ed1c6bf4f72756f188b1ba0b62ec10a40\",\"new_fingerprint\":\"26ece6e8fc6a983d266e7a82197b6f40cec07f299a969db8be5a00f983931c31\",\"new_stages\":[],\"closure_detected\":false,\"passed\":false,\"content_changed\":true,\"withdrawn\":false,\"discontinued\":false,\"consultation_opened\":false,\"amendments\":null,\"supplements\":[],\"detected_at\":\"2026-09-28T17:22:20Z\"}","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":67,"held_change_ids":[]}');
