INSERT INTO "publications" VALUES(74,10,'RCL/12398102','new_bill','sent','@lex_inform_pl',72,'[]',NULL,'2026-09-30T11:32:36+00:00','2026-09-30T11:32:37+00:00',NULL,0,NULL,'c119a3a27947ca1e329cef6b33550df2191731e4b2f7ae82fbb91144effa33f5','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"RCL/12398102\",\"title\":\"Projekt ustawy o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw\",\"description\":\"OCHRONA ZDROWIA; zdrowie\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2025-05-22\",\"document_date\":\"2026-06-30\",\"change_date\":\"2026-09-30T00:00:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":\"https://legislacja.rcl.gov.pl/projekt/12398102\",\"prints_considered_jointly\":[],\"applicant\":\"government\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:migracja\",\"text:obywatele_ukrainy\",\"text:karta_polaka\"],\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"9. Stały Komitet Rady Ministrów\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"71bac3c228d1e8cc9bcac5c8c7715d70d29f66da157df09466386f40726954b8\",\"observed_closure_date\":null,\"observed_process\":null,\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект полностью перестраивает правила рефундации лекарств и медизделий за счёт NFZ, вводит новые ИТ‑системы и упрощённые процедуры. Это может улучшить доступ к дорогим и редким лекарствам для всех застрахованных, в т.ч. иностранцев, и меняет данные, которые указываются в рецептах и заявках на возмещение.\",\"key_changes\":[\"Новые процедуры и ИТ‑системы для рефундации и мониторинга программ лековых (SOLR, SOID, System Monitorowania Programów Lekowych, SWDPL)\",\"Подробная регламентация импортa целевого и его рефундации, в т.ч. по заявлению пациента с PESEL или с паспортом, если PESEL нет\",\"Отдельный учёт пациентов с правами по координации ЕС: личный идентификационный номер и данные иностранной институции на рецептах\",\"Расширение и упорядочение рефундации редких («сиротских») лекарств, с новой многофакторной оценкой\",\"Уточнение данных в рецептах и отчётности аптек (коды болезней ICD‑10, номера документов, коды для координации ЕС и пр.)\"],\"affected_groups\":[\"Все застрахованные пациенты NFZ, включая иностранцев\",\"Иностранцы без номера PESEL, подающие заявки на индивидуальную рефундацию импортируемых лекарств/питания\",\"Пациенты, имеющие право на лечение по правилам координации ЕС (EHIC, S1 и др.)\",\"Аптеки и врачи, выписывающие рецепты иностранцам\"],\"practical_impact\":\"В повседневности у иностранцев с правом на NFZ изменится форма рецептов и заявлений: чаще потребуется указывать PESEL либо данные паспорта/личный номер по координации ЕС. Потенциально возрастает доступность дорогостоящих и редких лекарств за счёт упрощённых и быстрее проводимых процедур рефундации.\",\"effective_date\":\"Закон вступает в силу 1 января 2027 г., за исключением указанных статей, которые начнут действовать: через 14 дней, через 6 месяцев от дня оглашения, либо с 1 апреля 2027 г., 1 июля 2027 г. и 1 января 2028 г.\",\"confidence\":0.88,\"rationale\":\"Акт комплексно меняет правила рефундации и доступа к лекарствам в системе NFZ, что прямо затрагивает и иностранцев‑пациентов, но не меняет специальных иммиграционных режимов, поэтому это социальная сфера средней важности.\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":495380,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-09-30T11:32:33Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12398102/13129955/13129956/dokument782506.zip\",\"source_kind\":\"rcl\",\"revision\":1,\"text_sha256\":\"524157fa25a212119ccdf0eaa03ac7361481e0897a566f90548b9b3a13c50ed6\",\"law_sha256\":\"ba40ef050ccbcbe4812e32bd7981f599b3c5ccf103eeb19131577128dc57c845\",\"source_checked_at\":\"2026-09-30T11:32:33Z\"},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":{\"id\":12398102,\"title\":\"Projekt ustawy o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw\",\"applicant\":\"Minister Zdrowia\",\"wykaz_number\":\"UD187\",\"wykaz_url\":\"https://www.gov.pl/web/premier/wplip-rm\",\"created\":\"2025-05-22\",\"modified\":\"2026-09-30\",\"departments\":[\"zdrowie\"],\"keywords\":[\"OCHRONA ZDROWIA\"],\"status\":\"otwarty\",\"eu_note\":null,\"term_label\":\"X\",\"rm_number\":null,\"sejm_url\":null,\"print_number\":null,\"stages\":[{\"id\":13129917,\"number\":1,\"name\":\"Zgłoszenia lobbingowe\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"catalog_read\":false},{\"id\":13129918,\"number\":2,\"name\":\"Uzgodnienia\",\"state\":\"reached\",\"started\":null,\"ended\":null,\"modified\":\"2026-06-10\",\"folders\":[],\"catalog_read\":false},{\"id\":13129924,\"number\":3,\"name\":\"Konsultacje publiczne\",\"state\":\"reached\",\"started\":null,\"ended\":null,\"modified\":\"2026-06-10\",\"folders\":[{\"id\":13129925,\"name\":\"Projekt\",\"modified\":\"2025-05-22\",\"documents\":[{\"id\":718485,\"name\":\"Projekt\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12398102/13129924/13129925/dokument718485.pdf\",\"created\":\"2025-05-22\",\"author\":\"Minister Zdrowia\"},{\"id\":718486,\"name\":\"OSR\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12398102/13129924/13129925/dokument718486.docx\",\"created\":\"2025-05-22\",\"author\":\"Minister Zdrowia\"},{\"id\":718487,\"name\":\"Załącznik do OSR\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12398102/13129924/13129925/dokument718487.xlsx\",\"created\":\"2025-05-22\",\"author\":\"Minister Zdrowia\"}]},{\"id\":13129926,\"name\":\"Pisma kierujące projekt do konsultacji publicznych\",\"modified\":\"2025-05-22\",\"documents\":[{\"id\":718488,\"name\":\"Pismo - konsultacje\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12398102/13129924/13129926/dokument718488.pdf\",\"created\":\"2025-05-22\",\"author\":\"Minister Zdrowia\"}]},{\"id\":13129927,\"name\":\"Stanowiska zgłoszone w ramach konsultacji publicznych\",\"modified\":\"2026-06-10\",\"documen